            .args([
                "run",
                "--state-dir",
                store.state_dir.to_str().unwrap(),
                "--task-id",
                &task.id,
                "--run-id",
                &id,
            ])
            .kill_on_drop(true)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .unwrap();
        tokio::time::timeout(Duration::from_secs(10), async {
