        task.repository_path.parent()
    );
    assert_eq!(
        git(&task.repository_path, &["branch", "--show-current"]),
        "main"
    );
    assert_eq!(
        fs::read_to_string(task.repository_path.join("dirty.txt")).unwrap(),
        "keep me"
    );
}

