    assert_eq!(
        store
            .begin_run(
                &item,
                &execute,
                "/repo".into(),
                item.markdown.clone(),
                execute.fingerprint().unwrap()
            )
            .unwrap_err()
            .status,
        StatusCode::BAD_REQUEST
    );
    assert!(store.snapshot().unwrap().executions.is_empty());
}

