        Self {
            workspace_mode: WorkspaceMode::NewWorktree,
            workspace_path: PathBuf::new(),
            base_branch: default_base_branch(),
        }
    }
}

impl WorkspaceConfig {
    pub fn validate(&self) -> Result<()> {
        ensure!(
            !self
