    ch = os.read(0, 1)
    if not ch: break
    with open(log + '.raw', 'ab') as file: file.write(ch)
    if ch != b'\r':
        buf += ch
        continue
    text = buf.decode().replace('\x1b[200~', '').replace('\x1b[201~', '')
