fn push_codex_draft(turns: &mut Vec<TurnDraft>, draft: Option<TurnDraft>) {
    if let Some(draft) = draft.filter(|draft| draft.user.is_some()) {
        turns.push(draft);
    }
}

fn terminal_status(draft: &TurnDraft) -> &'static str {
    if draft.status != "in_progress" {
        draft.status
    } else if draft.final_message.is_some() {
        "completed"
    } else {
        "interrupted"
    }
}

fn settle_task(turns: &mut [TurnDraft], status: &'static str) {
    for turn in turns {
        if turn.status == "in_progress" {
            turn.status = status;
        }
    }
}

fn finish_task(
    turns: &mut Vec<TurnDraft>,
    current: &mut Option<TurnDraft>,
    task_start: &mut Option<usize>,
) {
    let status = current.as_ref().map_or("interrupted", terminal_status);
    let start = task_start.take().unwrap_or(turns.len());
    push_codex_draft(turns, current.take());
    settle_task(&mut turns[start..], status);
}

fn codex_candidate_line(line: &str) -> bool {
    // Match JSON tokens, allowing whitespace used by older transcript writers.
    [
        "\"event_msg\"",
        "\"response_item\"",
        "\"message\"",
        "\"history_mutation\"",
    ]
    .iter()
    .any(|token| line.contains(token))
}

fn codex_records(line: std::io::Result<String>) -> Vec<std::io::Result<Value>> {
    let line = match line {
        Ok(line) if codex_candidate_line(&line) => line,
        Ok(_) => return Vec::new(),
        Err(error) => return vec![Err(error)],
    };
    let Ok(mut record) = serde_json::from_str::<Value>(&line) else {
        return Vec::new();
    };
    if record.get("type").and_then(Value::as_str) != Some("history_mutation") {
        return vec![Ok(record)];
    }
    // Trae's canonical_v1 history stores response items in append mutations,
    // without legacy user/agent message projections. Context replacements are
    // model-history rewrites, not new messages in the conversation timeline.
    if record["payload"]["version"].as_u64() != Some(1)
        || record["payload"]["operation"].as_str() != Some("append")
    {
        return Vec::new();
    }
    let timestamp = record.get("timestamp").cloned();
    let Some(Value::Array(items)) = record["payload"].get_mut("items") else {
        return Vec::new();
    };
    std::mem::take(items)
        .into_iter()
        .map(|item| {
            Ok(serde_json::json!({
                "type": "response_item",
                "timestamp": timestamp,
                "payload": item,
            }))
        })
        .collect()
}

fn add_codex_user(
    turns: &mut Vec<TurnDraft>,
    current: &mut Option<TurnDraft>,
    fallback_id: &mut usize,
    message: SnapshotMessage,
    rank: u8,
    task_active: bool,
) {
    if current.as_ref().is_some_and(|draft| {
        draft
            .user
            .as_ref()
            .is_some_and(|user| user.text != message.text)
    }) {
        if !task_active && let Some(draft) = current.as_mut() {
            draft.status = terminal_status(draft);
        }
        push_codex_draft(turns, current.take());
    }
    ensure_draft(current, fallback_id).set_user(message, rank);
}

