fn parse_records(records: Vec<Value>) -> Vec<SnapshotTurn> {
    let (_directory, path) = write(
        &records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    );
    parse_codex_like(&path).unwrap()
}

