            json!({"type":"assistant","message":{"stop_reason":"tool_use","content":[{"type":"thinking","thinking":"PRIVATE_REASONING"},{"type":"tool_use","id":"tool-1","name":"Bash","input":{"command":"RAW_COMMAND"}}]}}),
