                    at: chrono::Utc::now(),
                    status: crate::RunStatus::Failed,
                    exit_code: None,
                    message: Some(format!("托管任务启动失败: {error:#}")),
                    duration_ms: 0,
                })?;
            }
        }
        result
    }
