#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Platform {
    Systemd,
    Launchd,
    Unsupported,
}

#[derive(Clone)]
pub struct Scheduler {
    pub platform: Platform,
    pub runner: PathBuf,
    pub directory: PathBuf,
    pub manager_command: PathBuf,
    pub dispatch_command: PathBuf,
}

#[derive(Serialize)]
pub struct SchedulerStatus {
    pub platform: Platform,
    pub ready: bool,
    pub message: Option<String>,
    pub timezone: String,
}

mod dispatch;
mod render;
mod sync;

impl Scheduler {
    pub fn new(home: &Path) -> Self {
        let runner = std::env::var_os("AOW_AUTOMATION_RUNNER")
            .map(PathBuf::from)
            .unwrap_or_else(|| home.join(".local/bin/aow-automation-runner"));
        let platform = if cfg!(target_os = "linux") {
            Platform::Systemd
        } else if cfg!(target_os = "macos") {
            Platform::Launchd
        } else {
            Platform::Unsupported
        };
        let directory = if platform == Platform::Launchd {
            home.join("Library/LaunchAgents")
        } else {
            std::env::var_os("XDG_CONFIG_HOME")
                .map(PathBuf::from)
                .unwrap_or_else(|| home.join(".config"))
                .join("systemd/user")
        };
        Self {
            platform,
            runner,
            directory,
            manager_command: if platform == Platform::Launchd {
                "launchctl".into()
            } else {
                "systemctl".into()
            },
            dispatch_command: if platform == Platform::Launchd {
                "launchctl".into()
            } else {
                "systemd-run".into()
            },
        }
    }

    async fn command(&self, executable: &Path, args: &[String]) -> Result<String> {
        let output = tokio::time::timeout(
            Duration::from_secs(20),
            Command::new(executable)
                .args(args)
                .stdin(Stdio::null())
                .kill_on_drop(true)
                .output(),
        )
        .await
        .context("系统定时器操作超时")??;
        ensure!(
            output.status.success(),
            "系统定时器操作失败: {}",
            String::from_utf8_lossy(&output.stderr)
                .chars()
                .take(2000)
                .collect::<String>()
        );
        Ok(String::from_utf8_lossy(&output.stdout).into_owned())
    }

    pub async fn status(&self) -> SchedulerStatus {
        let result = self.check_ready().await;
        SchedulerStatus {
            platform: self.platform,
            ready: result.is_ok(),
            message: result.err().map(|e| e.to_string()),
            timezone: chrono::Local::now().format("%Z (UTC%:z)").to_string(),
        }
    }

    async fn check_ready(&self) -> Result<()> {
        ensure!(
            self.platform != Platform::Unsupported,
