    pub(crate) fn repository_roots(&self) -> Result<Vec<PathBuf>, AowError> {
        Ok(self
            .lock()?
            .projects
            .iter()
            .map(|project| PathBuf::from(&project.registered_path))
            .collect())
    }

    pub(crate) fn in_memory() -> Self {
        Self {
