    pub(crate) fn run(&self, task_id: &str, run_id: &str) -> Result<Run> {
        self.store.get_task(task_id)?;
        self.store
            .read_run(task_id, run_id)?
            .context("执行记录尚未生成")
    }

    pub(crate) fn run_result(&self, run: &Run) -> Result<String> {
        self.store.read_run_result(run)
    }
}

