        .append(&RunEvent::AgentStarted {
            pid: 4242,
            command: vec![
                "/usr/local/bin/codex".into(),
                "exec".into(),
                "--json".into(),
            ],
        })
        .unwrap();
    journal
        .append(&RunEvent::Session {
            session_id: "native-session".into(),
