        "GET",
        &format!("{manual_path}/runs"),
        serde_json::Value::Null,
    )
    .await;
    assert_eq!(history[0]["variables"], run_detail["variables"]);
    assert_eq!(
        call(&router, "DELETE", &manual_path, serde_json::Value::Null)
            .await
