        "id":"12345678", "revision":99, "created_at":"2020-01-01T00:00:00Z", "updated_at":"2020-01-01T00:00:00Z",
        "name":"迁移任务", "prompt":"检查最近变更\n保留换行", "agent":"codex", "kind":"scheduled",
