+    fn mutate<T>(&self, change: impl FnOnce(&mut Document) -> Result<T>) -> Result<T> {
+        let mut state = self.lock()?;
+        let mut next = state.document.clone();
+        let result = change(&mut next)?;
+        next.revision += 1;
+        validate_document(&next)?;
