    assert!(bytes.starts_with(&prefix));
    assert_eq!(std::str::from_utf8(&bytes).unwrap().lines().count(), 2);
    assert_eq!(store.item(&item.id).unwrap().revision, item.revision);
    let updated = store
        .update(
