            .unwrap()
            .snapshot()
            .unwrap()
            .items
            .is_empty()
    );
    let status = std::process::Command::new("git")
        .args(["status", "--porcelain"])
        .current_dir(config.directory())
        .output()
        .unwrap();
    assert!(status.stdout.is_empty());
}

