    assert!(
        fixture
            .state
            .terminals
            .list(Some(&first.cwd))
            .await
            .unwrap()
            .tabs
            .is_empty()
    );
    for pane_id in [&first.pane_id, &second.pane_id] {
        assert!(
            fixture
                .state
                .terminals
                .inner
                .terminald
                .get(pane_id)
                .await
                .unwrap()
                .is_none()
        );
    }
    fixture.stop().await;
}

