pub(super) async fn attach_terminal_pane(
    State(state): State<AppState>,
    AxumPath((tab_id, pane_id)): AxumPath<(String, String)>,
    Query(query): Query<AttachQuery>,
    headers: HeaderMap,
    access: Option<axum::Extension<crate::auth::SessionAccess>>,
