    let live = directory.join("live.png");
    std::fs::write(&expired, b"expired").unwrap();
    std::fs::write(&live, b"live").unwrap();
    let now = SystemTime::now();
    std::fs::File::options()
        .write(true)
        .open(&expired)
        .unwrap()
        .set_times(
