                {rename?.tabId !== tab.id ? <button className="project-aow-tab-close" title={`关闭 ${tab.label}`} aria-label={`关闭 ${tab.label}`}
                  onClick={event => { event.stopPropagation(); run(() => onCloseTab(tab)); }}><X /></button> : null}
              </div>) : null}
            </div>
          </div>;
        })}
