    && typeof tab.id === 'string' && typeof tab.label === 'string' && isWorkspaceTabKind(tab.kind))
    .map(tab => ({ ...tab, targetId: tab.targetId ?? tab.id.slice(tab.id.indexOf(':') + 1),
      terminal: Array.isArray(tab.terminal?.panes) ? tab.terminal : undefined })) : [];
