+  try {
+    if (value === undefined) appLocalStorage.removeItem(`aow-inbox-draft:${key}`);
+    else appLocalStorage.setItem(`aow-inbox-draft:${key}`, JSON.stringify(value));
+  } catch { /* Draft remains in memory when browser storage is unavailable. */ }
+}

