  };

  const clearClipboardCopyTimer = () => {
    if (clipboardCopyTimerRef.current !== undefined) {
      window.clearTimeout(clipboardCopyTimerRef.current);
      clipboardCopyTimerRef.current = undefined;
    }
  };
