      },
      theme: {
        background: '#1e1e1e', foreground: '#cccccc', cursor: '#ffffff',
        selectionBackground: '#264f78', black: '#000000', brightBlack: '#666666',
        overviewRulerBorder: '#00000000',
      },
    });
