    let disposed = false;
    const clipboardProvider: IClipboardProvider = {
      readText(selection: ClipboardSelectionType) {
        if (!terminalCanMutate() || !clipboardPaneIsCurrent(/*requireTerminalFocus=*/ true)) return '';
