      renderEvent.dispose();
      cursorEvent.dispose();
      host.removeEventListener('focusin', focusEvent);
      terminal.dispose();
      terminalRef.current = undefined;
      fitRef.current = undefined;
      cancelPendingTerminalResize();
      clearClipboardCopyTimer();
    };
