          modified: diff.getModifiedEditor().getValue(),
          changes: diff.getLineChanges().map(({ charChanges, ...lines }) => lines),
          cached: monaco.editor.getModels().map(model => ({ path: model.uri.toString(), content: model.getValue() })),
        };
