    await dialog.getByRole('button', { name: '保存更改' }).click();
    await dialog.waitFor({ state: 'hidden' });
    assert.equal(saves[0].prompt_bindings.length, 2);
    await page.getByRole('button', { name: '编辑', exact: true }).click();
