  server: { host: '127.0.0.1', port: 0, proxy: {}, watch: { usePolling: true } } });
let browser;
const dragPaths = ['/workspace/demo', '/workspace/demo/目录 with spaces', "/workspace/demo/a'b $HOME;`whoami`.txt"];

try {
  await server.listen();
