    pub(in crate::aow) agent_type: AgentType,
    pub(in crate::aow) display_name: String,
    pub(in crate::aow) command: String,
    #[serde(default)]
    pub(in crate::aow) args: Vec<String>,
    #[serde(default)]
    pub(in crate::aow) env: BTreeMap<String, String>,
}

