impl AowManager {
    /// Registry metadata only; callers discover worktrees directly through Git.
    pub(super) fn persist_projects(&self, projects: &[StoredProject]) -> Result<(), AowError> {
        if let Some(path) = &self.inner.projects_path {
            self.save_configuration(
                path,
                &RegistryDocument {
                    version: REGISTRY_VERSION,
                    items: projects.to_vec(),
                },
            )?;
        }
        Ok(())
    }

    pub(super) fn persist_agents(&self, agents: &[StoredAgent]) -> Result<(), AowError> {
        if let Some(path) = &self.inner.agents_path {
            self.save_configuration(
                path,
                &RegistryDocument {
                    version: REGISTRY_VERSION,
                    items: agents.to_vec(),
                },
            )?;
        }
        Ok(())
    }

    pub(super) fn save_configuration<T: Serialize>(
        &self,
        path: &Path,
        document: &T,
    ) -> Result<(), AowError> {
        if let Some(config) = &self.inner.config {
            let relative = path
                .strip_prefix(config.directory())
                .map_err(|error| AowError::Invalid(error.to_string()))?;
            let mut bytes = serde_json::to_vec_pretty(document)?;
            bytes.push(b'\n');
            config
                .save(relative, &bytes)
                .map_err(AowError::Configuration)?;
        }
        Ok(())
    }
}

pub(super) fn load_registry<T>(path: &Path) -> Result<Vec<T>, AowError>
where
    T: for<'de> Deserialize<'de>,
{
    match std::fs::read(path) {
        Ok(bytes) => {
            let document: RegistryDocument<T> = serde_json::from_slice(&bytes)?;
            if document.version != REGISTRY_VERSION {
                return Err(AowError::Invalid(format!(
                    "unsupported AoW registry version {}",
                    document.version
                )));
            }
            Ok(document.items)
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(Vec::new()),
        Err(error) => Err(error.into()),
    }
}

pub(crate) fn atomic_save_document<T: Serialize>(
    path: &Path,
    document: &T,
) -> Result<(), AowError> {
    let parent = path.parent().ok_or_else(|| {
        AowError::Invalid(format!("registry path has no parent: {}", path.display()))
    })?;
    std::fs::create_dir_all(parent)?;
    let temporary = parent.join(format!(
        ".{}.{}.tmp",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("aow"),
        aow_id::new_id()
    ));
    let result = (|| {
        let bytes = serde_json::to_vec_pretty(document)?;
        let mut file = std::fs::OpenOptions::new()
            .create_new(true)
            .write(true)
            .mode(0o600)
            .open(&temporary)?;
        file.write_all(&bytes)?;
        file.write_all(b"\n")?;
        file.sync_all()?;
        drop(file);
        std::fs::rename(&temporary, path)?;
        Ok::<_, AowError>(())
    })();
    if result.is_err() {
        let _ = std::fs::remove_file(temporary);
    }
    result
}

use super::*;
use crate::operations::Spec;
use std::collections::HashSet;

pub(in crate::aow) async fn list_jobs(
    State(state): State<AppState>,
) -> Result<Json<Vec<RemovalJob>>, Response> {
    state
        .aow
        .inner
        .removals
        .lock()
        .map(|jobs| Json(jobs.clone()))
        .map_err(aow_response)
}

pub(in crate::aow) async fn submit_batch(
    State(state): State<AppState>,
    AxumPath(id): AxumPath<String>,
    Json(request): Json<BatchRequest>,
) -> Result<(StatusCode, Json<RemovalJob>), Response> {
    submit(state, id, request.items)
        .map(|job| (StatusCode::ACCEPTED, Json(job)))
        .map_err(aow_response)
}

pub(in crate::aow) fn submit(
    state: AppState,
    project_id: String,
    requests: Vec<RemovalRequest>,
) -> Result<RemovalJob, AowError> {
    if requests.is_empty() || requests.len() > 200 {
        return Err(AowError::Invalid("每次请选择 1～200 个 Worktree".into()));
    }
    let mut paths = HashSet::new();
    for request in &requests {
        let path = Path::new(&request.path);
        if !path.is_absolute()
            || request.path.len() > 4096
            || request.path.contains('\0')
            || path.components().any(|part| {
                matches!(
                    part,
                    std::path::Component::ParentDir | std::path::Component::CurDir
                )
            })
            || !paths.insert(request.path.clone())
        {
            return Err(AowError::Invalid("Worktree 路径无效或重复".into()));
        }
    }
    let job = RemovalJob {
        id: aow_id::new_id(),
        project_id,
        created_at: chrono::Utc::now().to_rfc3339(),
        finished_at: None,
        items: requests
            .into_iter()
            .map(|item| RemovalItem {
                path: item.path,
                force: item.force,
                status: RemovalStatus::Queued,
                error: None,
            })
            .collect(),
    };
    let project_lock;
    {
        // Same lock order as removing a Project. No Git scan or terminal daemon call
        // belongs in this request: all potentially slow work runs in the worker.
        let registry = state.aow.lock()?;
        if !registry
            .projects
            .iter()
            .any(|project| project.id == job.project_id)
        {
            return Err(AowError::ProjectNotFound(job.project_id.clone()));
        }
        let removals = &state.aow.inner.removals;
        let mut jobs = removals.lock()?;
        if jobs
            .iter()
            .flat_map(|job| &job.items)
            .any(|item| paths.contains(&item.path) && item.status.active())
        {
            return Err(AowError::RemovalConflict(
                "所选 Worktree 已在清理队列中".into(),
            ));
        }
        project_lock = removals.project_lock(&job.project_id)?;
        let mut next = jobs.clone();
        // Bound completed history while retaining every active task.
        let finished = next
            .iter()
            .filter(|job| job.items.iter().all(|item| !item.status.active()))
            .count();
        let mut discard = finished.saturating_sub(99);
        next.retain(|job| {
            if discard > 0 && job.items.iter().all(|item| !item.status.active()) {
                discard -= 1;
                false
            } else {
                true
            }
        });
        next.push(job.clone());
        *jobs = next;
        for item in &job.items {
            if let Err(error) = state.terminals.set_workspace_removing(&item.path, true) {
                tracing::error!(%error, path = %item.path, "failed to reserve workspace for removal");
            }
        }
    }
    let operation = state.operations.begin(Spec {
        id: job.id.clone(),
        kind: "worktree.remove",
        source: "web",
        title: "删除 Worktree".into(),
        project_id: Some(job.project_id.clone()),
        resource: None,
        total: Some(job.items.len()),
    });
    worker::spawn(state, job.clone(), operation, project_lock);
    Ok(job)
}

use super::*;

pub(in crate::aow) struct RemovalJobs {
    pub(super) jobs: Mutex<Vec<RemovalJob>>,
    pub(super) project_locks: Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
    pub(super) permits: tokio::sync::Semaphore,
}

impl RemovalJobs {
    pub fn in_memory() -> Self {
        Self {
            jobs: Mutex::new(Vec::new()),
            project_locks: Mutex::new(HashMap::new()),
            permits: tokio::sync::Semaphore::new(2),
        }
    }

    pub(super) fn lock(&self) -> Result<MutexGuard<'_, Vec<RemovalJob>>, AowError> {
        let mut jobs = self.jobs.lock().map_err(|_| AowError::Poisoned)?;
        // A short grace period lets clients consume final results. History lives
        // only in the shared operation log and never restores execution state.
        jobs.retain(|job| {
            job.finished_at
                .is_none_or(|at| at.elapsed() < std::time::Duration::from_secs(300))
        });
        Ok(jobs)
    }

    pub fn project_busy(&self, id: &str) -> Result<bool, AowError> {
        Ok(self
            .lock()?
            .iter()
            .any(|job| job.project_id == id && job.items.iter().any(|item| item.status.active())))
    }

    pub fn project_lock(&self, id: &str) -> Result<Arc<tokio::sync::Mutex<()>>, AowError> {
        Ok(self
            .project_locks
            .lock()
            .map_err(|_| AowError::Poisoned)?
            .entry(id.to_owned())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone())
    }

    pub(super) fn update(
        &self,
        id: &str,
        path: &str,
        status: RemovalStatus,
        error: Option<String>,
    ) -> Result<(), AowError> {
        let mut jobs = self.lock()?;
        let job = jobs
            .iter_mut()
            .find(|job| job.id == id)
            .ok_or_else(|| AowError::Invalid("清理任务不存在".into()))?;
        let item = job
            .items
            .iter_mut()
            .find(|item| item.path == path)
            .ok_or_else(|| AowError::Invalid("清理项目不存在".into()))?;
        item.status = status;
        item.error = error;
        if job.items.iter().all(|item| !item.status.active()) {
            job.finished_at = Some(std::time::Instant::now());
        }
        Ok(())
    }
}

