}

impl PasswordProvider {
    pub fn new(state_dir: &Path) -> Self {
        Self {
            credentials_path: state_dir.join(CREDENTIALS_FILE),
        }
    }

    fn configuration(&self) -> Result<Credentials, HttpError> {
        let path = &self.credentials_path;
        let contents = match std::fs::read_to_string(path) {
            Ok(contents) => contents,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Err(account_not_configured());
            }
            Err(error) => {
                return Err(configuration_error(format!(
                    "无法读取账户配置 {}：{error}",
                    path.display()
                )));
            }
        };
        match serde_json::from_str::<Credentials>(&contents) {
            Ok(credentials)
                if credentials.version == 1
                    && valid_username(&credentials.username)
                    && decode_hex::<16>(&credentials.salt).is_some()
                    && decode_hex::<32>(&credentials.password_hash).is_some() =>
            {
                Ok(credentials)
            }
            _ => Err(configuration_error(format!(
                "账户配置 {} 无效；请重新运行 `aow account`",
                path.display()
            ))),
        }
    }
}

impl LoginProvider for PasswordProvider {
    fn id(&self) -> &'static str {
        METHOD
    }
    fn label(&self) -> &'static str {
        "账号密码"
    }
    fn check_configured(&self) -> Result<(), HttpError> {
        self.configuration().map(|_| ())
    }

    fn authenticate(&self, credentials: &Value) -> Result<VerifiedIdentity, HttpError> {
        let request: PasswordCredentials =
            serde_json::from_value(credentials.clone()).map_err(|_| {
                HttpError::new(
                    StatusCode::UNPROCESSABLE_ENTITY,
                    "invalid_credentials",
                    "请输入账号和密码",
                    None,
                )
            })?;
        if !valid_username(&request.username)
            || request.password.is_empty()
            || request.password.len() > 1024
        {
            return Err(HttpError::new(
                StatusCode::BAD_REQUEST,
                "invalid_credentials",
                "请输入有效的账号和密码",
                None,
            ));
        }
        let configured = self.configuration()?;
        let salt = decode_hex::<16>(&configured.salt).expect("validated salt");
        let hash = decode_hex::<32>(&configured.password_hash).expect("validated hash");
        let password_matches = pbkdf2::verify(
            pbkdf2::PBKDF2_HMAC_SHA256,
            PASSWORD_ITERATIONS,
            &salt,
            request.password.as_bytes(),
            &hash,
        )
        .is_ok();
        if !password_matches || request.username != configured.username {
            return Err(HttpError::new(
                StatusCode::UNAUTHORIZED,
                "invalid_credentials",
                "账号或密码不正确",
                None,
            ));
        }
        Ok(configured.identity())
    }

    fn validate_session(&self, identity: &VerifiedIdentity) -> Result<bool, HttpError> {
        Ok(self.configuration()?.identity() == *identity)
    }
}

fn configuration_error(message: String) -> HttpError {
    HttpError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "account_configuration_invalid",
        message,
        None,
    )
}

fn valid_username(username: &str) -> bool {
    !username.is_empty()
        && username.len() <= 256
        && !username
            .chars()
            .any(|character| character.is_whitespace() || character.is_control())
}

fn decode_hex<const N: usize>(value: &str) -> Option<[u8; N]> {
    if value.len() != N * 2 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return None;
    }
    let mut bytes = [0; N];
    for (index, byte) in bytes.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&value[index * 2..index * 2 + 2], 16).ok()?;
    }
    Some(bytes)
}

fn account_not_configured() -> HttpError {
    HttpError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "account_not_configured",
        "AoW 尚未设置登录账户；请在服务器上运行 `aow account`",
        None,
    )
}

#[cfg(test)]
pub(crate) fn write_credentials(directory: &Path, username: &str, password: &str) {
    let salt = Uuid::new_v4();
    let mut hash = [0; 32];
    pbkdf2::derive(
        pbkdf2::PBKDF2_HMAC_SHA256,
        PASSWORD_ITERATIONS,
        salt.as_bytes(),
        password.as_bytes(),
        &mut hash,
    );
    let credentials = Credentials {
        version: 1,
        username: username.into(),
        salt: salt.simple().to_string(),
        password_hash: hash.iter().map(|byte| format!("{byte:02x}")).collect(),
    };
    std::fs::write(
        directory.join(CREDENTIALS_FILE),
        serde_json::to_vec(&credentials).unwrap(),
    )
    .unwrap();
}

use serde_json::Value;

use crate::HttpError;

/// Providers return an identity, never a browser token. `revision` is opaque
/// to the shared session store and changes when this identity is revoked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct VerifiedIdentity {
    pub subject: String,
    pub revision: String,
}

/// A login method owns credential verification and its revocation rules.
/// Sessions, cookies, and access policy are handled by the shared auth module.
pub(super) trait LoginProvider: Send + Sync {
    fn id(&self) -> &'static str;
    fn label(&self) -> &'static str;
    fn check_configured(&self) -> Result<(), HttpError>;
    fn authenticate(&self, credentials: &Value) -> Result<VerifiedIdentity, HttpError>;
    fn validate_session(&self, identity: &VerifiedIdentity) -> Result<bool, HttpError>;
}

use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

use tokio_util::sync::CancellationToken;
use uuid::Uuid;

use super::provider::VerifiedIdentity;
use crate::HttpError;

pub(super) const ABSOLUTE_TIMEOUT: Duration = Duration::from_secs(12 * 60 * 60);
const IDLE_TIMEOUT: Duration = Duration::from_secs(30 * 60);
const MAX_SESSIONS: usize = 64;

#[derive(Clone)]
pub(super) struct Session {
    pub method: &'static str,
    pub identity: VerifiedIdentity,
    pub cancelled: CancellationToken,
    created: Instant,
    last_active: Instant,
}

impl Session {
    fn expired(&self, now: Instant) -> bool {
        now.duration_since(self.created) >= ABSOLUTE_TIMEOUT
            || now.duration_since(self.last_active) >= IDLE_TIMEOUT
    }
}

#[derive(Clone, Default)]
pub(super) struct Sessions(Arc<Mutex<HashMap<String, Session>>>);

impl Sessions {
    pub fn create(
        &self,
        method: &'static str,
        identity: VerifiedIdentity,
    ) -> Result<String, HttpError> {
        let now = Instant::now();
        let mut sessions = self
            .0
            .lock()
            .map_err(|_| HttpError::internal("登录会话锁不可用"))?;
        Self::prune(&mut sessions, now);
        if sessions.len() >= MAX_SESSIONS {
            let oldest = sessions
                .iter()
                .min_by_key(|(_, session)| session.created)
                .map(|(token, _)| token.clone())
                .expect("nonempty session store");
            if let Some(session) = sessions.remove(&oldest) {
                session.cancelled.cancel();
            }
        }
        let token = Uuid::new_v4().simple().to_string();
        sessions.insert(
            token.clone(),
            Session {
                method,
                identity,
                cancelled: CancellationToken::new(),
                created: now,
                last_active: now,
            },
        );
        Ok(token)
    }

    pub fn get(&self, token: &str, touch: bool) -> Result<Option<Session>, HttpError> {
        let now = Instant::now();
        let mut sessions = self
            .0
            .lock()
            .map_err(|_| HttpError::internal("登录会话锁不可用"))?;
        Self::prune(&mut sessions, now);
        Ok(sessions.get_mut(token).map(|session| {
            if touch {
                session.last_active = now;
            }
            session.clone()
        }))
    }

    pub fn revoke(&self, token: &str) -> Result<(), HttpError> {
        if let Some(session) = self
            .0
            .lock()
            .map_err(|_| HttpError::internal("登录会话锁不可用"))?
            .remove(token)
        {
            session.cancelled.cancel();
        }
        Ok(())
    }

    fn prune(sessions: &mut HashMap<String, Session>, now: Instant) {
        sessions.retain(|_, session| {
            if session.expired(now) {
                session.cancelled.cancel();
                false
            } else {
                true
            }
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn identity() -> VerifiedIdentity {
        VerifiedIdentity {
            subject: "user".into(),
            revision: "1".into(),
        }
    }

    #[test]
    fn absolute_and_idle_expiry_cancel_connections_and_cannot_be_refreshed() {
        for absolute in [false, true] {
            let sessions = Sessions::default();
            let token = sessions.create("test", identity()).unwrap();
            let cancelled = sessions.get(&token, false).unwrap().unwrap().cancelled;
            {
                let mut entries = sessions.0.lock().unwrap();
                let entry = entries.get_mut(&token).unwrap();
                if absolute {
                    entry.created -= ABSOLUTE_TIMEOUT;
                } else {
                    entry.last_active -= IDLE_TIMEOUT;
                }
            }
            assert!(sessions.get(&token, true).unwrap().is_none());
            assert!(cancelled.is_cancelled());
        }
    }

    #[test]
    fn passive_checks_do_not_extend_idle_lifetime_and_store_is_bounded() {
        let sessions = Sessions::default();
        let token = sessions.create("test", identity()).unwrap();
        let before = Instant::now() - Duration::from_secs(60);
        sessions
            .0
            .lock()
            .unwrap()
            .get_mut(&token)
            .unwrap()
            .last_active = before;
        assert_eq!(
            sessions.get(&token, false).unwrap().unwrap().last_active,
            before
        );
        assert!(sessions.get(&token, true).unwrap().unwrap().last_active > before);
        let cancelled = sessions.get(&token, false).unwrap().unwrap().cancelled;
        for _ in 0..MAX_SESSIONS {
            sessions.create("test", identity()).unwrap();
        }
        assert!(cancelled.is_cancelled());
        assert_eq!(sessions.0.lock().unwrap().len(), MAX_SESSIONS);
        let token = sessions.create("test", identity()).unwrap();
        let cancelled = sessions.get(&token, false).unwrap().unwrap().cancelled;
        sessions.revoke(&token).unwrap();
        assert!(cancelled.is_cancelled());
        assert!(sessions.get(&token, false).unwrap().is_none());
    }
}

