#[tokio::test]
async fn corrupt_records_do_not_stop_delivery_and_repaired_records_are_retried() {
    let root = tempfile::tempdir().unwrap();
    let store = Arc::new(Store::new(root.path().into()).unwrap());
    let task = task();
    let mut originals = Vec::new();
    for id in ["bad-header", "bad-body", "bad-state", "healthy"] {
        finish(&mut start(&store, &task, id), RunStatus::Failed);
        let path = store.run_path(&task.id, id).unwrap().join("events.jsonl");
        let bytes = fs::read(&path).unwrap();
        if id == "bad-header" {
            fs::write(&path, b"invalid-json\n").unwrap();
            originals.push((path, bytes));
        } else if id == "bad-body" {
            let mut broken = bytes.clone();
            broken.extend_from_slice(b"{\"type\":\"workspace\",{\"type\":\"finished\"}\n");
            fs::write(&path, broken).unwrap();
            originals.push((path, bytes));
        } else if id == "bad-state" {
            let path = path.with_file_name(STATE_FILE);
            save(
                &path,
                DeliveryStatus::Sent,
                Some("already-sent".into()),
                None,
            )
            .unwrap();
            let bytes = fs::read(&path).unwrap();
            fs::write(&path, b"{\"status\":").unwrap();
            originals.push((path, bytes));
        }
    }
    let warnings = Warnings::default();
    let delivered = std::sync::Mutex::new(Vec::new());
    for _ in 0..12 {
        super::poll(
            store.clone(),
            |run, _, _| {
                delivered.lock().unwrap().push(run.id);
                async { Ok(true) }
            },
            true,
            warnings.clone(),
        )
        .await
        .unwrap();
    }
    assert_eq!(*delivered.lock().unwrap(), ["healthy"]);
    assert!(store.read_run(&task.id, "bad-header").is_err());
    assert!(store.read_run(&task.id, "bad-body").is_err());
    for (path, bytes) in originals {
        fs::write(path, bytes).unwrap();
    }
    for _ in 0..2 {
        super::poll(
            store.clone(),
            |run, _, _| {
                delivered.lock().unwrap().push(run.id);
                async { Ok(true) }
            },
            true,
            warnings.clone(),
        )
        .await
        .unwrap();
    }
    assert_eq!(
        *delivered.lock().unwrap(),
        ["healthy", "bad-body", "bad-header"]
    );
    assert_eq!(
        state(&store, "bad-state").delivery_id.as_deref(),
        Some("already-sent")
    );
}

use std::{
    collections::BTreeSet,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

const INTERVAL: Duration = Duration::from_secs(60);
const MAX_DETAILS: usize = 5;

/// One bounded, memory-only budget for the observer, including persistence and
/// cleanup errors. Tracking one entry per damaged file would itself be unbounded.
#[derive(Clone, Default)]
pub(in crate::automations) struct Warnings(Arc<Mutex<Window>>);

#[derive(Default)]
struct Window {
    started: Option<Instant>,
    details: BTreeSet<(&'static str, String, String)>,
    suppressed: u64,
}

impl Window {
    fn rollover(&mut self, now: Instant) -> u64 {
        if self
            .started
            .is_some_and(|start| now.duration_since(start) < INTERVAL)
        {
            return 0;
        }
        self.started = Some(now);
        self.details.clear();
        std::mem::take(&mut self.suppressed)
    }

    fn detail(&mut self, operation: &'static str, task_id: &str, run_id: &str) -> bool {
        if self.details.len() < MAX_DETAILS
            && self
                .details
                .insert((operation, task_id.into(), run_id.into()))
        {
            true
        } else {
            self.suppressed = self.suppressed.saturating_add(1);
            false
        }
    }
}

impl Warnings {
    pub(in crate::automations) fn flush(&self) {
        let suppressed = self.0.lock().unwrap().rollover(Instant::now());
        if suppressed > 0 {
            tracing::warn!(
                suppressed,
                "automation observer warnings suppressed in the last minute"
            );
        }
    }

    pub(in crate::automations) fn report(
        &self,
        operation: &'static str,
        task_id: &str,
        run_id: &str,
        error: &anyhow::Error,
    ) {
        self.flush();
        if self.0.lock().unwrap().detail(operation, task_id, run_id) {
            tracing::warn!(operation, task_id, run_id, error = %format_args!("{error:#}"), "automation observer failed");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn emitted_warnings_include_root_causes_and_summarize_suppression() {
        let log = tempfile::NamedTempFile::new().unwrap();
        let subscriber = tracing_subscriber::fmt()
            .with_ansi(false)
            .without_time()
            .with_writer(log.reopen().unwrap())
            .finish();
        let warnings = Warnings::default();
        let error = anyhow::Error::new(std::io::Error::from_raw_os_error(libc::ENOSPC))
            .context("cannot persist notification state");
        tracing::subscriber::with_default(subscriber, || {
            for _ in 0..12 {
                for run in 0..390 {
                    warnings.report("inspect run", "task", &run.to_string(), &error);
                }
            }
            warnings.0.lock().unwrap().started = Some(Instant::now() - INTERVAL);
            warnings.flush();
            warnings.flush();
        });
        let output = std::fs::read_to_string(log.path()).unwrap();
        assert_eq!(output.matches("automation observer failed").count(), 5);
        assert_eq!(output.matches("warnings suppressed").count(), 1);
        assert!(output.contains("suppressed=4675"));
        assert!(output.contains("cannot persist notification state"));
        assert!(output.contains(&error.root_cause().to_string()));
    }

    #[test]
    fn thousands_of_failures_share_a_bounded_budget_and_summary() {
        let now = Instant::now();
        let mut window = Window::default();
        assert_eq!(window.rollover(now), 0);
        let mut details = 0;
        for round in 0..12 {
            assert_eq!(window.rollover(now + Duration::from_secs(round * 5)), 0);
            for run in 0..390 {
                details += usize::from(window.detail("inspect", "task", &run.to_string()));
            }
        }
        assert_eq!(details, 5);
        assert_eq!(window.details.len(), 5);
        // Flush also works after recovery, without needing another failure.
        assert_eq!(window.rollover(now + INTERVAL), 4675);
        assert_eq!(window.rollover(now + INTERVAL), 0);
        assert!(window.detail("inspect", "task", "0"));
        assert!(!window.detail("inspect", "task", "0"));
        assert!(window.detail("persist", "task", "0"));
    }
}

use super::*;
use aow_automations::{
    RunEvent, RunStatus, runner::initial_run, scheduler::Platform, store::new_run_id,
};
use axum::{
    body::{Body, to_bytes},
    http::Request,
};
use std::{fs, os::unix::fs::PermissionsExt};
use tower::ServiceExt;

async fn call(
    router: &Router,
    method: &str,
    path: &str,
    body: serde_json::Value,
) -> (StatusCode, serde_json::Value) {
    let response = router
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(if body.is_null() {
                    Body::empty()
                } else {
                    Body::from(body.to_string())
                })
                .unwrap(),
        )
        .await
        .unwrap();
    let status = response.status();
    let bytes = to_bytes(response.into_body(), 1_000_000).await.unwrap();
    (
        status,
        if bytes.is_empty() {
            serde_json::Value::Null
        } else {
            serde_json::from_slice(&bytes).unwrap()
        },
    )
}

async fn call_text(router: &Router, path: &str) -> (StatusCode, String) {
    let response = router
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri(path)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let status = response.status();
    let bytes = to_bytes(response.into_body(), 5_000_000).await.unwrap();
    (status, String::from_utf8(bytes.to_vec()).unwrap())
}

