pub(crate) static PROCESS_HOME: LazyLock<PathBuf> = LazyLock::new(process_home);
pub(super) const PATH_SEGMENT_ENCODE_SET: &AsciiSet = &CONTROLS
    .add(b' ')
    .add(b'"')
    .add(b'#')
    .add(b'%')
    .add(b'/')
    .add(b'<')
    .add(b'>')
    .add(b'?')
    .add(b'`')
    .add(b'{')
    .add(b'}');

pub(super) fn decode_absolute(path: &str) -> Result<PathBuf, HttpError> {
    // Axum's Path extractor has already percent-decoded and UTF-8 validated the value.
    // Decoding it again would turn a literal filename such as `%20.txt` into a space.
    let path = Path::new("/").join(path.trim_start_matches('/'));
    Ok(path)
}

#[cfg(unix)]
fn process_home() -> PathBuf {
    // SAFETY: Called once through LazyLock; pw_dir is copied before returning.
    unsafe {
        let account = libc::getpwuid(libc::geteuid());
        if !account.is_null() && !(*account).pw_dir.is_null() {
            return PathBuf::from(
                CStr::from_ptr((*account).pw_dir)
                    .to_string_lossy()
                    .into_owned(),
            );
        }
    }
    PathBuf::from("/")
}

#[cfg(not(unix))]
fn process_home() -> PathBuf {
    std::env::var_os("USERPROFILE")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/"))
}

pub(crate) fn encode_absolute(path: &str) -> String {
    path.split('/')
        .map(|component| utf8_percent_encode(component, PATH_SEGMENT_ENCODE_SET).to_string())
        .collect::<Vec<_>>()
        .join("/")
}

pub(crate) fn escape_html(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('\"', "&quot;")
        .replace('\'', "&#39;")
}

use std::{io::SeekFrom, path::PathBuf};

use aow_filesystem::open_file;
use axum::{
    body::Body,
    extract::Path as AxumPath,
    http::{
        HeaderMap, HeaderValue, StatusCode,
        header::{
            ACCEPT_RANGES, CACHE_CONTROL, CONTENT_DISPOSITION, CONTENT_LENGTH, CONTENT_RANGE,
            CONTENT_TYPE, RANGE,
        },
    },
    response::Response,
};
use percent_encoding::utf8_percent_encode;
use tokio::io::{AsyncReadExt, AsyncSeekExt};
use tokio_util::io::ReaderStream;

use super::paths::{PATH_SEGMENT_ENCODE_SET, decode_absolute};
use crate::HttpError;

pub(crate) async fn raw_file(
    AxumPath(path): AxumPath<String>,
    headers: HeaderMap,
) -> Result<Response, HttpError> {
    let path = decode_absolute(&path)?;
    raw_response(path, headers, false).await
}

pub(super) async fn raw_response(
    path: PathBuf,
    headers: HeaderMap,
    attachment: bool,
) -> Result<Response, HttpError> {
    let (mut file, metadata) = open_file(&path).await?;
    let size = metadata.len();
    let content_type = mime_guess::from_path(&path)
        .first_or_octet_stream()
        .to_string();
    let range = headers.get(RANGE).and_then(|value| value.to_str().ok());
    let (start, end, status) = match range {
        Some(value) => {
            let (start, end) = parse_range(value, size)?;
            (start, end, StatusCode::PARTIAL_CONTENT)
        }
        None => (0, size.saturating_sub(1), StatusCode::OK),
    };
    let length = if size == 0 { 0 } else { end - start + 1 };
    file.seek(SeekFrom::Start(start)).await?;
    let stream = ReaderStream::new(file.take(length));
    let body = Body::from_stream(stream);
    let mut response = Response::new(body);
    *response.status_mut() = status;
    let response_headers = response.headers_mut();
    response_headers.insert(ACCEPT_RANGES, HeaderValue::from_static("bytes"));
    response_headers.insert(CONTENT_TYPE, HeaderValue::from_str(&content_type).unwrap());
    // Files are untrusted content, even when the reader is authenticated.
    // Restrict inline rendering and sandbox documents opened directly as well
    // as in an iframe; HttpOnly alone cannot prevent same-origin API calls.
    response_headers.insert(
        "x-content-type-options",
        HeaderValue::from_static("nosniff"),
    );
    response_headers.insert(CACHE_CONTROL, HeaderValue::from_static("no-store"));
    let safe_inline = matches!(
        content_type.as_str(),
        "text/plain"
            | "application/pdf"
            | "image/png"
            | "image/jpeg"
            | "image/gif"
            | "image/webp"
            | "image/avif"
            | "image/bmp"
            | "image/x-icon"
            | "image/vnd.microsoft.icon"
            | "audio/mpeg"
            | "audio/ogg"
            | "audio/wav"
            | "audio/mp4"
            | "video/mp4"
            | "video/webm"
            | "video/ogg"
    );
    // PDF viewers are browser plugins and cannot run in a sandboxed document.
    // Only allow known inert media types inline; sandbox all other file types.
    if !safe_inline {
        response_headers.insert(
            "content-security-policy",
            HeaderValue::from_static("sandbox; default-src 'none'"),
        );
    }
    if attachment || !safe_inline {
        let filename = path.file_name().unwrap_or_default().to_string_lossy();
        response_headers.insert(
            CONTENT_DISPOSITION,
            HeaderValue::from_str(&format!(
                "attachment; filename*=UTF-8''{}",
                utf8_percent_encode(&filename, PATH_SEGMENT_ENCODE_SET)
            ))
            .unwrap(),
        );
    }
    response_headers.insert(
        CONTENT_LENGTH,
        HeaderValue::from_str(&length.to_string()).unwrap(),
    );
    if status == StatusCode::PARTIAL_CONTENT {
        response_headers.insert(
            CONTENT_RANGE,
            HeaderValue::from_str(&format!("bytes {start}-{end}/{size}")).unwrap(),
        );
    }
    Ok(response)
}

fn parse_range(value: &str, size: u64) -> Result<(u64, u64), HttpError> {
    if size == 0 || !value.starts_with("bytes=") || value.contains(',') {
        return Err(HttpError::range_not_satisfiable(size));
    }
    let (start, end) = value[6..]
        .split_once('-')
        .ok_or_else(|| HttpError::range_not_satisfiable(size))?;
    let (start, end) = if start.is_empty() {
        let suffix = end
            .parse::<u64>()
            .map_err(|_| HttpError::range_not_satisfiable(size))?;
        let suffix = suffix.min(size);
        (size - suffix, size - 1)
    } else {
        let start = start
            .parse::<u64>()
            .map_err(|_| HttpError::range_not_satisfiable(size))?;
        let end = if end.is_empty() {
            size - 1
        } else {
            end.parse::<u64>()
                .map_err(|_| HttpError::range_not_satisfiable(size))?
                .min(size - 1)
        };
        (start, end)
    };
    if start >= size || start > end {
        return Err(HttpError::range_not_satisfiable(size));
    }
    Ok((start, end))
}

#[cfg(test)]
mod tests {
    use super::parse_range;

    #[test]
    fn parses_byte_ranges() {
        assert_eq!(parse_range("bytes=2-5", 10).unwrap(), (2, 5));
        assert_eq!(parse_range("bytes=7-", 10).unwrap(), (7, 9));
        assert_eq!(parse_range("bytes=-3", 10).unwrap(), (7, 9));
        assert!(parse_range("bytes=10-11", 10).is_err());
    }
}

