#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct LabelsUpdate {
    pub expected_revision: u64,
    pub labels: Vec<Label>,
}
#[derive(Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Execute {
    pub expected_revision: u64,
    pub request_key: String,
    pub agent: String,
    #[serde(default)]
    pub append_prompt: String,
    #[serde(flatten)]
    pub workspace: aow_workspaces::WorkspaceConfig,
}

fn existing_workspace_mode() -> aow_workspaces::WorkspaceMode {
    aow_workspaces::WorkspaceMode::Existing
}

impl Execute {
    pub(super) fn fingerprint(&self) -> Result<String, serde_json::Error> {
        serde_json::to_vec(self).map(|bytes| format!("{:x}", md5::compute(bytes)))
    }

    pub(super) fn final_task(&self, requirement: &str) -> String {
        if self.append_prompt.is_empty() {
            requirement.to_owned()
        } else {
            format!("{requirement}\n\n{}", self.append_prompt)
        }
    }
}

use super::model::{Comment, Document, Item, Label, Run, RunPhase};
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize, de::DeserializeOwned};
use std::{
    collections::{BTreeMap, HashSet},
    fs,
    io::Write,
    os::unix::fs::{DirBuilderExt, OpenOptionsExt},
    path::{Path, PathBuf},
};

// Keep list metadata alongside labels so each requirement has only two files.
#[derive(Serialize, Deserialize)]
struct Registry {
    version: u32,
    revision: u64,
    labels: Vec<Label>,
    order: Vec<String>,
    captures: BTreeMap<String, (String, String)>,
}

pub(super) struct Persistence {
    pub config: aow_config::ConfigRepository,
    pub runs: PathBuf,
}
impl Persistence {
    pub fn open(state: &Path) -> Result<(Self, Document, Vec<Run>)> {
        let config = aow_config::ConfigRepository::initialize(state)?;
        let path = state
            .join("inbox")
            .join(config.selection().config_id)
            .join("executions.json");
        let persistence = Self { config, runs: path };
        let document = if persistence
            .config
            .directory()
            .join("inbox/labels.json")
            .try_exists()?
        {
            persistence.document()?
        } else {
            let document = Document::default();
            persistence.save_document(&document)?;
            document
        };
        let mut runs: Vec<Run> = read(&persistence.runs)?;
        let mut changed = false;
        for run in &mut runs {
            if run.phase == RunPhase::Starting {
                run.phase = RunPhase::Interrupted;
                run.error =
                    Some("服务已重启，执行结果待确认；请先检查终端，再决定是否重新执行。".into());
                changed = true;
            }
        }
        if changed {
            write(&persistence.runs, &runs)?;
        }
        Ok((persistence, document, runs))
    }

    pub fn document(&self) -> Result<Document> {
        let root = self.config.directory().join("inbox");
        ensure!(
            !root.is_symlink() && !root.join("requirements").is_symlink(),
            "Inbox directory cannot be a symlink"
        );
        let registry: Registry = read_required(&root.join("labels.json"))?;
        ensure!(registry.version == 1, "Unsupported Inbox data version");
        let mut items = BTreeMap::new();
        for directory in requirement_directories(&root.join("requirements/active"))? {
            let item: Item = read_required(&directory.join("requirement.json"))?;
            ensure!(
                directory.file_name().and_then(|s| s.to_str()) == Some(item.id.as_str()),
                "Inbox directory and requirement ID differ"
            );
            items.insert(item.id.clone(), item);
        }
        let mut ordered = Vec::new();
        let mut seen = HashSet::new();
        for id in registry.order {
            ensure!(seen.insert(id.clone()), "Duplicate Inbox order ID");
            // Directory moves determine deletion; tolerate a stale order after interruption.
            if let Some(item) = items.remove(&id) {
                ordered.push(item);
            }
        }
        ordered.extend(items.into_values());
        let document = Document {
            version: registry.version,
            revision: registry.revision,
            labels: registry.labels,
            items: ordered,
            captures: registry.captures,
        };
        super::store::validate_document(&document).map_err(|e| anyhow::anyhow!(e.body.message))?;
        Ok(document)
    }

    pub fn save_document(&self, document: &Document) -> Result<()> {
        self.config
            .update_directory(Path::new("inbox"), |root| save_document(root, document))
    }

    pub fn comments(&self, id: &str) -> Result<Vec<Comment>> {
        read_comments(
            &self
                .config
                .directory()
                .join("inbox/requirements/active")
                .join(id)
                .join("comments.jsonl"),
        )
    }

    pub fn append_comment(&self, id: &str, comment: &Comment) -> Result<()> {
        self.config.update_directory(Path::new("inbox"), |root| {
            let directory = root.join("requirements/active").join(id);
            ensure!(
                directory.join("requirement.json").is_file(),
                "Requirement no longer exists"
            );
            let path = directory.join("comments.jsonl");
            let previous = read_comments(&path)?;
            // A durable append followed by a failed Git commit is retried without duplication.
            if previous.iter().any(|c| c.id == comment.id) {
                return Ok(());
            }
            let mut bytes = serde_json::to_vec(comment)?;
            bytes.push(b'\n');
            if fs::read(&path)?.last().is_some_and(|byte| *byte != b'\n') {
                bytes.insert(0, b'\n');
            }
            let mut file = fs::OpenOptions::new()
                .append(true)
                .custom_flags(libc::O_NOFOLLOW)
                .open(&path)?;
            let length = file.metadata()?.len();
            if let Err(error) = file.write_all(&bytes).and_then(|()| file.sync_all()) {
                file.set_len(length)?;
                file.sync_all()?;
                return Err(error.into());
            }
            Ok(())
        })
    }
}

fn requirement_directories(path: &Path) -> Result<Vec<PathBuf>> {
    let mut directories = Vec::new();
    if !path.try_exists()? {
        return Ok(directories);
    }
    ensure!(!path.is_symlink(), "Inbox directory cannot be a symlink");
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        ensure!(
            entry.file_type()?.is_dir()
                && entry.file_name().to_str().is_some_and(aow_id::is_valid_id),
            "Invalid Inbox requirement directory: {}",
            entry.path().display()
        );
        directories.push(entry.path());
    }
    Ok(directories)
}

// Roll back filesystem errors across files; Git failures occur after this succeeds
// and intentionally preserve the durable data, matching ConfigRepository::save.
enum Undo {
    File(PathBuf, Option<Vec<u8>>),
    Directory(PathBuf),
    Move(PathBuf, PathBuf),
}
fn save_document(root: &Path, document: &Document) -> Result<()> {
    let active = root.join("requirements/active");
    let deleted = root.join("requirements/deleted");
    for path in [&active, &deleted] {
        fs::DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(path)?;
    }
    let mut undo = Vec::new();
    let result = (|| {
        let ids: HashSet<_> = document.items.iter().map(|item| item.id.as_str()).collect();
        for directory in requirement_directories(&active)? {
            let id = directory.file_name().unwrap().to_str().unwrap();
            if !ids.contains(id) {
                let destination = deleted.join(id);
                ensure!(
                    !destination.try_exists()?,
                    "Deleted requirement already exists: {id}"
                );
                fs::rename(&directory, &destination)?;
                undo.push(Undo::Move(destination, directory));
            }
        }
        for item in &document.items {
            let directory = active.join(&item.id);
            if !directory.try_exists()? {
                ensure!(
                    !deleted.join(&item.id).try_exists()?,
                    "Requirement is already deleted"
                );
                fs::DirBuilder::new().mode(0o700).create(&directory)?;
                undo.push(Undo::Directory(directory.clone()));
            }
            replace(
                &directory.join("requirement.json"),
                &serde_json::to_vec_pretty(item)?,
                &mut undo,
            )?;
            let comments = directory.join("comments.jsonl");
            if !comments.try_exists()? {
                replace(&comments, b"", &mut undo)?;
            }
        }
        let registry = Registry {
            version: document.version,
            revision: document.revision,
            labels: document.labels.clone(),
            order: document.items.iter().map(|item| item.id.clone()).collect(),
            captures: document.captures.clone(),
        };
        replace(
            &root.join("labels.json"),
            &serde_json::to_vec_pretty(&registry)?,
            &mut undo,
        )?;
        fs::File::open(&active)?.sync_all()?;
        fs::File::open(&deleted)?.sync_all()?;
        Ok(())
    })();
    if result.is_err() {
        for operation in undo.into_iter().rev() {
            match operation {
                Undo::File(path, Some(bytes)) => write_bytes(&path, &bytes)?,
                Undo::File(path, None) => match fs::remove_file(path) {
                    Ok(()) => {}
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                    Err(error) => return Err(error.into()),
                },
                Undo::Directory(path) => fs::remove_dir(path)?,
                Undo::Move(source, destination) => fs::rename(source, destination)?,
            }
        }
    }
    result
}
fn replace(path: &Path, bytes: &[u8], undo: &mut Vec<Undo>) -> Result<()> {
    let previous = match fs::read(path) {
        Ok(previous) if previous == bytes => return Ok(()),
        Ok(previous) => Some(previous),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => return Err(error.into()),
    };
    undo.push(Undo::File(path.to_path_buf(), previous));
    write_bytes(path, bytes)
}

fn read_comments(path: &Path) -> Result<Vec<Comment>> {
    ensure!(!path.is_symlink(), "Inbox comments cannot be a symlink");
    let text = fs::read_to_string(path)
        .with_context(|| format!("Cannot read Inbox comments: {}", path.display()))?;
    let mut comments = Vec::new();
    let mut ids = HashSet::new();
    let mut requests = HashSet::new();
    for (index, line) in text.lines().enumerate() {
        let comment: Comment = serde_json::from_str(line)
            .with_context(|| format!("Invalid Inbox comment: {}:{}", path.display(), index + 1))?;
        super::store::validate_comment(&comment).map_err(|e| anyhow::anyhow!(e.body.message))?;
        ensure!(ids.insert(comment.id.clone()), "Duplicate Inbox comment ID");
        if let Some(request) = &comment.request_key {
            ensure!(
                requests.insert(request.clone()),
                "Duplicate Inbox comment request"
            );
        }
        comments.push(comment);
    }
    Ok(comments)
}
fn read_required<T: DeserializeOwned>(path: &Path) -> Result<T> {
    ensure!(
        !path.is_symlink(),
        "Inbox file cannot be a symlink: {}",
        path.display()
    );
    serde_json::from_slice(&fs::read(path)?)
        .with_context(|| format!("Invalid Inbox file: {}", path.display()))
}
fn read<T: DeserializeOwned + Default>(path: &Path) -> Result<T> {
    match fs::read(path) {
        Ok(bytes) => serde_json::from_slice(&bytes)
            .with_context(|| format!("Invalid Inbox file: {}", path.display())),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(T::default()),
        Err(e) => Err(e.into()),
    }
}
pub(super) fn write(path: &Path, value: &impl Serialize) -> Result<()> {
    write_bytes(path, &serde_json::to_vec_pretty(value)?)
}
fn write_bytes(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path.parent().context("Missing parent")?;
    fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(parent)?;
    let temporary = parent.join(format!(".{}.tmp", aow_id::new_id()));
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .create_new(true)
            .write(true)
            .mode(0o600)
            .open(&temporary)?;
        file.write_all(bytes)?;
        file.sync_all()?;
        fs::rename(&temporary, path)?;
        fs::File::open(parent)?.sync_all()?;
        Ok(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(temporary);
    }
    result
}

use super::{
    model::*,
    persistence::{self, Persistence},
};
use crate::HttpError;
use axum::http::StatusCode;
use std::{
    collections::{BTreeMap, HashSet},
    path::Path,
    sync::{Arc, Mutex, MutexGuard},
};

type Result<T> = std::result::Result<T, HttpError>;
struct State {
    document: Document,
    runs: Vec<Run>,
    comments: BTreeMap<String, Vec<Comment>>,
}
struct Inner {
    state: Mutex<State>,
    persistence: Option<Persistence>,
}
#[derive(Clone)]
pub(crate) struct InboxStore(Arc<Inner>);
impl InboxStore {
    pub(crate) fn in_memory() -> Self {
        Self(Arc::new(Inner {
            state: Mutex::new(State {
                document: Document::default(),
                runs: vec![],
                comments: BTreeMap::new(),
            }),
            persistence: None,
        }))
    }
    pub(crate) fn persistent(state_dir: &Path) -> anyhow::Result<Self> {
        let (persistence, document, runs) = Persistence::open(state_dir)?;
        let comments = document
            .items
            .iter()
            .map(|item| {
                persistence
                    .comments(&item.id)
                    .map(|comments| (item.id.clone(), comments))
            })
            .collect::<anyhow::Result<_>>()?;
        Ok(Self(Arc::new(Inner {
            state: Mutex::new(State {
                document,
                runs,
                comments,
            }),
            persistence: Some(persistence),
        })))
    }
    fn lock(&self) -> Result<MutexGuard<'_, State>> {
        self.0
            .state
            .lock()
            .map_err(|_| HttpError::internal("Inbox lock poisoned"))
    }
    pub(super) fn snapshot(&self) -> Result<Snapshot> {
        let s = self.lock()?;
        // Only the latest launch per requirement is needed by the list.
        let mut seen = HashSet::new();
        Ok(Snapshot {
            revision: s.document.revision,
            labels: s.document.labels.clone(),
            items: s.document.items.clone(),
            comment_counts: s
                .document
                .items
                .iter()
                .map(|item| {
                    (
                        item.id.clone(),
                        s.comments.get(&item.id).map_or(0, Vec::len),
                    )
                })
                .collect(),
            executions: s
                .runs
                .iter()
                .rev()
                .filter(|r| {
                    seen.insert(&r.item_id) && s.document.items.iter().any(|i| i.id == r.item_id)
                })
                .cloned()
                .collect(),
        })
    }
    pub(super) fn item(&self, id: &str) -> Result<Item> {
        self.lock()?
            .document
            .items
            .iter()
            .find(|i| i.id == id)
            .cloned()
            .ok_or_else(missing)
    }
    fn mutate<T>(&self, change: impl FnOnce(&mut Document) -> Result<T>) -> Result<T> {
        let mut state = self.lock()?;
        let mut next = state.document.clone();
        let result = change(&mut next)?;
        next.revision += 1;
        validate_document(&next)?;
        if let Some(persistence) = &self.0.persistence {
            if let Err(error) = persistence.save_document(&next) {
                // ConfigRepository may save successfully before a Git commit fails.
                // Reflect that durable write instead of accepting stale revisions.
                if let Ok(durable) = persistence.document() {
                    state.document = durable;
                }
                return Err(internal(error));
            }
        }
        state.document = next;
        Ok(result)
    }

    pub(super) fn comments(&self, id: &str) -> Result<Vec<Comment>> {
        let state = self.lock()?;
        if !state.document.items.iter().any(|item| item.id == id) {
            return Err(missing());
        }
        Ok(state.comments.get(id).cloned().unwrap_or_default())
    }

    pub(super) fn append_comment(&self, id: &str, input: AddComment) -> Result<Comment> {
        validate_id(&input.request_key)?;
        let mut state = self.lock()?;
        if !state.document.items.iter().any(|item| item.id == id) {
            return Err(missing());
        }
        let existing = state.comments.get(id).and_then(|comments| {
            comments
                .iter()
                .find(|comment| comment.request_key.as_deref() == Some(input.request_key.as_str()))
        });
        let comment = if let Some(existing) = existing {
            if existing.content != input.content || existing.author != input.author {
                return Err(conflict("这条评论已提交，补充内容请追加新评论。"));
            }
            existing.clone()
        } else {
            Comment {
                id: aow_id::new_id(),
                author: input.author,
                content: input.content,
                created_at: chrono::Utc::now().to_rfc3339(),
                request_key: Some(input.request_key),
            }
        };
        validate_comment(&comment)?;
        if let Some(persistence) = &self.0.persistence {
            if let Err(error) = persistence.append_comment(id, &comment) {
                // An append can be durable even if committing it failed.
                if let Ok(comments) = persistence.comments(id) {
                    state.comments.insert(id.to_owned(), comments);
                }
                return Err(internal(error));
            }
        }
        let comments = state.comments.entry(id.to_owned()).or_default();
        if !comments.iter().any(|existing| existing.id == comment.id) {
            comments.push(comment.clone());
        }
        Ok(comment)
    }
    pub(super) fn capture(&self, input: Capture) -> Result<Item> {
        validate_id(&input.request_key)?;
        validate_markdown(&input.markdown)?;
        self.mutate(|doc| {
            let fingerprint = format!("{:x}", md5::compute(input.markdown.as_bytes()));
            if let Some((id, previous)) = doc.captures.get(&input.request_key) {
                if previous != &fingerprint {
                    return Err(conflict("这次录入已提交，请刷新列表确认后再录入。"));
                }
                return doc
                    .items
                    .iter()
                    .find(|item| &item.id == id)
                    .cloned()
                    .ok_or_else(|| conflict("这次录入已被删除。"));
            }
            let now = chrono::Utc::now().to_rfc3339();
            let item = Item {
                id: aow_id::new_id(),
                markdown: input.markdown,
                project_id: None,
                label_ids: vec![],
                revision: 1,
                created_at: now.clone(),
                updated_at: now,
            };
            doc.captures
                .insert(input.request_key, (item.id.clone(), fingerprint));
            doc.items.push(item.clone());
            Ok(item)
        })
    }
    pub(super) fn update(&self, id: &str, input: Update) -> Result<Item> {
        self.mutate(|doc| {
            let item = doc
                .items
                .iter_mut()
                .find(|i| i.id == id)
                .ok_or_else(missing)?;
            revision(item.revision, input.expected_revision)?;
            item.markdown = input.markdown;
            item.project_id = input.project_id;
            item.label_ids = input.label_ids;
            item.revision += 1;
            item.updated_at = chrono::Utc::now().to_rfc3339();
            Ok(item.clone())
        })
    }
    pub(super) fn delete(&self, id: &str, expected: u64) -> Result<()> {
        self.mutate(|doc| {
            let index = doc
                .items
                .iter()
                .position(|i| i.id == id)
                .ok_or_else(missing)?;
            revision(doc.items[index].revision, expected)?;
            doc.items.remove(index);
            Ok(())
        })
    }
    pub(super) fn reorder(&self, input: Reorder) -> Result<()> {
        self.mutate(|doc| {
            revision(doc.revision, input.expected_revision)?;
            let from = doc
                .items
                .iter()
                .position(|i| i.id == input.item_id)
                .ok_or_else(missing)?;
            if input.before_id.as_deref() == Some(input.item_id.as_str()) {
                return Ok(());
            }
            let item = doc.items.remove(from);
            let to = match input.before_id {
                Some(id) => doc
                    .items
                    .iter()
                    .position(|i| i.id == id)
                    .ok_or_else(missing)?,
                None => doc.items.len(),
            };
            doc.items.insert(to, item);
            Ok(())
        })
    }
    pub(super) fn labels(&self, input: LabelsUpdate) -> Result<()> {
        self.mutate(|doc| {
            revision(doc.revision, input.expected_revision)?;
            validate_labels(&input.labels)?;
            let ids: HashSet<_> = input.labels.iter().map(|l| l.id.as_str()).collect();
            for item in &mut doc.items {
                let count = item.label_ids.len();
                item.label_ids.retain(|id| ids.contains(id.as_str()));
                if count != item.label_ids.len() {
                    item.revision += 1;
                    item.updated_at = chrono::Utc::now().to_rfc3339();
                }
            }
            doc.labels = input.labels;
            Ok(())
        })
    }
    pub(super) fn existing_run(&self, item_id: &str, input: &Execute) -> Result<Option<Run>> {
        let state = self.lock()?;
        existing_run(&state.runs, item_id, input)
    }
    pub(super) fn begin_run(
        &self,
        item: &Item,
        input: &Execute,
        cwd: String,
        markdown: String,
        execution_fingerprint: String,
    ) -> Result<(Run, bool)> {
        let mut state = self.lock()?;
        if let Some(run) = existing_run(&state.runs, &item.id, input)? {
            return Ok((run, false));
        }
        let current = state
            .document
            .items
            .iter()
            .find(|i| i.id == item.id)
            .ok_or_else(missing)?;
        revision(current.revision, input.expected_revision)?;
        if state
            .runs
            .iter()
            .any(|r| r.item_id == item.id && r.phase == RunPhase::Starting)
        {
            return Err(conflict("该需求正在启动 Agent，请等待执行结果。"));
        }
        let id = aow_id::new_id();
        let markdown = super::context::task(&item.id, &id, &markdown);
        if markdown.len() > 128 * 1024 {
            return Err(invalid(
                "需求、追加 prompt 与 Inbox 上下文拼接后不能超过 128 KiB。",
            ));
        }
        let run = Run {
            id,
            item_id: item.id.clone(),
            request_key: input.request_key.clone(),
            execution_fingerprint,
            item_revision: item.revision,
            agent: input.agent.clone(),
            project_id: item
                .project_id
                .clone()
                .ok_or_else(|| invalid("请先绑定项目。"))?,
            cwd,
            workspace_mode: input.workspace.workspace_mode,
            markdown,
            phase: RunPhase::Starting,
            tab_id: None,
            pane_id: None,
            error: None,
            created_at: chrono::Utc::now().to_rfc3339(),
        };
        let mut runs = state.runs.clone();
        runs.push(run.clone());
        self.save_runs(&runs)?;
        state.runs = runs;
        Ok((run, true))
    }
    pub(super) fn set_run_cwd(&self, id: &str, cwd: String) -> Result<()> {
        let mut state = self.lock()?;
        let mut runs = state.runs.clone();
        let run = runs
            .iter_mut()
            .find(|run| run.id == id)
            .ok_or_else(missing)?;
        run.cwd = cwd;
        self.save_runs(&runs)?;
        state.runs = runs;
        Ok(())
    }

    pub(crate) fn is_temporary_workspace(&self, path: &str) -> Result<bool> {
        Ok(self.lock()?.runs.iter().any(|run| {
            run.workspace_mode == aow_workspaces::WorkspaceMode::Temporary
                && run.tab_id.is_some()
                && !path.is_empty()
                && run.cwd == path
        }))
    }
    pub(super) fn finish_run(
        &self,
        id: &str,
        info: std::result::Result<aow_protocol::AgentTerminalInfo, String>,
    ) -> Result<()> {
        let mut state = self.lock()?;
        let mut runs = state.runs.clone();
        let run = runs.iter_mut().find(|r| r.id == id).ok_or_else(missing)?;
        match info {
            Ok(info) => {
                run.tab_id = Some(info.tab_id);
                run.pane_id = Some(info.pane_id);
                run.phase = if info.state.task_submitted {
                    RunPhase::Submitted
                } else {
                    RunPhase::Failed
                };
                run.error = info.state.error.or_else(|| {
                    (run.phase == RunPhase::Failed).then(|| "需求未提交，请查看终端。".into())
                });
            }
            Err(error) => {
                run.phase = RunPhase::Failed;
                run.error = Some(error);
            }
        }
        // Even a failed final journal write must not leave a live UI stuck in Starting.
        let saved = self.save_runs(&runs);
        state.runs = runs;
        saved
    }
    fn save_runs(&self, runs: &Vec<Run>) -> Result<()> {
        if let Some(persistence) = &self.0.persistence {
            persistence::write(&persistence.runs, runs).map_err(internal)?;
        }
        Ok(())
    }
}
fn existing_run(runs: &[Run], item: &str, input: &Execute) -> Result<Option<Run>> {
    let fingerprint = input.fingerprint().map_err(internal)?;
    if let Some(run) = runs.iter().find(|r| r.request_key == input.request_key) {
        if run.item_id != item
            || run.agent != input.agent
            || run.item_revision != input.expected_revision
            || (!run.execution_fingerprint.is_empty() && run.execution_fingerprint != fingerprint)
        {
            return Err(conflict("执行请求已使用，请刷新后重试。"));
        }
        return Ok(Some(run.clone()));
    }
    Ok(None)
}
pub(super) fn validate_document(doc: &Document) -> Result<()> {
    validate_labels(&doc.labels)?;
    let labels: HashSet<_> = doc.labels.iter().map(|l| &l.id).collect();
    let mut ids = HashSet::new();
    for item in &doc.items {
        validate_id(&item.id)?;
        validate_markdown(&item.markdown)?;
        if let Some(project) = &item.project_id {
            validate_id(project)?;
        }
        if !ids.insert(&item.id)
            || item.label_ids.iter().collect::<HashSet<_>>().len() != item.label_ids.len()
            || item.label_ids.iter().any(|id| !labels.contains(id))
        {
            return Err(invalid("需求 ID 或标签无效。"));
        }
    }
    Ok(())
}
fn validate_labels(labels: &[Label]) -> Result<()> {
    if labels.len() > 64 {
        return Err(invalid("最多配置 64 个标签。"));
    }
    let mut ids = HashSet::new();
    let mut names = HashSet::new();
    for label in labels {
        validate_id(&label.id)?;
        if !ids.insert(&label.id)
            || label.name.trim().is_empty()
            || label.name.chars().count() > 40
            || !names.insert(label.name.trim().to_lowercase())
            || label.color.len() != 7
            || !label.color.starts_with('#')
            || !label.color.as_bytes()[1..]
                .iter()
                .all(u8::is_ascii_hexdigit)
        {
            return Err(invalid(
                "标签名称须唯一且不超过 40 字，颜色须为十六进制色值。",
            ));
        }
    }
    Ok(())
}
pub(super) fn validate_id(id: &str) -> Result<()> {
    if !aow_id::is_valid_id(id) {
        return Err(invalid("ID 无效。"));
    }
    Ok(())
}
fn validate_markdown(markdown: &str) -> Result<()> {
    if markdown.trim().is_empty() || markdown.len() > 128 * 1024 || markdown.contains('\0') {
        return Err(invalid("请输入需求，最多支持 128 KiB 文本。"));
    }
    Ok(())
}
pub(super) fn validate_comment(comment: &Comment) -> Result<()> {
    validate_id(&comment.id)?;
    if let Some(key) = &comment.request_key {
        validate_id(key)?;
    }
    if comment.content.trim().is_empty()
        || comment.content.len() > 128 * 1024
        || comment.content.contains('\0')
        || comment.author.name.trim().is_empty()
        || comment.author.name.chars().count() > 80
        || chrono::DateTime::parse_from_rfc3339(&comment.created_at).is_err()
    {
        return Err(invalid(
            "评论须包含正文和作者，正文最多 128 KiB，作者名称最多 80 字。",
        ));
    }
    Ok(())
}
pub(super) fn revision(current: u64, expected: u64) -> Result<()> {
    if current != expected {
        return Err(conflict(
            "内容已在其他页面更新，请检查最新内容后重试；当前输入已保留。",
        ));
    }
    Ok(())
}
pub(super) fn invalid(message: &str) -> HttpError {
    HttpError::new(StatusCode::BAD_REQUEST, "invalid_inbox", message, None)
}
fn conflict(message: &str) -> HttpError {
    HttpError::new(StatusCode::CONFLICT, "inbox_conflict", message, None)
}
fn missing() -> HttpError {
    HttpError::new(
        StatusCode::NOT_FOUND,
        "inbox_not_found",
        "需求不存在或已被删除。",
        None,
    )
}
fn internal(error: impl std::fmt::Display) -> HttpError {
    HttpError::internal(error.to_string())
}

