const PREVIOUS_GITHUB_SCRIPT_MD5: &[&str] = &[
    "d1e903f22605a41bf437bf77bc85a981",
    "28fea8f4f7673254cca56a6122bfd0a2",
    "135515472a8c25185cf5a81a35b89138",
