use serde::de::DeserializeOwned;
use serde_json::Value;
use std::{
    collections::HashSet,
    path::{Component, Path},
};

use super::{PullRequestError, Result, SCRIPT_LIMIT, Settings};

// Validate clickable links without making assumptions about the hosting platform.
pub(super) fn web_link(result: &Value, field: &str) -> Result<Option<String>> {
    match result.get(field) {
        Some(Value::Null) => Ok(None),
        Some(Value::String(value)) => {
            let url = reqwest::Url::parse(value).map_err(invalid_json)?;
            if !matches!(url.scheme(), "http" | "https")
                || url.host_str().is_none()
                || !url.username().is_empty()
                || url.password().is_some()
                || value
                    .bytes()
                    .any(|byte| byte.is_ascii_control() || byte.is_ascii_whitespace())
            {
                return Err(invalid_json(format!(
                    "{field} must be an HTTP(S) URL without credentials"
                )));
            }
            Ok(Some(value.clone()))
        }
        _ => Err(invalid_json(format!(
            "{field} must be a URL string or null"
        ))),
    }
}
pub(super) fn managed_script_path(path: &str) -> bool {
    let path = Path::new(path);
    path.parent() == Some(Path::new("review-providers"))
        && path.extension().is_some_and(|s| s == "py")
        && path
            .file_stem()
            .and_then(|s| s.to_str())
            .is_some_and(valid_id)
}
fn valid_id(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 96
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}
pub(super) fn validate_settings(settings: &Settings) -> Result<()> {
    if settings.providers.len() > 32 {
        return Err(PullRequestError::Invalid(
            "最多配置 32 个 Provider。".into(),
        ));
    }
    let mut ids = HashSet::new();
    let mut hosts = HashSet::new();
    for p in &settings.providers {
        if !valid_id(&p.id) || !ids.insert(&p.id) || p.id == "auto" {
            return Err(PullRequestError::Invalid(
                "Provider ID 必须唯一，只能包含字母、数字、-、_，且不能为 auto。".into(),
            ));
        }
        if p.name.trim().is_empty() || p.script.trim().is_empty() || p.script.len() > SCRIPT_LIMIT {
            return Err(PullRequestError::Invalid(
                "名称和脚本必填；脚本最大 1 MiB。".into(),
            ));
        }
        if p.hosts.is_empty() {
            return Err(PullRequestError::Invalid(
                "请至少配置一个 remote 域名。".into(),
            ));
        }
        for host in &p.hosts {
            if host.is_empty()
                || host.len() > 253
                || !host
                    .bytes()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || b".-_:[]".contains(&c))
            {
                return Err(PullRequestError::Invalid(format!(
                    "无效的 remote 域名：{host}"
                )));
            }
            if p.enabled && !hosts.insert(host) {
                return Err(PullRequestError::Invalid(format!(
                    "多个启用的 Provider 匹配同一个域名：{host}"
                )));
            }
        }
    }
    Ok(())
}
// Parse HTTPS, ssh:// and scp-style remotes. Local paths have no provider.
pub(super) fn parse_remote(raw: &str) -> Option<(String, String)> {
    let (host, path) = if raw.contains("://") {
        let url = reqwest::Url::parse(raw).ok()?;
        if !matches!(url.scheme(), "https" | "http" | "ssh" | "git") {
            return None;
        }
        let mut host = url.host_str()?.to_ascii_lowercase();
        if let Some(port) = url
            .port()
            .filter(|_| matches!(url.scheme(), "https" | "http"))
        {
            host.push_str(&format!(":{port}"));
        }
        (host, url.path().trim_start_matches('/').to_string())
    } else {
        let (authority, path) = raw.split_once(':')?;
        if authority.contains('/') || authority.is_empty() {
            return None;
        }
        (
            authority.rsplit('@').next()?.to_ascii_lowercase(),
            path.trim_start_matches('/').to_string(),
        )
    };
    let path = path
        .trim_end_matches('/')
        .strip_suffix(".git")
        .unwrap_or(path.trim_end_matches('/'))
        .to_string();
    if host.is_empty() || path.is_empty() || !path.contains('/') {
        return None;
    }
    Some((host, path))
}
pub(super) fn absolute(repo: &str) -> Result<()> {
    if !Path::new(repo).is_absolute() {
        return Err(PullRequestError::Invalid(
            "repository path must be absolute".into(),
        ));
    }
    Ok(())
}
pub(super) fn positive(number: u64) -> Result<()> {
    if number == 0 {
        Err(PullRequestError::Invalid(
            "PR number must be positive".into(),
        ))
    } else {
        Ok(())
    }
}
pub(super) fn safe_path(path: &str) -> Result<()> {
    if path.is_empty()
        || path.contains('\0')
        || Path::new(path)
            .components()
            .any(|p| !matches!(p, Component::Normal(_)))
    {
        return Err(PullRequestError::Invalid(
            "file path must be repository-relative".into(),
        ));
    }
    Ok(())
}
pub(super) fn invalid_json(message: impl ToString) -> PullRequestError {
    PullRequestError::InvalidJson(message.to_string())
}
pub(super) fn decode<T: DeserializeOwned>(value: Value) -> Result<T> {
    serde_json::from_value(value).map_err(invalid_json)
}

//! Multiplex live updates on a WebSocket so tabs cannot exhaust HTTP/1.1 slots.

use std::time::Duration;

use axum::{
    Extension, Router,
    extract::{
        State,
        ws::{CloseFrame, Message, WebSocket, WebSocketUpgrade},
    },
    http::HeaderMap,
    response::Response,
    routing::get,
};
use serde::Serialize;
use tokio::sync::{broadcast, watch};

use crate::{AppState, HttpError, auth::SessionAccess};

pub(crate) fn routes() -> Router<AppState> {
    Router::new().route("/api/events/ws", get(upgrade))
}

async fn upgrade(
    State(state): State<AppState>,
    headers: HeaderMap,
    access: Option<Extension<SessionAccess>>,
    websocket: WebSocketUpgrade,
) -> Result<Response, HttpError> {
    crate::auth::check_origin(&headers)?;
    // Subscribe before upgrading so updates during the handshake are retained.
    let workspace = state.workspace_events.subscribe();
    let operations = state.operations.subscribe();
    let stops = state.terminals.subscribe_task_stops();
    Ok(websocket.max_message_size(1024).on_upgrade(move |mut socket| async move {
        let revoked = async {
            match access {
                Some(access) => access.revoked().await,
                None => std::future::pending::<()>().await,
            }
        };
        tokio::select! {
            biased;
            _ = revoked => {
                let _ = tokio::time::timeout(Duration::from_secs(1), socket.send(Message::Close(Some(CloseFrame {
                    code: 1008,
                    reason: "Authentication expired".into(),
                })))).await;
            }
            _ = forward(&mut socket, workspace, operations, stops) => {}
        }
    }))
}

fn event(name: &str, data: impl Serialize) -> Message {
    Message::Text(
        serde_json::json!({ "event": name, "data": data })
            .to_string()
            .into(),
    )
}

async fn send(socket: &mut WebSocket, message: Message) -> Result<(), ()> {
    tokio::time::timeout(Duration::from_secs(5), socket.send(message))
        .await
        .map_err(|_| ())?
        .map_err(|_| ())
}

async fn forward(
    socket: &mut WebSocket,
    mut workspace: watch::Receiver<crate::workspace_events::Snapshot>,
    mut operations: watch::Receiver<crate::operations::Snapshot>,
    mut stops: broadcast::Receiver<crate::terminal::notifications::TaskStopNotification>,
) -> Result<(), ()> {
    // Never hold a watch borrow across a send/await; publishers need its write lock.
    let initial = event("workspace", workspace.borrow_and_update().clone());
    send(socket, initial).await?;
    let initial = event("operations", operations.borrow_and_update().clone());
    send(socket, initial).await?;
    let mut heartbeat = tokio::time::interval(Duration::from_secs(15));
    heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    let mut last_pong = tokio::time::Instant::now();
    loop {
        let message = tokio::select! {
            incoming = socket.recv() => {
                match incoming {
                    Some(Ok(Message::Pong(_))) => last_pong = tokio::time::Instant::now(),
                    Some(Ok(Message::Ping(_))) => {}, // Axum replies automatically.
                    _ => return Ok(()), // This stream accepts no application commands.
                }
                continue;
            }
            result = workspace.changed() => {
                result.map_err(|_| ())?;
                event("workspace", workspace.borrow_and_update().clone())
            }
            result = operations.changed() => {
                result.map_err(|_| ())?;
                event("operations", operations.borrow_and_update().clone())
            }
            result = stops.recv() => {
                match result {
                    Ok(stop) => event("task-stopped", stop),
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => return Ok(()),
                }
            }
            _ = heartbeat.tick() => {
                if last_pong.elapsed() > Duration::from_secs(45) { return Ok(()); }
                Message::Ping(Vec::new().into())
            }
        };
        send(socket, message).await?;
    }
}

#[cfg(test)]
mod tests;

use super::*;
use futures_util::{SinkExt, StreamExt};
use serde_json::Value;
use tokio_tungstenite::{connect_async, tungstenite::Message as ClientMessage};

#[tokio::test]
async fn multiplexes_snapshots_changes_and_live_notifications_and_resyncs_on_reconnect() {
    let state = AppState::new(Default::default());
    let (stops, _) = broadcast::channel(16);
    let sender = stops.clone();
    let fixture = state.clone();
    let router = Router::new().route(
        "/events",
        get(move |ws: WebSocketUpgrade| {
            let workspace = fixture.workspace_events.subscribe();
            let operations = fixture.operations.subscribe();
            let stops = sender.subscribe();
            async move {
                ws.on_upgrade(move |mut socket| async move {
                    let _ = forward(&mut socket, workspace, operations, stops).await;
                })
            }
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move { axum::serve(listener, router).await.unwrap() });
    let url = format!("ws://{address}/events");
    let (mut socket, _) = connect_async(&url).await.unwrap();
    assert_eq!(next(&mut socket).await["event"], "workspace");
    assert_eq!(next(&mut socket).await["event"], "operations");

    state.workspace_events.terminals_changed();
    let update = next(&mut socket).await;
    assert_eq!(update["event"], "workspace");
    assert_eq!(update["data"]["terminals"], 1);
    let operation = state.operations.begin(crate::operations::Spec {
        id: "test".into(),
        kind: "test",
        source: "test",
        title: "Testing".into(),
        project_id: None,
        resource: None,
        total: Some(1),
    });
    assert_eq!(
        next(&mut socket).await["data"]["operations"][0]["id"],
        "test"
    );
    stops
        .send(crate::terminal::notifications::TaskStopNotification {
            agent: "codex".into(),
            session_id: "session".into(),
            title: "Done".into(),
            cwd: "/tmp".into(),
            turn_id: None,
            conclusion: None,
            usage: None,
            instance_ids: vec![],
            sources: vec![],
        })
        .unwrap();
    let notification = next(&mut socket).await;
    assert_eq!(notification["event"], "task-stopped");
    assert_eq!(notification["data"]["session_id"], "session");
    socket.close(None).await.unwrap();
    operation.finish(aow_operation_log::Outcome::Succeeded, "Done");
    let (mut socket, _) = connect_async(&url).await.unwrap();
    assert_eq!(next(&mut socket).await["data"]["terminals"], 1);
    assert_eq!(
        next(&mut socket).await["data"]["operations"][0]["outcome"],
        "succeeded"
    );
    // Stops are live notifications, not replayed on reconnect.
    state.workspace_events.terminals_changed();
    assert_eq!(next(&mut socket).await["event"], "workspace");
    socket.close(None).await.unwrap();
    server.abort();
}

async fn next(
    socket: &mut tokio_tungstenite::WebSocketStream<
        tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>,
    >,
) -> Value {
    tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            match socket.next().await.unwrap().unwrap() {
                ClientMessage::Text(text) => return serde_json::from_str(&text).unwrap(),
                ClientMessage::Ping(_) => socket.flush().await.unwrap(),
                message => panic!("unexpected message: {message:?}"),
            }
        }
    })
    .await
    .unwrap()
}

#[tokio::test]
async fn upgrade_requires_authentication_and_matching_origin() {
    use tokio_tungstenite::tungstenite::client::IntoClientRequest;
    let directory = tempfile::tempdir().unwrap();
    crate::auth::write_credentials(directory.path(), "admin", "test-password");
    let mut state = AppState::new(Default::default());
    state.auth = crate::auth::AuthService::persistent(directory.path());
    let router = crate::build_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move { axum::serve(listener, router).await.unwrap() });
    let url = format!("ws://{address}/api/events/ws");
    assert!(
        matches!(connect_async(&url).await, Err(tokio_tungstenite::tungstenite::Error::Http(response)) if response.status() == 401)
    );
    let response = reqwest::Client::new()
        .post(format!("http://{address}/api/auth/login"))
        .json(&serde_json::json!({"username": "admin", "password": "test-password"}))
        .send()
        .await
        .unwrap();
    assert_eq!(response.status(), 200);
    let cookie = response.headers()["set-cookie"]
        .to_str()
        .unwrap()
        .split(';')
        .next()
        .unwrap();
    let mut request = url.into_client_request().unwrap();
    request
        .headers_mut()
        .insert("cookie", cookie.parse().unwrap());
    request
        .headers_mut()
        .insert("origin", "https://evil.example".parse().unwrap());
    assert!(
        matches!(connect_async(request.clone()).await, Err(tokio_tungstenite::tungstenite::Error::Http(response)) if response.status() == 403)
    );
    request
        .headers_mut()
        .insert("origin", format!("http://{address}").parse().unwrap());
    let (mut socket, _) = connect_async(request).await.unwrap();
    assert_eq!(next(&mut socket).await["event"], "workspace");
    next(&mut socket).await;
    crate::auth::write_credentials(directory.path(), "admin", "replacement-password");
    let code = tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            if let ClientMessage::Close(frame) = socket.next().await.unwrap().unwrap() {
                break u16::from(frame.unwrap().code);
            }
        }
    })
    .await
    .unwrap();
    assert_eq!(code, 1008);
    server.abort();
}

