    assert!(branch.status.success());
    assert_eq!(String::from_utf8(branch.stdout).unwrap().trim(), "feature");
    let tabs = fixture
        .state
        .terminals
        .list(Some(&first.cwd))
        .await
        .unwrap()
        .tabs;
    assert_eq!(tabs.len(), 2);
    assert!(tabs.iter().any(|tab| tab.id == first.tab_id));
    assert!(tabs.iter().any(|tab| tab.id == second.tab_id));
    let closed = fixture
        .state
        .terminals
        .delete_workspace(&first.cwd)
        .await
        .unwrap();
    assert_eq!(closed, (0, 2));
    assert!(
        fixture
            .state
            .terminals
            .list(Some(&first.cwd))
            .await
            .unwrap()
            .tabs
            .is_empty()
    );
    for pane_id in [&first.pane_id, &second.pane_id] {
        assert!(
            fixture
                .state
                .terminals
                .inner
                .terminald
                .get(pane_id)
                .await
                .unwrap()
                .is_none()
        );
    }
    fixture.stop().await;
}

