pub(crate) fn routes() -> Router<AppState> {
    Router::new()
        .route(
            "/api/terminals",
            get(tabs::list_terminals).post(tabs::create_terminal),
        )
        .route("/api/terminals/order", put(tabs::reorder_terminals))
        .route("/api/terminals/agents", get(tabs::list_terminal_agents))
        .route("/api/terminals/task-stops", get(notifications::events))
        .route(
            "/api/terminals/{tab_id}/panes/{pane_id}/hosting",
            put(hosting::enable),
        )
        .route(
            "/api/terminals/{tab_id}/panes/{pane_id}/agent-sessions",
            get(sessions::list),
        )
        .route(
            "/api/terminals/{tab_id}",
            get(tabs::get_terminal)
                .patch(tabs::update_terminal)
                .delete(tabs::delete_terminal),
        )
        .route("/api/terminals/{tab_id}/split", post(tabs::split_terminal))
        .route(
            "/api/terminals/{tab_id}/rebuild",
            post(rebuild::rebuild_terminal),
        )
        .route(
            "/api/terminals/{tab_id}/layout",
            put(tabs::update_terminal_layout),
        )
        .route(
            "/api/terminals/{tab_id}/panes/{pane_id}",
            axum::routing::delete(tabs::delete_terminal_pane),
        )
        .route(
            "/api/terminals/{tab_id}/panes/{pane_id}/ws",
            get(attachment::attach_terminal_pane),
        )
        .route(
            "/api/terminals/{tab_id}/panes/{pane_id}/clipboard-images",
            post(clipboard::upload_terminal_clipboard_image),
        )
}

use super::*;

pub(crate) fn validate_request_origin(headers: &HeaderMap) -> Result<(), TerminalError> {
    let Some(origin) = headers.get(ORIGIN) else {
        return Ok(());
    };
    let origin = origin
        .to_str()
        .map_err(|_| TerminalError::ForbiddenOrigin("Origin is not valid ASCII".to_owned()))?;
    let origin: Uri = origin
        .parse()
        .map_err(|_| TerminalError::ForbiddenOrigin("Origin is not a valid URL".to_owned()))?;
    if !matches!(origin.scheme_str(), Some("http" | "https"))
        || origin.path() != "/"
        || origin.query().is_some()
    {
        return Err(TerminalError::ForbiddenOrigin(
            "Origin must be an HTTP origin without a path or query".to_owned(),
        ));
    }
    let origin_authority = origin.authority().ok_or_else(|| {
        TerminalError::ForbiddenOrigin("Origin does not contain a host".to_owned())
    })?;
    let host = headers
        .get(HOST)
        .ok_or_else(|| TerminalError::ForbiddenOrigin("Host header is required".to_owned()))?
        .to_str()
        .map_err(|_| TerminalError::ForbiddenOrigin("Host is not valid ASCII".to_owned()))?
        .parse::<http::uri::Authority>()
        .map_err(|_| TerminalError::ForbiddenOrigin("Host is invalid".to_owned()))?;
    if !origin_authority.host().eq_ignore_ascii_case(host.host())
        || origin_authority.port_u16() != host.port_u16()
    {
        return Err(TerminalError::ForbiddenOrigin(format!(
            "Origin authority {origin_authority} does not match Host {host}"
        )));
    }
    Ok(())
}

use super::super::rebuild::ensure_rebuildable;
use super::*;
use aow_agents::Agent;

pub(super) async fn rebuild_terminal(
    State(state): State<AppState>,
    AxumPath(tab_id): AxumPath<String>,
) -> Result<Json<TerminalTab>, HttpError> {
    // Finish committing or rolling back even if the browser disconnects.
    tokio::spawn(async move {
        let previous = state
            .terminals
            .get(&tab_id)
            .await
            .map_err(terminal_http_error)?;
        ensure_rebuildable(&previous).map_err(terminal_http_error)?;
        let mut specs = Vec::new();
        for pane in &previous.panes {
            let mut spec = runtime_spec(pane);
            if pane.kind == TerminalPaneKind::Agent {
                let agent_id = pane.agent_id.as_deref().ok_or_else(|| {
                    terminal_http_error(TerminalError::Invalid(
                        "终端缺少 Agent 配置，无法重建".into(),
                    ))
                })?;
                if pane.agent_terminal.is_some()
                    && Agent::from_id(agent_id)
                        .and_then(Agent::interactive)
                        .is_none()
                {
                    return Err(terminal_http_error(TerminalError::Invalid(
                        "该 Agent 不支持交互式初始化".into(),
                    )));
                }
                // Credentials and PATH come from the current workspace profile;
                // keep the saved command/arguments (including explicit resume).
                spec.environment = state
                    .aow
                    .resolve_terminal_rebuild_launch(
                        pane,
                        &previous.workspace_root,
                        state
                            .inbox
                            .is_temporary_workspace(&previous.workspace_root)?,
                    )
                    .await
                    .map_err(crate::aow::aow_http_error)?
                    .env;
            }
            specs.push(spec);
        }
        let tab = state
            .terminals
            .rebuild(&previous, &specs)
            .await
            .map_err(terminal_http_error)?;
        for pane in &tab.panes {
            if pane.agent_terminal.is_some() {
                let adapter = pane
                    .agent_id
                    .as_deref()
                    .and_then(Agent::from_id)
                    .and_then(Agent::interactive)
                    .expect("validated interactive adapter");
                let manager = state.terminals.clone();
                let pane_id = pane.id.clone();
                tokio::spawn(async move {
                    if let Err(error) = manager
                        .initialize_agent_lifecycle(
                            &pane_id,
                            adapter,
                            None,
                            Duration::from_secs(120),
                            None,
                        )
                        .await
                    {
                        tracing::warn!(%pane_id, %error, "failed to initialize rebuilt agent");
                    }
                });
            }
        }
        Ok(Json(tab))
    })
    .await
    .map_err(|error| HttpError::internal(error.to_string()))?
}

