pub(super) struct Source {
    pub locator: AgentSessionLocator,
    pub process: TerminalAgentProcess,
}

pub(super) async fn read(manager: &TerminalManager, pane_id: &str) -> Result<Source> {
    let detected = manager.agents(None).await?;
    let agent = detected
        .agents
        .get(pane_id)
        .and_then(|agent| agent.as_deref())
        .context("当前实例没有运行中的 Agent")?;
    let process = detected
        .processes
        .get(pane_id)
        .cloned()
        .context("无法确认 Agent 进程身份，请升级终端服务")?;
    let environment = sessions::process_environment(&process).context("Agent 进程已变化")?;
    let tracker = aow_agents::Agent::from_id(agent)
        .and_then(aow_agents::Agent::session_tracking)
        .context("该 Agent 暂不支持托管")?;
    let target = match tracker
        .resolve_live_session(LiveSessionContext {
            pid: Some(process.pid),
            cwd: &process.cwd,
            title: detected.titles.get(pane_id).map_or("", String::as_str),
            environment: &environment,
        })
        .await
    {
        SessionResolution::Resolved(target) => target,
        _ => anyhow::bail!("尚未定位 Agent 当前会话，请在会话开始后重试"),
    };
    let roots = SessionRoots::from_configuration(
        environment
            .get("HOME")
            .map_or(crate::PROCESS_HOME.as_path(), PathBuf::as_path),
        &environment,
    );
    let cwd = PathBuf::from(&process.cwd);
    let locator = tokio::task::spawn_blocking(move || -> Result<_> {
        let mut candidates = tracker.candidate_sessions(&target, &cwd, roots);
        ensure!(
            candidates.len() == 1,
            "无法唯一定位当前 Agent 会话，请为会话设置唯一标题后重试"
        );
        Ok(candidates.remove(0))
    })
    .await??;
    ensure!(sessions::same_process(&process), "Agent 进程已变化");
    Ok(Source { locator, process })
}

pub(super) fn matches(hosting: &TerminalHosting, source: &Source) -> bool {
    hosting.agent == source.locator.agent
        && hosting.session_id == source.locator.session_id
        && hosting.process == source.process
}

use super::*;

impl TerminalManager {
    pub(in crate::terminal) fn hosting_gate(
        &self,
        pane_id: &str,
    ) -> Result<Arc<tokio::sync::Mutex<()>>, TerminalError> {
        let mut gates = self
            .inner
            .hosting_gates
            .lock()
            .map_err(|_| TerminalError::Poisoned)?;
        gates.retain(|_, gate| gate.strong_count() > 0);
        if let Some(gate) = gates.get(pane_id).and_then(std::sync::Weak::upgrade) {
            return Ok(gate);
        }
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        gates.insert(pane_id.into(), Arc::downgrade(&gate));
        Ok(gate)
    }

    pub(in crate::terminal) fn hosting(
        &self,
        pane_id: &str,
    ) -> Result<Option<TerminalHosting>, TerminalError> {
        let state = self.lock_state()?;
        let (tab, pane) = find_pane(&state.tabs, pane_id)
            .ok_or_else(|| TerminalError::PaneNotFound(pane_id.into()))?;
        Ok(state.tabs[tab].panes[pane].hosting.clone())
    }

    /// Workers supply their generation for atomic conditional updates, including
    /// failures. User changes and terminal input also serialize with hosting_gate;
    /// expected=None is reserved for explicit user actions.
    pub(in crate::terminal) fn set_hosting(
        &self,
        pane_id: &str,
        expected: Option<&str>,
        hosting: Option<TerminalHosting>,
    ) -> Result<bool, TerminalError> {
        let mut state = self.lock_state()?;
        let (tab, pane) = find_pane(&state.tabs, pane_id)
            .ok_or_else(|| TerminalError::PaneNotFound(pane_id.into()))?;
        if expected.is_some_and(|id| {
            state.tabs[tab].panes[pane]
                .hosting
                .as_ref()
                .is_none_or(|current| current.id != id)
        }) {
            return Ok(false);
        }
        let old = state.tabs[tab].clone();
        state.tabs[tab].panes[pane].hosting = hosting;
        touch_tab(&mut state.tabs[tab]);
        if let Err(error) = self.persist_locked(&state) {
            state.tabs[tab] = old;
            return Err(error);
        }
        Ok(true)
    }
}

pub(super) fn transition(hosting: &mut TerminalHosting, phase: TerminalHostingPhase) {
    hosting.phase = phase;
    hosting.phase_started_at = timestamp();
}

pub(super) fn elapsed(hosting: &TerminalHosting) -> i64 {
    chrono::DateTime::parse_from_rfc3339(&hosting.phase_started_at).map_or(i64::MAX, |started| {
        (chrono::Utc::now() - started.to_utc()).num_seconds()
    })
}

