async fn takeover_waits_for_submission_boundary() {
    let manager =
        TerminalManager::in_memory(TerminaldClient::new("/tmp/unused-hosting.sock".into()));
    let first = manager.hosting_gate("pane").unwrap();
    let second = manager.hosting_gate("pane").unwrap();
    let submission = first.lock().await;
    assert!(second.try_lock().is_err());
    drop(submission);
    assert!(second.try_lock().is_ok());
}

use super::super::agent_control::connection::AgentConnection;
use super::super::notifications::TaskStopNotification;
use super::state::{elapsed, transition};
use super::*;
use anyhow::{Context, Result, ensure};
use aow_automations::RunStatus;
use tokio::sync::broadcast;

pub(crate) fn recover(state: AppState) {
    let Ok(tabs) = state.terminals.list_snapshot(None) else {
        return;
    };
    for pane in tabs.tabs.into_iter().flat_map(|tab| tab.panes) {
        if let Some(hosting) = pane.hosting {
            let completions = state.terminals.subscribe_task_completions();
            spawn(state.clone(), pane.id, hosting, None, completions);
        }
    }
}

pub(super) fn spawn(
    state: AppState,
    pane_id: String,
    hosting: TerminalHosting,
    connection: Option<AgentConnection>,
    completions: broadcast::Receiver<TaskStopNotification>,
) {
    if hosting.phase.stopped() {
        return;
    }
    let Ok(mut workers) = state.terminals.inner.hosting_workers.lock() else {
        return;
    };
    if !workers.insert(hosting.id.clone()) {
        return;
    }
    drop(workers);
    tokio::spawn(async move {
        if let Err(error) = run(&state, &pane_id, &hosting.id, connection, completions).await {
            if let Ok(gate) = state.terminals.hosting_gate(&pane_id) {
                let _gate = gate.lock().await;
                if let Ok(Some(mut current)) = state.terminals.hosting(&pane_id) {
                    if current.id == hosting.id && !current.phase.stopped() {
                        transition(&mut current, TerminalHostingPhase::Failed);
                        current.error = Some(format!("{error:#}"));
                        if let Err(error) =
                            state
                                .terminals
                                .set_hosting(&pane_id, Some(&hosting.id), Some(current))
                        {
                            tracing::error!(%error, %pane_id, "cannot persist hosting failure");
                        }
                        state.workspace_events.terminals_changed();
                    }
                }
            }
        }
        if let Ok(mut workers) = state.terminals.inner.hosting_workers.lock() {
            workers.remove(&hosting.id);
        }
    });
}

async fn run(
    state: &AppState,
    pane_id: &str,
    id: &str,
    connection: Option<AgentConnection>,
    mut completions: broadcast::Receiver<TaskStopNotification>,
) -> Result<()> {
    let manager = &state.terminals;
    let gate = manager.hosting_gate(pane_id)?;
    let mut connection = match connection {
        Some(connection) => connection,
        None => {
            let _gate = gate.lock().await;
            let Some(current) = manager.hosting(pane_id)?.filter(|hosting| hosting.id == id) else {
                return Ok(());
            };
            if current.phase.stopped() {
                return Ok(());
            }
            ensure!(
                current.phase != TerminalHostingPhase::Submitting,
                "AoW 在提交反馈期间重启，送达状态未知，请接管后确认，未自动重发"
            );
            let source = source::read(manager, pane_id).await?;
            ensure!(
                source::matches(&current, &source),
                "Agent 进程或会话已变化，请接管后重新配置托管"
            );
            tokio::time::timeout(
                Duration::from_secs(10),
                AgentConnection::claim_with_force(&manager.inner.terminald, pane_id, true),
            )
            .await
            .context("恢复托管控制权超时")??
        }
    };
    let mut interval = tokio::time::interval(Duration::from_millis(1500));
    interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    loop {
        let Some(hosting) = manager.hosting(pane_id)?.filter(|hosting| hosting.id == id) else {
            return Ok(());
        };
        if hosting.phase.stopped() {
            return Ok(());
        }
        tokio::select! {
            message = connection.socket.next() => {
                if let Some(aow_protocol::TerminalAttachServerMessage::Control { state }) = AgentConnection::check(message)? {
                    ensure!(state == aow_protocol::TerminalControlState::Claimed, "托管控制权已丢失，请接管后重试");
                }
            }
            event = completions.recv() => {
                let event = event.context("任务完成事件订阅中断或积压丢失，请接管后重新启用托管")?;
                if accepts(&hosting, pane_id, &event) {
                    let source = source::read(manager, pane_id).await?;
                    ensure!(source::matches(&hosting, &source), "Agent 进程或会话已变化，请接管后重新配置托管");
                    start_review(state, pane_id, hosting, event).await?;
                }
            }
            _ = interval.tick() => {
                ensure!(sessions::same_process(&hosting.process), "Agent 进程已变化，请接管后重新配置托管");
                step(state, pane_id, hosting, &mut completions, &mut connection).await?;
            }
        }
    }
}

pub(super) fn accepts(
    hosting: &TerminalHosting,
    pane_id: &str,
    event: &TaskStopNotification,
) -> bool {
    hosting.phase == TerminalHostingPhase::Waiting
        && event.agent == hosting.agent
        && event.session_id == hosting.session_id
        && event.instance_ids.iter().any(|id| id == pane_id)
        && event
            .turn_id
            .as_ref()
            .is_none_or(|id| hosting.source_turn_id.as_ref() != Some(id))
}

async fn start_review(
    state: &AppState,
    pane_id: &str,
    mut hosting: TerminalHosting,
    event: TaskStopNotification,
) -> Result<()> {
    let automation = state
        .automations
        .as_ref()
        .context("Automation 服务不可用")?;
    let task = automation.hosting_task(&hosting.task_id, hosting.task_revision)?;
    hosting.source_turn_id = event.turn_id.clone();
    hosting.run_id = Some(aow_automations::store::new_run_id());
    transition(&mut hosting, TerminalHostingPhase::Reviewing);
    save(state, pane_id, &hosting)?;
    automation.dispatch_hosted(task, &hosting, &event).await
}

async fn step(
    state: &AppState,
    pane_id: &str,
    mut hosting: TerminalHosting,
    completions: &mut broadcast::Receiver<TaskStopNotification>,
    connection: &mut AgentConnection,
) -> Result<()> {
    let automation = state
        .automations
        .as_ref()
        .context("Automation 服务不可用")?;
    match hosting.phase {
        TerminalHostingPhase::Waiting => {}
        TerminalHostingPhase::Reviewing => {
            let run_id = hosting.run_id.as_deref().context("缺少运行 ID")?;
            let Some(run) = automation.hosted_run(&hosting.task_id, run_id)? else {
                ensure!(elapsed(&hosting) < 90, "Runner 启动超时，尚未生成执行记录");
                return Ok(());
            };
            if !run.status.terminal() {
                return Ok(());
            }
            ensure!(
                run.status == RunStatus::Completed,
                "{}",
                run.message.as_deref().unwrap_or("托管任务未正常完成")
            );
            transition(&mut hosting, TerminalHostingPhase::Collecting);
            save(state, pane_id, &hosting)?;
        }
        TerminalHostingPhase::Collecting => {
            let run = automation
                .hosted_run(
                    &hosting.task_id,
                    hosting.run_id.as_deref().context("缺少运行 ID")?,
                )?
                .context("执行记录已丢失")?;
            let result = automation.run_result(&run)?;
            let source = source::read(&state.terminals, pane_id).await?;
            // Slow scheduler/history I/O never delays a human takeover. Only
            // the final ownership check and paste + Enter hold the input gate.
            let gate = state.terminals.hosting_gate(pane_id)?;
            let _gate = gate.lock().await;
            if state
                .terminals
                .hosting(pane_id)?
                .is_none_or(|current| current.id != hosting.id)
            {
                return Ok(());
            }
            ensure!(
                sessions::same_process(&hosting.process),
                "原 Agent 进程已变化，未提交托管结论"
            );
            ensure!(
                source::matches(&hosting, &source),
                "原 Agent 进程或会话已变化，未提交托管结论"
            );
            // A passing final review still wins when all feedback slots are used.
            // Keep the outcome for observers and stop without submitting any text.
            if aow_automations::hosting::review_passed(&result) {
                transition(&mut hosting, TerminalHostingPhase::Completed);
                return save(state, pane_id, &hosting);
            }
            if hosting.input_count >= hosting.max_inputs {
                transition(&mut hosting, TerminalHostingPhase::LimitReached);
                return save(state, pane_id, &hosting);
            }
            super::super::agent_control::api::validate_task(&result)?;
            transition(&mut hosting, TerminalHostingPhase::Submitting);
            save(state, pane_id, &hosting)?;
            // Discard events received during review, but retain any completion
            // emitted while this submission is being acknowledged.
            *completions = completions.resubscribe();
            tokio::time::timeout(Duration::from_secs(15), connection.submit(&result))
                .await
                .context("反馈提交超时，送达状态未知，请接管确认，未自动重发")??;
            hosting.input_count += 1;
            transition(&mut hosting, TerminalHostingPhase::Waiting);
            save(state, pane_id, &hosting)?;
        }
        TerminalHostingPhase::Submitting => {
            anyhow::bail!("反馈送达状态未知，请接管确认，未自动重发")
        }
        TerminalHostingPhase::Completed
        | TerminalHostingPhase::LimitReached
        | TerminalHostingPhase::Failed => {}
    }
    Ok(())
}

fn save(state: &AppState, pane_id: &str, hosting: &TerminalHosting) -> Result<()> {
    ensure!(
        state
            .terminals
            .set_hosting(pane_id, Some(&hosting.id), Some(hosting.clone()))?,
        "托管已解除"
    );
    state.workspace_events.terminals_changed();
    Ok(())
}

use super::*;

pub(super) fn validate_ratio(ratio: f32) -> Result<f32, TerminalError> {
    if !ratio.is_finite() || !(0.05..=0.95).contains(&ratio) {
        return Err(TerminalError::Invalid(
            "split ratio must be between 0.05 and 0.95".to_owned(),
        ));
    }
    Ok(ratio)
}

pub(super) fn tab_index(state: &ManagerState, tab_id: &str) -> Result<usize, TerminalError> {
    state
        .tabs
        .iter()
        .position(|tab| tab.id == tab_id)
        .ok_or_else(|| TerminalError::TabNotFound(tab_id.to_owned()))
}

pub(super) fn touch_tab(tab: &mut TerminalTab) {
    tab.revision = tab.revision.saturating_add(1);
    tab.updated_at = timestamp();
}

pub(super) fn replace_layout_leaf(
    layout: &mut TerminalLayout,
    pane_id: &str,
    replacement: &TerminalLayout,
) -> bool {
    match layout {
        TerminalLayout::Pane { pane_id: current } if current == pane_id => {
            *layout = replacement.clone();
            true
        }
        TerminalLayout::Pane { .. } => false,
        TerminalLayout::Split { first, second, .. } => {
            replace_layout_leaf(first, pane_id, replacement)
                || replace_layout_leaf(second, pane_id, replacement)
        }
    }
}

pub(super) fn remove_layout_leaf(layout: TerminalLayout, pane_id: &str) -> Option<TerminalLayout> {
    match layout {
        TerminalLayout::Pane { pane_id: current } => {
            (current != pane_id).then_some(TerminalLayout::Pane { pane_id: current })
        }
        TerminalLayout::Split {
            axis,
            ratio,
            first,
            second,
        } => {
            if layout_contains(&first, pane_id) {
                match remove_layout_leaf(*first, pane_id) {
                    Some(first) => Some(TerminalLayout::Split {
                        axis,
                        ratio,
                        first: Box::new(first),
                        second,
                    }),
                    None => Some(*second),
                }
            } else {
                match remove_layout_leaf(*second, pane_id) {
                    Some(second) => Some(TerminalLayout::Split {
                        axis,
                        ratio,
                        first,
                        second: Box::new(second),
                    }),
                    None => Some(*first),
                }
            }
        }
    }
}

pub(super) fn layout_contains(layout: &TerminalLayout, pane_id: &str) -> bool {
    match layout {
        TerminalLayout::Pane { pane_id: current } => current == pane_id,
        TerminalLayout::Split { first, second, .. } => {
            layout_contains(first, pane_id) || layout_contains(second, pane_id)
        }
    }
}

pub(super) fn validate_layout(
    layout: &TerminalLayout,
    panes: &[TerminalPane],
) -> Result<(), TerminalError> {
    let expected = panes
        .iter()
        .map(|pane| pane.id.as_str())
        .collect::<HashSet<_>>();
    let mut found = HashSet::new();
    collect_layout_panes(layout, 0, &mut found)?;
    if found != expected {
        return Err(TerminalError::Invalid(
            "layout must contain every pane exactly once".to_owned(),
        ));
    }
    Ok(())
}

fn collect_layout_panes<'a>(
    layout: &'a TerminalLayout,
    depth: usize,
    panes: &mut HashSet<&'a str>,
) -> Result<(), TerminalError> {
    if depth > MAX_LAYOUT_DEPTH {
        return Err(TerminalError::Invalid(format!(
            "layout exceeds maximum depth {MAX_LAYOUT_DEPTH}"
        )));
    }
    match layout {
        TerminalLayout::Pane { pane_id } => {
            if !panes.insert(pane_id) {
                return Err(TerminalError::Invalid(format!(
                    "pane appears more than once in layout: {pane_id}"
                )));
            }
        }
        TerminalLayout::Split {
            ratio,
            first,
            second,
            ..
        } => {
            validate_ratio(*ratio)?;
            collect_layout_panes(first, depth + 1, panes)?;
            collect_layout_panes(second, depth + 1, panes)?;
        }
    }
    Ok(())
}

pub(super) fn validate_persisted_tabs(tabs: &[TerminalTab]) -> Result<(), TerminalError> {
    let mut tab_ids = HashSet::new();
    let mut pane_ids = HashSet::new();
    for tab in tabs {
        if !tab_ids.insert(tab.id.as_str()) {
            return Err(TerminalError::Invalid(format!(
                "duplicate terminal tab id: {}",
                tab.id
            )));
        }
        if tab.panes.is_empty() {
            return Err(TerminalError::Invalid(format!(
                "terminal tab has no panes: {}",
                tab.id
            )));
        }
        for pane in &tab.panes {
            if !pane_ids.insert(pane.id.as_str()) {
                return Err(TerminalError::Invalid(format!(
                    "duplicate terminal pane id: {}",
                    pane.id
                )));
            }
            validate_name(&pane.name)?;
        }
        validate_layout(&tab.layout, &tab.panes)?;
    }
    Ok(())
}

use super::super::*;

impl TerminalManager {
    pub(crate) async fn reconcile(&self) -> Result<(), TerminalError> {
        let _operation = self.inner.operation.lock().await;
        const MAX_ATTEMPTS: usize = 3;
        for attempt in 1..=MAX_ATTEMPTS {
            let before = self
                .inner
                .terminald
                .health()
                .await
                .map_err(map_client_error)?;
            let runtimes = self
                .inner
                .terminald
                .list()
                .await
                .map_err(map_client_error)?;
            let desired = {
                let state = self.lock_state()?;
                state
                    .tabs
                    .iter()
                    .flat_map(|tab| tab.panes.iter().cloned())
                    .map(|pane| (pane.id.clone(), pane))
                    .collect::<HashMap<_, _>>()
            };
            let actual = runtimes
                .into_iter()
                .map(|runtime| (runtime.id.clone(), runtime))
                .collect::<HashMap<_, _>>();

            // The JSON document is the desired runtime set. Delete daemon-only
            // instances first so a prior control-plane crash cannot leak shells.
            for runtime_id in actual.keys().filter(|id| !desired.contains_key(*id)) {
                self.inner
                    .terminald
                    .delete(runtime_id)
                    .await
                    .map_err(map_client_error)?;
            }

            // Existing runtimes are deliberately preserved even if their live
            // size differs. Web restarts must not replace a healthy shell.
            // Every persisted pane is desired state (including one last seen
            // exited/interrupted), so daemon restart recreates all missing
            // panes as fresh running shells.
            for pane in desired.values() {
                if !actual.contains_key(&pane.id) && pane.restart_on_daemon_restart {
                    self.inner
                        .terminald
                        .create(&pane.id, &self.runtime_spec(pane))
                        .await
                        .map_err(map_client_error)?;
                }
            }
            self.mark_missing_nonrestart_panes(&desired, &actual)?;

            let mut reconciled = HashMap::new();
            for id in desired.keys() {
                if let Some(runtime) = self
                    .inner
                    .terminald
                    .get(id)
                    .await
                    .map_err(map_client_error)?
                {
                    reconciled.insert(id.clone(), runtime);
                }
            }
            let after = self
                .inner
                .terminald
                .health()
                .await
                .map_err(map_client_error)?;
            if before.instance_id != after.instance_id {
                tracing::warn!(
                    attempt,
                    before_instance_id = %before.instance_id,
                    after_instance_id = %after.instance_id,
                    "terminald restarted during reconciliation; retrying"
                );
                continue;
            }

            self.record_daemon_instance(after.instance_id)?;
            return self.apply_runtime_statuses(&reconciled);
        }
        Err(TerminalError::DaemonUnavailable(
            "terminald restarted repeatedly during reconciliation".to_owned(),
        ))
    }

    fn record_daemon_instance(&self, instance_id: String) -> Result<(), TerminalError> {
        let mut instance = self
            .inner
            .daemon_instance_id
            .lock()
            .map_err(|_| TerminalError::Poisoned)?;
        let previous = instance.replace(instance_id.clone());
        if previous.as_deref().is_some_and(|id| id != instance_id) {
            tracing::info!(
                previous_instance_id = ?previous,
                %instance_id,
                "terminald instance changed; desired runtimes were rebuilt"
            );
        }
        Ok(())
    }

    fn apply_runtime_statuses(
        &self,
        runtimes: &HashMap<String, TerminalRuntime>,
    ) -> Result<(), TerminalError> {
        let mut state = self.lock_state()?;
        let old = state.tabs.clone();
        let mut changed = false;
        for tab in &mut state.tabs {
            let mut tab_changed = false;
            for pane in &mut tab.panes {
                let Some(runtime) = runtimes.get(&pane.id) else {
                    continue;
                };
                if apply_runtime(pane, runtime) {
                    tab_changed = true;
                    changed = true;
                }
            }
            if tab_changed {
                // Runtime state and size are not structural layout changes.
                tab.updated_at = timestamp();
            }
        }
        if changed && let Err(error) = self.persist_locked(&state) {
            state.tabs = old;
            return Err(error);
        }
        Ok(())
    }

    fn mark_missing_nonrestart_panes(
        &self,
        desired: &HashMap<String, TerminalPane>,
        actual: &HashMap<String, TerminalRuntime>,
    ) -> Result<(), TerminalError> {
        let missing = desired
            .values()
            .filter(|pane| !pane.restart_on_daemon_restart && !actual.contains_key(&pane.id))
            .map(|pane| pane.id.as_str())
            .collect::<HashSet<_>>();
        if missing.is_empty() {
            return Ok(());
        }
        let mut state = self.lock_state()?;
        let old = state.tabs.clone();
        let now = timestamp();
        let mut changed = false;
        for tab in &mut state.tabs {
            let mut tab_changed = false;
            for pane in &mut tab.panes {
                if missing.contains(pane.id.as_str()) && pane.status == TerminalPaneStatus::Running
                {
                    pane.status = TerminalPaneStatus::Interrupted;
                    pane.exit_code = None;
                    pane.updated_at = now.clone();
                    tab_changed = true;
                    changed = true;
                }
            }
            if tab_changed {
                tab.updated_at = now.clone();
            }
        }
        if changed && let Err(error) = self.persist_locked(&state) {
            state.tabs = old;
            return Err(error);
        }
        Ok(())
    }

    pub(in crate::terminal) async fn sync_runtime(
        &self,
        pane_id: &str,
    ) -> Result<(), TerminalError> {
        // Multiple browser bridges for one pane can overlap briefly during a
        // takeover. Serialize get+apply so every later ACK observes and stores
        // terminald's latest authoritative state rather than a stale snapshot.
        let _sync = self.inner.runtime_sync.lock().await;
        let runtime = self
            .inner
            .terminald
            .get(pane_id)
            .await
            .map_err(map_client_error)?;
        if let Some(runtime) = runtime {
            self.apply_runtime_statuses(&HashMap::from([(pane_id.to_owned(), runtime)]))?;
        }
        Ok(())
    }
}

use std::sync::MutexGuard;

use super::super::*;

impl TerminalManager {
    pub(crate) fn in_memory(terminald: TerminaldClient) -> Self {
        let clipboard = clipboard::ClipboardStorage::temporary();
        let manager = Self {
            inner: Arc::new(ManagerInner {
                metadata_path: None,
                state: Mutex::new(ManagerState::default()),
                terminald,
                daemon_instance_id: Mutex::new(None),
                operation: tokio::sync::Mutex::new(()),
                runtime_sync: tokio::sync::Mutex::new(()),
                agent_operations: Mutex::new(HashMap::new()),
                hosting_gates: Mutex::new(HashMap::new()),
                hosting_workers: Mutex::new(HashSet::new()),
                clipboard,
                clipboard_operation: tokio::sync::Mutex::new(()),
                task_stops: tokio::sync::broadcast::channel(128).0,
                task_completions: tokio::sync::broadcast::channel(128).0,
                notifications_started: std::sync::atomic::AtomicBool::new(false),
            }),
        };
        manager.start_clipboard_cleanup();
        manager
    }

    pub(crate) fn persistent(
        state_dir: PathBuf,
        terminald: TerminaldClient,
    ) -> Result<Self, TerminalError> {
        std::fs::create_dir_all(&state_dir)?;
        let clipboard = clipboard::ClipboardStorage::persistent(&state_dir)?;
        let metadata_path = state_dir.join(METADATA_FILE);
        let mut tabs = match std::fs::read(&metadata_path) {
            Ok(bytes) => {
                let persisted: PersistedState = serde_json::from_slice(&bytes)?;
                if persisted.version != METADATA_VERSION {
                    return Err(TerminalError::Invalid(format!(
                        "unsupported terminal metadata version {}",
                        persisted.version
                    )));
                }
                persisted.tabs
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
            Err(error) => return Err(error.into()),
        };
        for tab in &mut tabs {
            for pane in &mut tab.panes {
                // Pane names are generated. Legacy custom labels are discarded.
                pane.name = default_pane_name(&pane.cwd, &pane.shell);
                if let Some(agent) = &mut pane.agent_terminal {
                    if agent.phase == aow_protocol::AgentTerminalPhase::Starting {
                        agent.phase = aow_protocol::AgentTerminalPhase::Failed;
                        agent.error = Some("AoW restarted during agent initialization".into());
                    }
                }
            }
            migrate_terminal_names(tab);
        }
        validate_persisted_tabs(&tabs)?;
        let manager = Self {
            inner: Arc::new(ManagerInner {
                metadata_path: Some(metadata_path),
                state: Mutex::new(ManagerState {
                    tabs,
                    ..ManagerState::default()
                }),
                terminald,
                daemon_instance_id: Mutex::new(None),
                operation: tokio::sync::Mutex::new(()),
                runtime_sync: tokio::sync::Mutex::new(()),
                agent_operations: Mutex::new(HashMap::new()),
                hosting_gates: Mutex::new(HashMap::new()),
                hosting_workers: Mutex::new(HashSet::new()),
                clipboard,
                clipboard_operation: tokio::sync::Mutex::new(()),
                task_stops: tokio::sync::broadcast::channel(128).0,
                task_completions: tokio::sync::broadcast::channel(128).0,
                notifications_started: std::sync::atomic::AtomicBool::new(false),
            }),
        };
        manager.start_clipboard_cleanup();
        Ok(manager)
    }

    fn start_clipboard_cleanup(&self) {
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return;
        };
        let inner = Arc::downgrade(&self.inner);
        handle.spawn(async move {
            let mut interval = tokio::time::interval(CLIPBOARD_CLEANUP_INTERVAL);
            interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            interval.tick().await;
            loop {
                interval.tick().await;
                let Some(inner) = inner.upgrade() else {
                    break;
                };
                let _operation = inner.clipboard_operation.lock().await;
                if let Err(error) = inner.clipboard.clean_expired() {
                    tracing::warn!(%error, "failed to clean expired clipboard images");
                }
            }
        });
    }

    pub(in crate::terminal) fn lock_state(
        &self,
    ) -> Result<MutexGuard<'_, ManagerState>, TerminalError> {
        self.inner.state.lock().map_err(|_| TerminalError::Poisoned)
    }

    pub(in crate::terminal) fn persist_locked(
        &self,
        state: &ManagerState,
    ) -> Result<(), TerminalError> {
        let Some(path) = &self.inner.metadata_path else {
            return Ok(());
        };
        atomic_save(
            path,
            &PersistedState {
                version: METADATA_VERSION,
                tabs: state.tabs.clone(),
            },
        )
    }
}

