            },
            AgentLaunch {
                agent_type: aow_agents::launch::AgentType::Codex,
                display_name: "Test Agent".to_owned(),
                executable: "/bin/sh".to_owned(),
                args: vec!["-c".to_owned(), "sleep 30".to_owned()],
                env: Default::default(),
            },
        )
        .await
        .unwrap();
