import { ReactNode, useEffect, useState } from 'react';
import { authStatus } from './authApi';
import { AuthScreen } from './AuthScreen';
import { loginMethods } from './loginMethods';
import type { AuthStatus, LoginMethodProps } from './types';
import './auth.css';

export function LoginGate({ children }: { children: ReactNode }) {
  const [status, setStatus] = useState<AuthStatus>();
  const [loadError, setLoadError] = useState<string>();

  useEffect(() => {
    let active = true;
    void authStatus()
      .then((next) => { if (active) setStatus(next); })
      .catch((error: unknown) => { if (active) setLoadError(error instanceof Error ? error.message : '无法读取登录状态'); });
    return () => { active = false; };
  }, []);

  useEffect(() => {
    if (!status?.authenticated) return;
    let active = true;
    const check = () => {
      if (document.visibilityState === 'hidden') return;
      void authStatus().then(next => { if (active) setStatus(next); }).catch(() => {});
    };
    const timer = window.setInterval(check, 30_000);
    document.addEventListener('visibilitychange', check);
    return () => { active = false; window.clearInterval(timer); document.removeEventListener('visibilitychange', check); };
  }, [status?.authenticated]);

  if (loadError) return <AuthScreen title="无法连接 AoW" detail={loadError} retry={() => window.location.reload()} />;
  if (!status) return <AuthScreen title="正在检查登录状态…" />;
  if (!status.configured) return <AuthScreen title="尚未配置登录方式" detail={status.message ?? '请在服务器上完成登录配置。'} />;
  if (status.authenticated) return <>{children}</>;
  return <LoginMethods status={status} onSuccess={setStatus} />;
}

function LoginMethods({ status, onSuccess }: { status: AuthStatus } & LoginMethodProps) {
  const [selected, setSelected] = useState<string>();
  const available = (status.methods ?? [{ id: 'password', label: '账号密码', configured: true }])
    .filter(method => method.configured && loginMethods.has(method.id));
  const method = available.find(method => method.id === selected) ?? available[0];
  const Form = method && loginMethods.get(method.id);
  if (!Form) return <AuthScreen title="当前页面不支持此登录方式" detail="请刷新页面或更新客户端后重试。" retry={() => window.location.reload()} />;

  return <AuthScreen title="登录 AoW">
    {available.length > 1 && <div className="aow-auth-methods" role="group" aria-label="登录方式">
      {available.map(option => <button key={option.id} type="button" aria-pressed={method.id === option.id} onClick={() => setSelected(option.id)}>{option.label}</button>)}
    </div>}
    <Form key={method.id} onSuccess={onSuccess} />
  </AuthScreen>;
}

import { useState } from 'react';
import { LogOut } from 'lucide-react';
import { logout } from './authApi';

export function LogoutButton({ disabled = false, compact = false, className }: { disabled?: boolean; compact?: boolean; className?: string }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();
  const leave = async () => {
    if (busy) return;
    setBusy(true);
    setError(undefined);
    try {
      await logout();
      window.location.reload();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : '退出登录失败，请重试。');
      setBusy(false);
    }
  };
  return <>
    <button type="button" className={className} disabled={disabled || busy} aria-label="退出登录" title="退出登录" onClick={() => void leave()}>
      <LogOut size={18} />{!compact && <span>{busy ? '正在退出…' : '退出登录'}</span>}
    </button>
    {error && <span role="alert" className="aow-auth-error">{error}</span>}
  </>;
}

import { FormEvent, useRef, useState } from 'react';
import { login } from './authApi';
import type { LoginMethodProps } from './types';

export function PasswordLogin({ onSuccess }: LoginMethodProps) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string>();
  const [submitting, setSubmitting] = useState(false);
  const submittingRef = useRef(false);

  const submit = async () => {
    if (submittingRef.current) return;
    if (!username || !password) {
      setError('请输入账号和密码。');
      return;
    }
    submittingRef.current = true;
    setSubmitting(true);
    setError(undefined);
    try {
      const result = await login('password', { username, password });
      onSuccess(result);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : '登录失败，请重试。');
      setPassword('');
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  };

  const onSubmit = (event: FormEvent) => {
    event.preventDefault();
    void submit();
  };

  return <>
    <p>请输入首次安装时设置的账号和密码。</p>
    <form onSubmit={onSubmit}>
      <label htmlFor="aow-username">账号</label>
      <input id="aow-username" name="username" autoComplete="username" autoFocus autoCapitalize="none" spellCheck={false} placeholder="请输入账号" type="text" value={username} required disabled={submitting} onChange={(event) => { setUsername(event.target.value); setError(undefined); }} />
      <label htmlFor="aow-password">密码</label>
      <input id="aow-password" name="password" autoComplete="current-password" placeholder="请输入密码" type="password" value={password} required disabled={submitting} onChange={(event) => { setPassword(event.target.value); setError(undefined); }} />
      {error && <p className="aow-auth-error" role="alert">{error}</p>}
      <button type="submit" disabled={submitting}>{submitting ? '正在验证…' : '登录'}</button>
    </form>
  </>;
}

