import { appUrl } from '../../lib/basePath';
import type { AuthStatus } from './types';

export async function authStatus(): Promise<AuthStatus> {
  const response = await fetch(appUrl('/api/auth/status'), { cache: 'no-store' });
  if (!response.ok) throw new Error(`无法读取登录状态（HTTP ${response.status}）`);
  return response.json() as Promise<AuthStatus>;
}

export async function login(method: string, credentials: Record<string, unknown>): Promise<AuthStatus> {
  const response = await fetch(appUrl('/api/auth/login'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...credentials, method }),
  });
  const payload = await response.json().catch(() => null) as AuthStatus | null;
  if (!response.ok) throw new Error(payload?.message ?? `登录失败（HTTP ${response.status}）`);
  if (!payload?.authenticated) throw new Error('登录未完成，请重试。');
  return payload;
}

export async function logout(): Promise<void> {
  const response = await fetch(appUrl('/api/auth/logout'), { method: 'POST', cache: 'no-store' });
  if (!response.ok) throw new Error(`退出登录失败（HTTP ${response.status}）`);
}

import type { ComponentType } from 'react';
import { PasswordLogin } from './PasswordLogin';
import type { LoginMethodProps } from './types';

// IDs match the server provider registry. Each method owns only its input flow;
// the gate, successful-login state, and API transport remain shared.
export const loginMethods: ReadonlyMap<string, ComponentType<LoginMethodProps>> = new Map([
  ['password', PasswordLogin],
]);

export interface LoginMethodStatus {
  id: string;
  label: string;
  configured: boolean;
  message?: string;
}

export interface AuthStatus {
  configured: boolean;
  authenticated: boolean;
  message?: string;
  // Older servers and existing embedded fixtures only expose the two flags.
  methods?: LoginMethodStatus[];
}

export interface LoginMethodProps {
  onSuccess: (status: AuthStatus) => void;
}

import { newestRunFirst } from './runOrder';
