  wordWrapOverride?: boolean;
  onWordWrapChange: (id: string, enabled: boolean) => void;
  onActivate: (id: string) => void; onClose: (id: string) => boolean;
  onCloseOthers: (id: string) => boolean; onCloseAll: () => boolean;
