import { useLayoutEffect, useRef, useState } from 'react';
import { filesApi } from './api';

interface Upload {
  id: number;
  file: File;
  directory: string;
  status: 'waiting' | 'uploading' | 'success' | 'error';
  loaded: number;
  path?: string;
  error?: string;
}

export function useExplorerUploads(root: string, onUploaded: (directory: string, path: string) => Promise<void>) {
  const [uploads, setUploads] = useState<Upload[]>([]);
  const queue = useRef<Upload[]>([]);
  const nextId = useRef(0);
  const epoch = useRef(0);
  const running = useRef(false);
  const controller = useRef<AbortController | undefined>(undefined);
  const completed = useRef(onUploaded);
  useLayoutEffect(() => { completed.current = onUploaded; });
  useLayoutEffect(() => {
    setUploads([]);
    return () => {
      epoch.current += 1;
      queue.current = [];
      controller.current?.abort();
      running.current = false;
    };
  }, [root]);

  const enqueue = (directory: string, files: File[]) => {
    if (!files.length) return;
    const items: Upload[] = files.map((file) => ({ id: ++nextId.current, file, directory, status: 'waiting', loaded: 0 }));
    queue.current.push(...items);
    setUploads((previous) => [...previous, ...items]);
    if (running.current) return;
    running.current = true;
    const generation = epoch.current;
    const update = (id: number, changes: Partial<Upload>) => {
      if (epoch.current === generation) setUploads((previous) => previous.map((item) => item.id === id ? { ...item, ...changes } : item));
    };
    void (async () => {
      try {
        while (queue.current.length && epoch.current === generation) {
          const item = queue.current.shift()!;
          const abort = new AbortController();
          controller.current = abort;
          update(item.id, { status: 'uploading' });
          try {
            if (!item.file.name || item.file.name === '.' || item.file.name === '..' || /[/\\\0]/.test(item.file.name)) {
              throw new Error('文件名无效，请重新选择文件');
            }
            const result = await filesApi.uploadFile(item.directory, item.file, (loaded) => update(item.id, { loaded }), { keepBoth: true, signal: abort.signal });
            if (epoch.current !== generation) return;
            update(item.id, { status: 'success', path: result.path, loaded: item.file.size });
            try { await completed.current(item.directory, result.path); }
            catch (reason) { update(item.id, { error: `文件已上传，目录刷新失败：${reason instanceof Error ? reason.message : String(reason)}` }); }
          } catch (reason) {
            update(item.id, { status: 'error', error: reason instanceof Error ? reason.message : String(reason) });
          }
        }
      } finally {
        if (epoch.current === generation) { running.current = false; controller.current = undefined; }
      }
    })();
  };

  return {
    uploads, enqueue,
    cancel: () => {
      const waiting = new Set(queue.current.map((item) => item.id));
      queue.current = [];
      controller.current?.abort();
      setUploads((previous) => previous.map((item) => waiting.has(item.id) ? { ...item, status: 'error', error: '上传已取消' } : item));
    },
    clear: () => setUploads((previous) => previous.filter((item) => item.status === 'waiting' || item.status === 'uploading')),
    retry: (item: Upload) => {
      setUploads((previous) => previous.filter((previous) => previous.id !== item.id));
      enqueue(item.directory, [item.file]);
    },
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { filesApi } from './api';
import type { PinnedDirectories } from './types';

export function usePinnedDirectories() {
  const [paths, setPaths] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [pending, setPending] = useState<Set<string>>(() => new Set());
  const pendingRef = useRef(new Set<string>());
  const revisionRef = useRef(-1);
  const reloadRef = useRef(0);

  const accept = useCallback((result: PinnedDirectories) => {
    if (result.revision < revisionRef.current) return;
    revisionRef.current = result.revision;
    setPaths(result.paths);
  }, []);

  const reload = useCallback(async () => {
    const generation = ++reloadRef.current;
    setLoading(true);
    setError('');
    try {
      const result = await filesApi.pinnedDirectories();
      if (generation === reloadRef.current) accept(result);
    } catch (reason) {
      if (generation === reloadRef.current) setError(`收藏加载失败：${reason instanceof Error ? reason.message : String(reason)}`);
    } finally {
      if (generation === reloadRef.current) setLoading(false);
    }
  }, [accept]);

  useEffect(() => { void reload(); }, [reload]);

  const toggle = useCallback(async (path: string, pinned: boolean) => {
    if (pendingRef.current.has(path)) return;
    pendingRef.current.add(path);
    setPending(new Set(pendingRef.current));
    setError('');
    try {
      accept(await filesApi.updatePinnedDirectories(pinned ? { remove: [path] } : { add: [path] }));
    } catch (reason) {
      setError(`收藏保存失败：${reason instanceof Error ? reason.message : String(reason)}`);
    } finally {
      pendingRef.current.delete(path);
      setPending(new Set(pendingRef.current));
    }
  }, [accept]);

  return { paths, loading, error, pending, reload, toggle };
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Check, Copy, ExternalLink, GitCommitHorizontal, LoaderCircle, X } from 'lucide-react';
import type { GitCommit, GitCommitDetail } from './types';

interface Props {
  commit: GitCommit;
  detail?: GitCommitDetail;
  loading: boolean;
  error?: string;
  anchor: HTMLElement;
  pinned: boolean;
  upstream?: string;
  onEnter: () => void;
  onLeave: () => void;
  onClose: () => void;
}

const margin = 8;
const gap = 8;
const desiredWidth = 430;

function relativeTime(value: string) {
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) return value;
  const seconds = Math.round((timestamp - Date.now()) / 1000);
  const ranges: [Intl.RelativeTimeFormatUnit, number][] = [
    ['year', 31_536_000], ['month', 2_592_000], ['week', 604_800],
    ['day', 86_400], ['hour', 3_600], ['minute', 60],
  ];
  const formatter = new Intl.RelativeTimeFormat('zh-CN', { numeric: 'auto' });
  for (const [unit, size] of ranges) {
    if (Math.abs(seconds) >= size) return formatter.format(Math.round(seconds / size), unit);
  }
  return formatter.format(seconds, 'second');
}

function absoluteTime(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'medium' }).format(date);
}

async function copyText(value: string) {
  if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(value); return; }
  const input = document.createElement('textarea');
  input.value = value; input.style.position = 'fixed'; input.style.opacity = '0';
  document.body.appendChild(input); input.select(); document.execCommand('copy'); input.remove();
}

function shortId(value: string) { return value.slice(0, 8); }

export function CommitDetailPopover({ commit, detail, loading, error, anchor, pinned, upstream, onEnter, onLeave, onClose }: Props) {
  const card = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ left: margin, top: margin, width: desiredWidth });
  const [copied, setCopied] = useState(false);
  const popoverId = `commit-detail-${commit.id}`;

  const updatePosition = () => {
    if (!anchor.isConnected) { onClose(); return; }
    const rect = anchor.getBoundingClientRect();
    if (rect.bottom < 0 || rect.top > window.innerHeight) { onClose(); return; }
    const maximumWidth = Math.max(1, window.innerWidth - margin * 2);
    const width = Math.min(desiredWidth, maximumWidth);
    const right = window.innerWidth - rect.right - gap - margin;
    const left = rect.left - gap - margin;
    let x = right >= Math.min(320, width) ? rect.right + gap : rect.left - gap - width;
    if (right < Math.min(320, width) && left < Math.min(320, width)) x = rect.right + gap;
    x = Math.max(margin, Math.min(x, window.innerWidth - width - margin));
    const height = card.current?.getBoundingClientRect().height ?? 320;
    const y = Math.max(margin, Math.min(rect.top - 6, window.innerHeight - height - margin));
    setPosition({ left: x, top: y, width });
  };

  useLayoutEffect(updatePosition, [anchor, detail, loading, error]);
  useEffect(() => {
    const update = () => updatePosition();
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => { window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); };
  });
  useEffect(() => { setCopied(false); }, [commit.id]);
  useEffect(() => {
    if (pinned) card.current?.focus({ preventScroll: true });
  }, [pinned, commit.id]);

  const identityChanged = detail && (detail.author.name !== detail.committer.name || detail.author.email !== detail.committer.email || detail.author.date !== detail.committer.date);
  const stats = detail?.stats;

  return createPortal(
    <div
      ref={card}
      id={popoverId}
      className={`commit-detail-popover${pinned ? ' pinned' : ''}`}
      role="dialog"
      aria-label={`提交详情：${commit.subject}`}
      tabIndex={-1}
      style={position}
      onPointerEnter={onEnter}
      onPointerLeave={onLeave}
      onFocusCapture={onEnter}
      onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) onLeave(); }}
    >
      {pinned ? <button className="commit-detail-close" title="关闭" onClick={onClose}><X /></button> : null}
      {loading ? <div className="commit-detail-loading"><LoaderCircle className="spinning" />正在加载提交详情…</div> : null}
      {error ? <div className="commit-detail-error">{error}</div> : null}
      {detail ? <>
        <div className="commit-detail-author">
          <span className="commit-avatar">{detail.author.name.trim().charAt(0).toUpperCase() || '?'}</span>
          <div><strong>{detail.author.name}</strong><span>{detail.author.email}</span></div>
          <time title={absoluteTime(detail.author.date)}>{relativeTime(detail.author.date)}</time>
        </div>
        <h4>{detail.subject}</h4>
        {detail.body.trim() ? <pre className="commit-detail-body">{detail.body.trim()}</pre> : null}
        {identityChanged ? <div className="commit-detail-committer">提交者：{detail.committer.name} &lt;{detail.committer.email}&gt; · {absoluteTime(detail.committer.date)}</div> : null}
        {stats ? <div className="commit-detail-stats">
          <span>{stats.files_changed} 个文件变更</span>
          <b>+{stats.insertions}</b><em>-{stats.deletions}</em>
          {stats.binary_files ? <span>{stats.binary_files} 个二进制文件</span> : null}
        </div> : null}
        <div className="commit-detail-meta">
          <span className={`commit-sync-state ${commit.is_pushed ? 'pushed' : 'outgoing'}`}>{commit.is_pushed ? `已推送${upstream ? ` · ${upstream}` : ''}` : '仅本地'}</span>
          {detail.refs.map((ref) => <span className="commit-detail-ref" key={ref}>{ref}</span>)}
        </div>
        {detail.parents.length > 1 ? <div className="commit-detail-parents"><span>Parents</span>{detail.parents.map((parent) => <code key={parent}>{shortId(parent)}</code>)}</div> : null}
        <footer className="commit-detail-footer">
          <GitCommitHorizontal /><code title={detail.id}>{detail.id}</code>
          <button title="复制 commit SHA" onClick={() => { void copyText(detail.id).then(() => { setCopied(true); window.setTimeout(() => setCopied(false), 1200); }); }}>{copied ? <Check /> : <Copy />}</button>
          {detail.commit_url ? <a href={detail.commit_url} target="_blank" rel="noopener noreferrer"><ExternalLink />在 {detail.remote_name ?? '远程仓库'} 中打开</a> : null}
        </footer>
      </> : null}
    </div>,
    document.body,
  );
}

import { GitBranch } from 'lucide-react';
import { gitApi } from './api';
import { filesApi } from '../files/api';
import { FileTypeIcon } from '../files/FileTypeIcon';
import { MobilePageHeader, MobileRefresh, MobileState } from '../../mobile/MobilePrimitives';
import { useMobileResource, useMobileScroll, type MobileRoute } from '../../mobile/mobileState';
import type { MobileNavigate } from '../../mobile/mobileState';

export function MobileGit({ route, visible, navigate, back }: { route: MobileRoute; visible: boolean; navigate: MobileNavigate; back: () => void }) {
  const status = useMobileResource(`git.${route.workspace}`, () => gitApi.gitStatus(route.workspace), visible && !route.diff);
  const scroll = useMobileScroll(`git.${route.workspace}`, !!status.data);
  if (route.diff) return <MobileDiff route={route} back={back} />;
  return <section className="mobile-content-page">
    <MobilePageHeader title="Git 变更" actions={<MobileRefresh reload={status.reload} loading={status.loading} />} />
    <div className="mobile-scroll" ref={scroll}>
      {status.data && <div className="mobile-branch-card"><GitBranch size={23} /><div><strong>{status.data.branch || 'Detached HEAD'}</strong><span>{status.data.files.length} 个变更 · 领先 {status.data.ahead} / 落后 {status.data.behind}</span></div></div>}
      <MobileState loading={status.loading && !status.data} error={status.error} retry={status.reload} empty={status.data?.files.length === 0 ? '工作区干净，暂无文件变更。' : undefined} />
      <div className="mobile-list">{status.data?.files.map((file) => <div key={file.path} className="mobile-git-row">
        <div className="mobile-git-file"><FileTypeIcon path={file.path} /><span>{file.path}</span></div>
        <div className="mobile-git-actions">
          {file.index_status !== ' ' && file.index_status !== '?' && <button onClick={() => navigate({ workspace: route.workspace, view: 'git', diff: file.path, staged: '1' })}><b>{file.index_status}</b>已暂存 · 查看 Diff</button>}
          {file.worktree_status !== ' ' && <button onClick={() => navigate({ workspace: route.workspace, view: 'git', diff: file.path, untracked: file.worktree_status === '?' ? '1' : undefined })}><b>{file.worktree_status}</b>{file.worktree_status === '?' ? '未跟踪' : '工作区'} · 查看 Diff</button>}
        </div>
      </div>)}</div>
    </div>
  </section>;
}

function MobileDiff({ route, back }: { route: MobileRoute; back: () => void }) {
  const repository = route.repository ?? route.workspace;
  const diff = useMobileResource(`diff.${repository}.${route.diff}.${route.staged}.${route.commit}.${route.originalPath}`, async () => {
    const result = route.commit ? await gitApi.gitCommitDiff(repository, route.commit, route.diff!, route.originalPath)
      : await gitApi.gitDiff(repository, route.diff, route.staged === '1');
    if (route.untracked === '1' && !result.patch && result.modified == null) {
      result.patch = (await filesApi.readText(`${repository}/${route.diff}`)).content.split('\n').map(line => '+' + line).join('\n');
    }
    return result;
  });
  const scroll = useMobileScroll(`diff.${route.workspace}.${route.diff}.${route.staged}`, !!diff.data);
  return <section className="mobile-content-page">
    <MobilePageHeader title={route.diff!.split('/').pop()!} subtitle={route.commit ? `Commit ${route.commit.slice(0, 8)}` : route.staged === '1' ? '已暂存变更' : '工作区变更'} back={back} actions={<MobileRefresh reload={diff.reload} loading={diff.loading} />} />
    <div className="mobile-scroll mobile-diff-reader" ref={scroll}>
      <MobileState loading={diff.loading && !diff.data} error={diff.error} retry={diff.reload} empty={diff.data && !diff.data.patch ? '暂无文本差异，文件可能是二进制格式。' : undefined} />
      {diff.data?.truncated && <div className="mobile-inline-error">差异较大，仅展示部分内容。</div>}
      <pre className="mobile-diff">{diff.data?.patch.split('\n').map((line, index) => <span key={index} className={line.startsWith('@@') ? 'hunk' : line.startsWith('+') ? 'added' : line.startsWith('-') ? 'removed' : ''}>{line || ' '}<br /></span>)}</pre>
    </div>
  </section>;
}

import { appLocalStorage } from '../../lib/basePath';
import { Fragment, memo, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import {
  ArrowDown, ArrowUp, Check, ChevronDown, ChevronRight, Cloud, FileDiff, GitBranch, History, List,
  MoreHorizontal, RefreshCw, TreePine,
} from 'lucide-react';
import { gitApi } from './api';
import { useSourceControlPolling } from './useSourceControlPolling';
import { SourceControlChanges, type ChangeItem } from './SourceControlChanges';
import { buildCommitGraph, type CommitGraphRow } from './commitGraph';
import type { GitCommit, GitCommitDetail, GitCommitFile, GitFileStatus, RepositorySummary } from './types';
import { CommitDetailPopover } from './CommitDetailPopover';
import { AowIconButton } from '../../components/AowIconButton';
import { AowPanel, AowPanelStack } from '../../components/AowPanel';

type Layout = 'list' | 'tree';
type CommitState = 'outgoing' | 'pushed';

interface Props {
  root: string;
  visible: boolean;
  refreshGeneration?: number;
  activeDocumentId?: string;
  onOpenDiff: (repo: string, file: GitFileStatus, staged: boolean) => void;
  onOpenCommitDiff: (repo: string, commit: GitCommit, file: GitCommitFile) => void;
  fixedRepository?: RepositorySummary;
  titleCase?: boolean;
  aowHeader?: boolean;
}
interface CommitPopoverState { commit: GitCommit; anchor: HTMLElement; pinned: boolean }
interface CommitDetailCacheEntry { detail?: GitCommitDetail; loading?: boolean; error?: string }
interface SectionHeaderProps {
  title: string;
  icon: ReactNode;
  aow?: boolean;
  hideLegacyHeader?: boolean;
  collapsed?: boolean;
  controlsId?: string;
