type RefreshTarget = 'all' | 'changes' | 'commits';
interface Callbacks {
  status: (status: GitStatus) => void;
  log: (log: GitLog) => void;
  error: (message: string) => void;
}

// One round per visible panel. Manual requests and save notifications share
// the same queue; a slow round never accumulates interval ticks.
export function useSourceControlPolling(repository: string, visible: boolean, generation: number, callbacks: Callbacks) {
  const latest = useRef({ repository, visible, callbacks });
  latest.current = { repository, visible, callbacks };
  const refreshRef = useRef<(mask: number) => void>(() => {});
  const previousGeneration = useRef(generation);

  useEffect(() => {
    if (!repository || !visible) return;
    let disposed = false;
    let timer: number | undefined;
    let controller: AbortController | undefined;
    let pending = 0;
    const errors = new Map<number, string>();
    const active = () => !disposed && latest.current.visible
      && latest.current.repository === repository && document.visibilityState === 'visible';
    const clearTimer = () => { window.clearTimeout(timer); timer = undefined; };
    const refresh = async (mask: number) => {
      if (!active()) return;
      clearTimer();
      if (controller) { pending |= mask; return; }
      const request = new AbortController();
      controller = request;
      const run = async <T,>(key: number, load: () => Promise<T>, apply: (value: T) => void) => {
        try {
          const result = await load();
          if (!active() || request.signal.aborted) return;
          apply(result);
          errors.delete(key);
        } catch (reason) {
          if (!active() || request.signal.aborted) return;
          errors.set(key, `${key === 1 ? 'Changes' : 'Commits'}：${reason instanceof Error ? reason.message : String(reason)}`);
        }
      };
      await Promise.all([
        mask & 1 ? run(1, () => gitApi.gitStatus(repository, request.signal), (value) => latest.current.callbacks.status(value)) : undefined,
        mask & 2 ? run(2, () => gitApi.gitLog(repository, request.signal), (value) => latest.current.callbacks.log(value)) : undefined,
      ]);
      controller = undefined;
      if (!active()) return;
      if (!request.signal.aborted) latest.current.callbacks.error([...errors.values()].join('；'));
      if (pending) {
        const next = pending; pending = 0;
        void refresh(next);
      } else {
        // Working files can change without touching Git metadata. History is
        // refreshed by metadata events (or retried after a failed log request).
        timer = window.setTimeout(() => void refresh(errors.has(2) ? 3 : 1), 5_000);
      }
    };
    const onVisibilityChange = () => {
      clearTimer();
      if (document.visibilityState === 'visible') void refresh(3);
      else { pending = 0; controller?.abort(); }
    };
    refreshRef.current = (mask) => void refresh(mask);
    const unsubscribe = subscribeWorkspaceChanges(change => {
      if (change.reset || change.repositories.has(repository)) void refresh(3);
    });
    document.addEventListener('visibilitychange', onVisibilityChange);
    void refresh(3);
    return () => {
      disposed = true;
      unsubscribe();
      refreshRef.current = () => {};
      clearTimer();
      controller?.abort();
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [repository, visible]);

  useEffect(() => {
    if (previousGeneration.current !== generation) refreshRef.current(1);
    previousGeneration.current = generation;
  }, [generation]);

  return useCallback((target: RefreshTarget = 'all') => refreshRef.current(target === 'changes' ? 1 : target === 'commits' ? 2 : 3), []);
}

import { useCallback, useEffect, useState } from 'react';
import { notificationsApi } from '../notifications/api';
import type { NotificationSettings } from '../notifications/types';
import { imApi } from './api';
import { WechatSettings } from './WechatSettings';
import './im-settings.css';

export function ImSettingsPanel({ onBusyChange, onDirtyChange }: { onBusyChange: (busy: boolean) => void; onDirtyChange?: (dirty: boolean) => void }) {
  const [settings, setSettings] = useState<NotificationSettings>();
  const [appId, setAppId] = useState('');
  const [secret, setSecret] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [wechatBusy, setWechatBusy] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState('');
  const feishu = settings?.im.providers.find(provider => provider.provider === 'feishu');
  const wechat = settings?.im.providers.find(provider => provider.provider === 'wechat');
  const dirty = !!settings && (appId !== (feishu?.app_id ?? '') || !!secret);
  useEffect(() => { onDirtyChange?.(dirty); return () => onDirtyChange?.(false); }, [dirty, onDirtyChange]);
  useEffect(() => {
    let active = true;
    void notificationsApi.notificationSettings().then(next => {
      if (!active) return;
      setSettings(next); setAppId(next.im.providers.find(provider => provider.provider === 'feishu')?.app_id ?? '');
    }).catch(reason => { if (active) setError(String(reason)); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);
  useEffect(() => { onBusyChange(busy || wechatBusy); }, [busy, wechatBusy, onBusyChange]);
  const refresh = useCallback(async () => { setSettings(await notificationsApi.notificationSettings()); }, []);
  const changed = () => { setError(''); setSaved(''); };
  const save = async (remove = false) => {
    setBusy(true); changed();
    try {
      const next = remove ? await imApi.removeFeishu() : await imApi.saveFeishu(appId.trim(), secret.trim() || undefined);
      setSettings(next); setAppId(next.im.providers.find(provider => provider.provider === 'feishu')?.app_id ?? '');
      setSecret(''); setSaved('IM 配置已保存。');
    } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); }
    finally { setBusy(false); }
  };
  const unavailable = loading || busy || wechatBusy || !settings;
  return <div className="notification-settings-form project-aow-dialog-form">
    <div className="project-aow-dialog-body">
      <div className="project-aow-settings-heading"><div><h2>IM</h2><p>配置机器人，在飞书或微信中接收通知。</p></div></div>
      {loading && <p role="status">加载配置中…</p>}
      <WechatSettings provider={wechat} disabled={loading || busy || !settings} onChanged={refresh} onBusyChange={setWechatBusy} />
      <form id="im-feishu-settings" onSubmit={event => { event.preventDefault(); void save(); }}>
        <h3>飞书 Bot {feishu && <small className="notification-configured">已配置</small>}</h3>
        <label className="project-aow-dialog-field"><span>App ID</span><input aria-label="飞书 App ID" value={appId} disabled={unavailable} spellCheck={false} autoComplete="off" onChange={event => { setAppId(event.target.value); changed(); }} placeholder="cli_…" required /></label>
        <label className="project-aow-dialog-field"><span>App Secret</span><input aria-label="飞书 App Secret" type="password" value={secret} disabled={unavailable} autoComplete="new-password" onChange={event => { setSecret(event.target.value); changed(); }} placeholder={feishu?.app_id === appId.trim() ? '已保存，留空保留现有密钥' : '填写应用密钥'} required={!feishu || feishu.app_id !== appId.trim()} /></label>
        <p className="project-aow-form-intro">使用企业自建应用，在飞书开发者后台开启机器人能力并发布。消息发送给应用所有者，所有者需在可用范围内。</p>
        <p className="project-aow-form-intro">需要开通“管理应用自身资源”和“以应用的身份发消息”权限。保存后，可在“通知”中选择飞书推送。</p>
      </form>
      {saved && <p role="status">{saved}</p>}
      {error && <div role="alert" className="project-aow-error">{error}</div>}
    </div>
    <footer className="project-aow-dialog-footer">
      {feishu && <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => void save(true)}>移除飞书配置</button>}
      <button type="submit" form="im-feishu-settings" className="project-aow-dialog-button primary" disabled={unavailable || !appId.trim()}>{busy ? '保存中…' : '保存'}</button>
    </footer>
  </div>;
}

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { imApi } from './api';
import type { ImProviderView, WechatLogin, WechatStatus, WechatVerification } from './types';

const failure = (reason: unknown) => reason instanceof Error ? reason.message : String(reason);
const polling = (login: WechatLogin) => ['wait', 'scaned', 'scaned_but_redirect'].includes(login.status);

function SetupStep({ number, title, complete, current, children }: {
  number: number; title: string; complete: boolean; current: boolean; children: ReactNode;
}) {
  return <li className={`im-wechat-step${complete ? ' complete' : ''}`} aria-current={current ? 'step' : undefined}>
    <div className="im-wechat-step-heading"><span className="im-wechat-step-number" aria-hidden="true">{number}</span>
      <h4>{title}</h4><span className="im-wechat-step-state">{complete ? '已完成' : current ? '当前步骤' : '待完成'}</span></div>
    <div className="im-wechat-step-body">{children}</div>
  </li>;
}

export function WechatSettings({ provider, disabled, onChanged, onBusyChange }: {
  provider?: Extract<ImProviderView, { provider: 'wechat' }>;
  disabled: boolean; onChanged: () => Promise<void>; onBusyChange: (busy: boolean) => void;
}) {
  const [login, setLogin] = useState<WechatLogin>();
  const [cycle, setCycle] = useState(0);
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [testing, setTesting] = useState(false);
  const [statusCycle, setStatusCycle] = useState(0);
  const [statusError, setStatusError] = useState('');
  const [connection, setConnection] = useState<WechatStatus['connection']>(null);
  const mounted = useRef(true);
  const currentId = useRef<string | undefined>(undefined);
  const statusVersion = useRef(0);
  const operating = useRef(false);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      if (currentId.current) void imApi.cancelWechat(currentId.current).catch(() => {});
    };
  }, []);

  useEffect(() => {
    setConnection(null);
  }, [provider?.account_id, provider?.user_id]);

  useEffect(() => {
    setStatusError('');
    if (!provider) return;
    let active = true;
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout>;
    const check = async () => {
      const version = statusVersion.current;
      try {
        if (!operating.current) {
          const status = await imApi.wechatStatus(controller.signal);
          if (active && !operating.current && version === statusVersion.current) {
            setConnection(status.connection); setStatusError('');
          }
        }
      } catch (reason) { if (active && version === statusVersion.current) setStatusError(failure(reason)); }
      if (active) timer = setTimeout(() => void check(), 5000);
    };
    void check();
    return () => { active = false; controller.abort(); clearTimeout(timer); };
  }, [provider?.account_id, provider?.user_id, statusCycle]);

  useEffect(() => {
    if (!login || !polling(login)) return;
    let active = true;
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout>;
    const id = login.id;
    const poll = async () => {
      try {
        const next = await imApi.pollWechat(id, undefined, controller.signal);
        if (!active) return;
        setLogin(next); setError('');
        if (next.status === 'confirmed') {
          currentId.current = undefined; statusVersion.current++; setConnection(null);
          setStatusCycle(value => value + 1); await onChanged();
        }
        else if (polling(next)) timer = setTimeout(() => void poll(), 1000);
      } catch (reason) { if (active) setError(failure(reason)); }
    };
    void poll();
    return () => { active = false; controller.abort(); clearTimeout(timer); };
    // The loop owns status changes; cycle explicitly resumes after verification/retry.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [login?.id, cycle, onChanged]);

  const operation = async (work: () => Promise<void>) => {
    operating.current = true; statusVersion.current++;
    setBusy(true); onBusyChange(true); setError('');
    try { await work(); } catch (reason) {
      if (mounted.current) { setError(failure(reason)); setStatusCycle(value => value + 1); }
    } finally {
      operating.current = false; statusVersion.current++;
      if (mounted.current) { setBusy(false); onBusyChange(false); }
    }
  };
  const start = () => operation(async () => {
    if (currentId.current) await imApi.cancelWechat(currentId.current);
    setLogin(undefined); setCode('');
    const next = await imApi.startWechat();
    if (!mounted.current) { await imApi.cancelWechat(next.id); return; }
    currentId.current = next.id; setLogin(next);
  });
  const cancel = () => operation(async () => {
    if (currentId.current) await imApi.cancelWechat(currentId.current);
    currentId.current = undefined; setLogin(undefined); setCode('');
  });
  const unavailable = disabled || busy;
  const pairing = !!login && (polling(login) || login.status === 'need_verifycode');
  const contextReady = !!provider && !!connection?.context_ready;
  const verification = pairing ? null : connection?.verification;
  const testResult = verification?.receipt ?? 'idle';
  const testSubmitted = testResult !== 'idle';
  const confirmed = testResult === 'confirmed';
  const step = !provider || pairing ? 1 : testSubmitted ? confirmed ? 0 : 4 : contextReady ? 3 : 2;
  const updateVerification = (verification: WechatVerification | null) => {
    setConnection(current => current && { ...current, verification });
  };
  const sendTest = () => operation(async () => {
    updateVerification(null); setTesting(true);
    try {
      const result = await imApi.testWechat();
      if (mounted.current) updateVerification(result.verification);
    } finally { if (mounted.current) setTesting(false); }
  });
  const receipt = (received: boolean) => operation(async () => {
    if (!verification) return;
    const result = await imApi.wechatReceipt(verification.test_id, received);
    if (mounted.current) updateVerification(result.verification);
  });
  return <section className="im-wechat" aria-label="微信 Bot 设置">
    <h3>微信 Bot {provider && <small className="notification-configured">{confirmed ? '已验证' : '已绑定'}</small>}</h3>
    <p className="project-aow-form-intro">使用普通微信扫码绑定，通知发送到扫码账号与 Bot 的私聊。目前不支持普通微信群。</p>
    <ol className="im-wechat-steps" aria-label="微信推送设置步骤">
      <SetupStep number={1} title="扫码绑定微信" complete={!!provider && !pairing} current={step === 1}>
        <p className="project-aow-form-intro">{provider ? `接收账号：${provider.user_id}` : '用接收通知的微信账号扫码，按手机提示完成授权。'}</p>
        <div className="im-actions">
          <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => void start()}>{login && login.status !== 'confirmed' ? '重新生成二维码' : provider ? '重新扫码绑定' : '扫码连接微信'}</button>
          {login && login.status !== 'confirmed' && <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => void cancel()}>关闭扫码</button>}
          {provider && <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => void operation(async () => {
            await imApi.disconnectWechat(); currentId.current = undefined; setLogin(undefined); setConnection(null); await onChanged();
          })}>解除微信绑定</button>}
        </div>
        {login && login.status !== 'confirmed' && <div className="im-wechat-login">
          {login.qr_image && <img className="im-wechat-qr" src={login.qr_image} alt="微信 Bot 登录二维码" width="256" height="256" />}
          <p role="status">{login.message}</p>
          {login.status === 'need_verifycode' && <form onSubmit={event => {
            event.preventDefault();
            if (unavailable || !code.trim()) return;
            void operation(async () => {
              const next = await imApi.pollWechat(login.id, code.trim());
              setCode(''); setLogin(next);
              if (next.status === 'confirmed') {
                currentId.current = undefined; setConnection(null); setStatusCycle(value => value + 1); await onChanged();
              }
              setCycle(value => value + 1);
            });
          }}>
            <label className="project-aow-dialog-field"><span>手机微信显示的数字</span><input aria-label="微信配对码" inputMode="numeric" pattern="[0-9]+" maxLength={16} autoComplete="off" value={code} disabled={unavailable} onChange={event => setCode(event.target.value)} required /></label>
            <button type="submit" className="project-aow-dialog-button" disabled={unavailable || !code.trim()}>确认配对码</button>
          </form>}
          {error && polling(login) && <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => { setError(''); setCycle(value => value + 1); }}>重试检查</button>}
        </div>}
      </SetupStep>
      <SetupStep number={2} title="在微信中向 Bot 发一条消息" complete={(contextReady || testSubmitted) && !pairing} current={step === 2}>
        <p className="project-aow-form-intro">绑定后，打开微信里的 Bot 私聊，发送一句“你好”。请保持本页面打开，AoW 收到后会自动更新状态。</p>
        {provider && <p className="im-wechat-progress" role="status">{statusError || connection?.error || (contextReady ? '已收到你的消息，可以发送测试通知。' : '等待接收你在微信中发送的消息…')}</p>}
        {provider && (!contextReady || statusError) && <div className="im-actions"><button type="button" className="project-aow-dialog-button" disabled={unavailable || pairing} onClick={() => setStatusCycle(value => value + 1)}>我已发送，检查状态</button></div>}
      </SetupStep>
      <SetupStep number={3} title="由 AoW 发送测试通知" complete={testSubmitted} current={step === 3}>
        <p className="project-aow-form-intro">{testSubmitted ? '测试请求已提交，请到微信查看“AoW 微信推送测试”。' : '收到你的消息后，点击下方按钮，让 AoW 向当前绑定的微信账号发送一条测试通知。'}</p>
        <div className="im-actions"><button type="button" className="project-aow-dialog-button primary" disabled={unavailable || pairing || !contextReady} onClick={() => void sendTest()}>{testing ? '正在发送…' : '发送微信测试消息'}</button></div>
      </SetupStep>
      <SetupStep number={4} title="确认微信收到通知" complete={confirmed} current={step === 4}>
        <p className="project-aow-form-intro">{confirmed ? '验证完成，记录已保存。请在 Settings → 通知中勾选“微信推送”，并保存通知设置。后续连接状态请查看第二步提示。' : '请以微信中实际出现测试通知为准，收到后点击“我已收到”。'}</p>
        {testResult === 'missing' && <p className="im-wechat-progress" role="status">请确认查看的是本次扫码账号与 Bot 的私聊。向 Bot 再发一条消息，然后重新发送测试通知；仍未收到时，可重新扫码绑定。</p>}
        {testSubmitted && !confirmed && <div className="im-actions">
          <button type="button" className="project-aow-dialog-button primary" disabled={unavailable || pairing} onClick={() => void receipt(true)}>我已收到</button>
          <button type="button" className="project-aow-dialog-button" disabled={unavailable || pairing} onClick={() => void receipt(false)}>还没收到</button>
        </div>}
        {confirmed && <p className="im-wechat-progress im-wechat-verified" role="status">已确认收到微信测试通知。</p>}
      </SetupStep>
    </ol>
    {error && <p className="project-aow-error" role="alert">{error}</p>}
  </section>;
}

import { aowRequest } from '../../lib/aowRequest';
import type { NotificationSettings } from '../notifications/types';
import type { WechatLogin, WechatStatus, WechatVerification } from './types';

export const imApi = {
  saveFeishu: (app_id: string, app_secret?: string) => aowRequest<NotificationSettings>('/api/aow/im/feishu', {
    method: 'PUT', body: JSON.stringify({ app_id, app_secret }),
  }),
  removeFeishu: () => aowRequest<NotificationSettings>('/api/aow/im/feishu', { method: 'DELETE' }),
  wechatStatus: (signal?: AbortSignal) => aowRequest<WechatStatus>('/api/aow/im/wechat', { cache: 'no-store', signal }),
  startWechat: () => aowRequest<WechatLogin>('/api/aow/im/wechat/login', { method: 'POST' }),
  pollWechat: (id: string, verify_code?: string, signal?: AbortSignal) => aowRequest<WechatLogin>(`/api/aow/im/wechat/login/${encodeURIComponent(id)}`, {
    method: 'POST', body: JSON.stringify({ verify_code }), signal,
  }),
  cancelWechat: (id: string) => aowRequest<void>(`/api/aow/im/wechat/login/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  disconnectWechat: () => aowRequest<NotificationSettings>('/api/aow/im/wechat', { method: 'DELETE' }),
  testWechat: () => aowRequest<{ message: string; verification: WechatVerification }>('/api/aow/im/wechat/test', { method: 'POST' }),
  wechatReceipt: (test_id: string, received: boolean) => aowRequest<{ verification: WechatVerification }>('/api/aow/im/wechat/test/receipt', {
    method: 'PUT', body: JSON.stringify({ test_id, received }),
  }),
};

