import { useEffect, useState } from 'react';
import { MarkdownContent } from '../../components/MarkdownContent';
import { inboxApi } from './api';
import { inboxError, type InboxComment } from './types';

export function InboxComments({ itemId, count }: { itemId: string; count: number }) {
  const [comments, setComments] = useState<InboxComment[]>();
  const [error, setError] = useState('');
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let active = true;
    setError('');
    void inboxApi.comments(itemId).then(next => {
      if (active) setComments(next);
    }).catch(reason => { if (active) setError(inboxError(reason)); });
    return () => { active = false; };
  }, [itemId, count, attempt]);
  return <section id={`inbox-comments-${itemId}`} className="inbox-comments" aria-label="需求评论">
    {!comments && !error && <p className="inbox-comments-loading" role="status">正在加载评论…</p>}
    {error && <p className="inbox-error" role="alert">{error}<button type="button" onClick={() => setAttempt(value => value + 1)}>重试加载评论</button></p>}
    {comments && <ol>{comments.map(comment => <li key={comment.id} data-comment-id={comment.id}>
      <header><span>{comment.author.name}</span><time dateTime={comment.created_at}>{new Date(comment.created_at).toLocaleString()}</time></header>
      <MarkdownContent text={comment.content} readOnly className="inbox-markdown" />
    </li>)}</ol>}
  </section>;
}

import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { createPortal } from 'react-dom';
import { LoaderCircle, Play, X } from 'lucide-react';
import type { AowProject } from '../../aow/types';
import type { AowAgent } from '../agents/types';
import type { InboxExecuteOptions, InboxItem } from './types';
import { WorkspaceSelect } from '../workspaces/WorkspaceSelect';
import { workspaceConfig, type WorkspaceConfig } from '../workspaces/types';

const interactiveAgent = (agent: AowAgent) => ['codex', 'traecli', 'hermes'].includes(agent.agent_type ?? agent.id);

export function InboxExecutePanel({ item, project, agents, busy, error, container, onClose, onSubmit }: {
  item: InboxItem;
  project: AowProject;
  agents: AowAgent[];
  busy: boolean;
  error?: string;
  container: HTMLElement;
  onClose: () => void;
  onSubmit: (options: InboxExecuteOptions) => void;
}) {
  const worktrees = [...project.worktrees].sort((left, right) => Number(right.is_main) - Number(left.is_main));
  const mainWorktree = worktrees[0];
  const availableAgents = agents.filter(agent => agent.available && interactiveAgent(agent));
  const [agent, setAgent] = useState(() => availableAgents[0]?.id ?? '');
  const [workspace, setWorkspace] = useState<WorkspaceConfig>({ workspace_mode: 'new_worktree', workspace_path: mainWorktree?.path ?? '', base_branch: '' });
  const [workspaceReady, setWorkspaceReady] = useState(false);
  const [appendPrompt, setAppendPrompt] = useState('');
  const dialog = useRef<HTMLElement>(null);
  const titleId = useId();

  useEffect(() => {
    const element = dialog.current;
    element?.querySelector<HTMLElement>('[aria-label="Agent"]')?.focus({ preventScroll: true });
  }, []);

  const finalPrompt = appendPrompt ? `${item.markdown}\n\n${appendPrompt}` : item.markdown;

  const onDialogKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
    event.stopPropagation();
    if (event.key === 'Escape') {
      event.preventDefault();
      if (!busy) onClose();
      return;
    }
    if (event.key !== 'Tab') return;
    const focusable = [...(dialog.current?.querySelectorAll<HTMLElement>(
      'button:not(:disabled),select:not(:disabled),input:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]',
    ) ?? [])];
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && (document.activeElement === first || !dialog.current?.contains(document.activeElement))) {
      event.preventDefault(); last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault(); first.focus();
    }
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (busy || !agent || !workspaceReady) return;
    onSubmit({ agent, ...workspaceConfig(workspace), append_prompt: appendPrompt });
  };


  return createPortal(<div className="inbox-execute-overlay" onPointerDown={event => {
    if (event.target === event.currentTarget && !busy) onClose();
  }}>
    <section ref={dialog} className="inbox-execute-panel" role="dialog" aria-modal="true" aria-labelledby={titleId} onKeyDown={onDialogKeyDown}>
    <form onSubmit={submit}>
      <header><div><Play size={15} /><div><h2 id={titleId}>执行需求</h2><p title={item.markdown}>{item.markdown.split(/\r?\n/, 1)[0]}</p></div></div><button type="button" aria-label="关闭" disabled={busy} onClick={onClose}><X size={16} /></button></header>
      <div className="inbox-execute-body">
        <label><span>Agent</span><select autoFocus aria-label="Agent" required value={agent} onChange={event => setAgent(event.target.value)} disabled={busy}>
          {!availableAgents.length && <option value="">没有可用的交互式 Agent</option>}
          {agents.map(option => <option key={option.id} value={option.id} disabled={!option.available || !interactiveAgent(option)}>{option.display_name}{!option.available ? ' · 未安装' : !interactiveAgent(option) ? ' · 暂不支持交互执行' : ''}</option>)}
        </select></label>
        <WorkspaceSelect project={project} value={workspace} disabled={busy} onChange={setWorkspace} onValidityChange={setWorkspaceReady} />
        {workspace.workspace_mode === 'temporary' && <p className="workspace-hint">此工作区会保留供 Agent 使用，不会自动清理。</p>}
        <label className="inbox-append-prompt"><span>追加 prompt <small>可选</small></span><textarea aria-label="追加 prompt" rows={5} value={appendPrompt} onChange={event => setAppendPrompt(event.target.value)} placeholder="例如：先分析需求和实现方案，列出风险，再开始修改代码。" disabled={busy} /></label>
        <details className="inbox-final-prompt"><summary>查看最终任务输入</summary><pre>{finalPrompt}</pre></details>
        {error && <p className="inbox-execute-error" role="alert">{error}</p>}
      </div>
      <footer><button type="button" disabled={busy} onClick={onClose}>取消</button><button className="inbox-execute-primary" type="submit" disabled={busy || !agent || !workspaceReady}>{busy ? <LoaderCircle className="inbox-spin" size={14} /> : <Play size={14} />}{busy ? '正在启动…' : '开始执行'}</button></footer>
    </form>
    </section>
  </div>, container);
}

import { useCallback, useRef, useState } from 'react';
import { Inbox, Plus } from 'lucide-react';
import type { AowProject } from '../../aow/types';
import type { AowAgent } from '../agents/types';
import { inboxApi } from './api';
import { InboxRow } from './InboxRow';
import { InlineEditor } from './InlineEditor';
import { InboxToolbar } from './InboxToolbar';
import { MarkdownContent } from '../../components/MarkdownContent';
import { useInboxDraft } from './useInboxDraft';
import { useEditorDismiss } from './useEditorDismiss';
import { useInbox } from './useInbox';
import { inboxError } from './types';
import './inbox.css';
interface Drag { id: string; over?: string; after: boolean; x: number; y: number; moved: boolean }
export function InboxPanel({ visible, projects, agents, onOpenTerminal }: {
  visible: boolean; projects: AowProject[]; agents: AowAgent[]; onOpenTerminal: (id: string) => Promise<void>;
}) {
  const { data, error, reload, mutate } = useInbox(visible);
  const capture = useInboxDraft('new', mutate, undefined, data?.items);
  const draft = capture.draft;
  const [editingIds, setEditingIds] = useState<Set<string>>(() => new Set());
  const onEditingChange = useCallback((id: string, editing: boolean) => setEditingIds(current => {
    if (current.has(id) === editing) return current;
    const next = new Set(current); if (editing) next.add(id); else next.delete(id); return next;
  }), []);
  const [project, setProject] = useState('');
  const [labels, setLabels] = useState<string[]>([]);
  const [query, setQuery] = useState('');
  const [busy, setBusy] = useState(false);
  const [actionError, setActionError] = useState('');
  const drag = useRef<Drag | undefined>(undefined);
  const [dragging, setDragging] = useState<Drag>();
  const editor = useRef<HTMLDivElement>(null);
  useEditorDismiss(editor, capture.editing, () => { void capture.finish(); });
  const ownProjects = projects.filter(project => !project.builtin);
  const selectedLabels = labels.filter(id => data?.labels.some(label => label.id === id));
  const items = (data?.items ?? []).filter(item => item.id !== draft?.base?.id && (editingIds.has(item.id) || ((!project || (project === 'unbound' ? !item.project_id : item.project_id === project))
    && (!selectedLabels.length || item.label_ids.some(id => selectedLabels.includes(id))) && item.markdown.toLowerCase().includes(query.toLowerCase()))));
  const add = async () => {
    setProject(''); setLabels([]); setQuery('');
    if (draft && !await capture.finish()) return;
    capture.begin();
    requestAnimationFrame(() => { editor.current?.scrollIntoView({ block: 'nearest' }); editor.current?.querySelector<HTMLElement>('[role="textbox"]')?.focus(); });
  };
  const move = async (id: string, before: string | null) => {
    if (!data || busy || before === id) return;
    setBusy(true); setActionError('');
    try { await mutate(() => inboxApi.reorder(data.revision, id, before)); }
    catch (reason) { setActionError(inboxError(reason)); }
    finally { setBusy(false); }
  };
  return <section className="inbox-panel" aria-label="Inbox">
    <InboxToolbar visible={visible} data={data} projects={ownProjects} project={project} query={query} labels={selectedLabels} count={items.length}
      onProject={setProject} onQuery={setQuery} onLabel={id => setLabels(current => current.includes(id) ? current.filter(value => value !== id) : [...current, id])}
      onClear={() => { setProject(''); setLabels([]); setQuery(''); }} mutate={mutate} />
    <div className="inbox-scroll">
      {error && <div className="inbox-error" role="alert">{error}<button onClick={() => void reload()}>重试加载</button></div>}
      {!data && !error && <p className="inbox-empty">正在加载…</p>}
      {data && !items.length && !draft && <div className="inbox-empty"><Inbox size={28} /><strong>{data.items.length ? '没有匹配的需求' : '先把想法记下来'}</strong><p>{data.items.length ? '调整筛选，或添加新的需求。' : '一段 Markdown 就够了，项目和标签可以稍后补充。'}</p></div>}
      <div className="inbox-list" aria-label="需求列表">{items.map((item, index) => <InboxRow key={item.id} item={item} labels={data!.labels} projects={ownProjects} agents={agents} execution={data?.executions.find(run => run.item_id === item.id)}
        commentCount={data?.comment_counts[item.id] ?? 0}
        mutate={mutate} onOpenTerminal={onOpenTerminal} onEditingChange={onEditingChange} dragging={dragging?.id === item.id} drop={dragging?.over === item.id ? dragging.after ? 'after' : 'before' : undefined}
        dragProps={{
          onPointerDown: event => { if (busy || event.button) return; drag.current = { id: item.id, x: event.clientX, y: event.clientY, after: false, moved: false }; event.currentTarget.setPointerCapture(event.pointerId); },
          onPointerMove: event => {
            const current = drag.current; if (!current) return;
            if (Math.hypot(current.x - event.clientX, current.y - event.clientY) > 5) current.moved = true;
            if (!current.moved) return;
            const target = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>('[data-inbox-id]');
            const rect = target?.getBoundingClientRect();
            current.over = target?.dataset.inboxId; current.after = !!rect && event.clientY > rect.top + rect.height / 2;
            setDragging({ ...current });
            const scroll = event.currentTarget.closest('.inbox-scroll');
            const bounds = scroll?.getBoundingClientRect();
            if (bounds && scroll) { if (event.clientY < bounds.top + 36) scroll.scrollTop -= 18; else if (event.clientY > bounds.bottom - 36) scroll.scrollTop += 18; }
          },
          onPointerUp: event => {
            const current = drag.current; drag.current = undefined; setDragging(undefined);
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            if (!current?.moved || !current.over || current.over === current.id) return;
            const order = data!.items.filter(item => item.id !== current.id);
            const target = order.findIndex(item => item.id === current.over);
            if (target >= 0) void move(current.id, current.after ? order[target + 1]?.id ?? null : current.over);
          },
          onPointerCancel: () => { drag.current = undefined; setDragging(undefined); },
          onKeyDown: event => {
            if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
            event.preventDefault();
            if (event.key === 'ArrowUp' && index > 0) void move(item.id, items[index - 1].id);
            else if (event.key === 'ArrowDown' && index < items.length - 1) {
              const order = data!.items.filter(other => other.id !== item.id);
              const next = order.findIndex(other => other.id === items[index + 1].id);
              void move(item.id, order[next + 1]?.id ?? null);
            }
          },
        }} />)}</div>
      {draft && <div ref={editor} className="inbox-new-row" data-inbox-editor="new">
        {capture.editing ? <InlineEditor value={draft.markdown} label="新需求 Markdown" onChange={markdown => capture.update({ markdown })}
          onFinish={() => { void capture.finish(); }} onComposing={capture.setComposing} status={capture.status} />
          : <><div className="inbox-edit-target inbox-content" tabIndex={0} role="group" aria-label="需求内容，双击或按 Enter 编辑"
            onDoubleClick={event => { if (!(event.target as Element).closest('a, button, input, select, textarea, summary')) capture.begin(); }} onKeyDown={event => { if (event.target === event.currentTarget && ['Enter', 'F2'].includes(event.key)) { event.preventDefault(); capture.begin(); } }}>
            <MarkdownContent text={draft.markdown} readOnly className="inbox-markdown" /></div><span className="inbox-save-status" role="status">{capture.status}</span></>}
        {capture.conflict && <p className="inbox-conflict">这条需求已有更新。<button disabled={capture.saving} onClick={() => capture.resolve(true)}>{capture.removing ? '按最新版本移除' : '保留草稿，以最新版本保存'}</button><button disabled={capture.saving} onClick={() => capture.resolve(false)}>载入最新内容</button></p>}
        {capture.error && <p className="inbox-error" role="alert">{capture.error}<button onClick={() => { void capture.retry(); }}>重试</button></p>}
      </div>}
      {actionError && <p className="inbox-error" role="alert">{actionError}</p>}
    </div>
    <footer className="inbox-add-bar"><button onClick={() => { void add(); }} disabled={!data}><Plus size={16} />添加需求</button></footer>
  </section>;
}

import { useEffect, useRef, useState, type PointerEvent, type KeyboardEvent } from 'react';
import { GripVertical, LoaderCircle, MessageSquare, Play, Trash2 } from 'lucide-react';
import type { AowProject } from '../../aow/types';
import type { AowAgent } from '../agents/types';
import { AgentIcon } from '../agents/AgentIcon';
import { aowAgentType } from '../agents/agentTypes';
import { MarkdownContent } from '../../components/MarkdownContent';
import { inboxApi } from './api';
import { newInboxId } from './id';
import { InboxExecutePanel } from './InboxExecutePanel';
import { InboxComments } from './InboxComments';
import { InlineEditor } from './InlineEditor';
import { EditorShortcutHint } from './EditorShortcutHint';
import { RowLabels } from './RowLabels';
import { ProjectSelect } from './ProjectSelect';
import { saveDraft } from './drafts';
import { useInboxDraft } from './useInboxDraft';
import { useEditorDismiss } from './useEditorDismiss';
import { inboxError, previewTitle, type InboxExecuteOptions, type InboxExecution, type InboxItem, type InboxLabel } from './types';

export function InboxRow({ item, labels, projects, agents, execution, commentCount, mutate, onOpenTerminal, onEditingChange, dragProps, dragging, drop }: {
  item: InboxItem; labels: InboxLabel[]; projects: AowProject[]; agents: AowAgent[]; execution?: InboxExecution;
  commentCount: number;
  mutate: <T>(action: () => Promise<T>) => Promise<T>; onOpenTerminal: (id: string) => Promise<void>;
  onEditingChange: (id: string, editing: boolean) => void;
  dragging: boolean; drop?: 'before' | 'after';
  dragProps: { onPointerDown: (e: PointerEvent<HTMLButtonElement>) => void; onPointerMove: (e: PointerEvent<HTMLButtonElement>) => void; onPointerUp: (e: PointerEvent<HTMLButtonElement>) => void; onPointerCancel: () => void; onKeyDown: (e: KeyboardEvent<HTMLButtonElement>) => void };
}) {
  const editor = useInboxDraft(item.id, mutate, item);
  const draft = editor.draft;
  const root = useRef<HTMLElement>(null);
  useEditorDismiss(root, editor.editing, focus => { if (focus) finishEdit(); else void editor.finish(); });
  useEffect(() => { onEditingChange(item.id, !!draft); }, [item.id, !!draft, onEditingChange]);
  useEffect(() => () => onEditingChange(item.id, false), [item.id, onEditingChange]);
  const [pendingLabels, setPendingLabels] = useState<string[]>();
  const [section, setSection] = useState<'delete'>();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [configureExecution, setConfigureExecution] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const content = useRef<HTMLDivElement>(null);
  const [editorHeight, setEditorHeight] = useState<number>();
  const executionRequest = useRef<{ key: string; revision: number; signature: string } | undefined>(undefined);
  const action = async (operation: () => Promise<unknown>, done?: () => void) => {
    setBusy(true); setError('');
    try { await mutate(operation); done?.(); } catch (reason) { setError(inboxError(reason)); }
    finally { setBusy(false); }
  };
  const beginEdit = () => {
    if (busy || editor.editing || editor.removing) return;
    setEditorHeight(content.current?.getBoundingClientRect().height);
    editor.begin();
    setSection(undefined); setError('');
  };
  const finishEdit = () => { void editor.finish(); requestAnimationFrame(() => content.current?.querySelector<HTMLElement>('.inbox-edit-target')?.focus({ preventScroll: true })); };
  const projectExists = projects.some(project => project.id === item.project_id);
  const boundProject = projects.find(project => project.id === item.project_id);
  const panelContainer = configureExecution ? root.current?.closest<HTMLElement>('.inbox-panel') : null;
  const activeLabels = draft ? draft.label_ids : pendingLabels ?? item.label_ids;
  const starting = execution?.phase === 'starting';
  const executedAgent = agents.find(agent => agent.id === execution?.agent);
  const terminalTitle = `打开 ${executedAgent?.display_name || execution?.agent} 终端`;
  const toggle = (next: typeof section) => { setSection(value => value === next ? undefined : next); setError(''); };
  const execute = (options: InboxExecuteOptions) => {
    if (busy || starting) return;
    const signature = JSON.stringify(options);
    const currentRequest = executionRequest.current;
    const request = currentRequest && currentRequest.revision === item.revision && currentRequest.signature === signature
      ? currentRequest
      : { key: newInboxId(), revision: item.revision, signature };
    executionRequest.current = request;
    void action(() => inboxApi.execute(item, options, request.key), () => {
      executionRequest.current = undefined;
      setConfigureExecution(false);
    });
  };
  return <article ref={root} className={`inbox-row${dragging ? ' dragging' : ''}${editor.editing ? ' editing' : ''}`} data-inbox-id={item.id} data-inbox-editor={item.id} data-drop={drop} aria-label={previewTitle(item.markdown)}>
    <button className="inbox-grip" aria-label={`拖动排序：${previewTitle(item.markdown)}`} title="拖动排序，或使用上下方向键" disabled={busy || !!draft} {...dragProps}><GripVertical size={16} /></button>
    <div className="inbox-row-body">
      <div ref={content} className="inbox-content">
        {draft && editor.editing ? <InlineEditor seamless initialHeight={editorHeight} value={draft.markdown} onChange={markdown => editor.update({ markdown })}
          onFinish={() => { void finishEdit(); }} onComposing={editor.setComposing} status={editor.status} />
          : <div className="inbox-edit-target" role="group" tabIndex={busy ? -1 : 0} aria-label="需求内容，双击或按 Enter 编辑" aria-keyshortcuts="Enter F2" title="双击编辑"
            onDoubleClick={event => { if (!(event.target as Element).closest('a, button, input, select, textarea, summary')) beginEdit(); }}
            onKeyDown={event => { if (event.target === event.currentTarget && (event.key === 'Enter' || event.key === 'F2')) { event.preventDefault(); beginEdit(); } }}>
            <MarkdownContent text={draft?.markdown ?? item.markdown} readOnly className="inbox-markdown" />
          </div>}
      </div>
      {draft && editor.conflict && <p className="inbox-conflict">这条需求已有更新。<button disabled={editor.saving} onClick={() => editor.resolve(true)}>{editor.removing ? '按最新版本移除' : '保留草稿，以最新版本保存'}</button><button disabled={editor.saving} onClick={() => editor.resolve(false)}>载入最新内容</button></p>}
      <div className="inbox-row-meta">
        <ProjectSelect projects={projects} value={(draft ? draft.project_id : item.project_id) ?? ''} disabled={busy || editor.removing} onChange={value => {
          const project_id = value || null;
          if (draft) editor.update({ project_id });
          else void action(() => inboxApi.update(item, { project_id }));
        }} />
        <RowLabels labels={labels} selected={activeLabels} busy={busy || editor.removing} onChange={next => {
          if (draft) { editor.update({ label_ids: next }); return; }
          setPendingLabels(next);
          void action(() => inboxApi.update(item, { label_ids: next })).finally(() => setPendingLabels(undefined));
        }} />
        <div className="inbox-row-actions" aria-busy={starting}>
          {execution?.tab_id && <button type="button" aria-label="打开终端" title={terminalTitle} onClick={() => {
            setError('');
            void onOpenTerminal(execution.tab_id!).catch(reason => setError(inboxError(reason)));
          }}><AgentIcon agentId={executedAgent ? aowAgentType(executedAgent) : execution.agent} /></button>}
          {commentCount > 0 && <button type="button" aria-label="评论" title={showComments ? '收起评论' : '展开评论'}
            aria-expanded={showComments} aria-controls={`inbox-comments-${item.id}`} className={showComments ? 'active' : undefined}
            onClick={() => setShowComments(value => !value)}><MessageSquare size={14} /></button>}
          {draft ? <span className="inbox-save-status" role="status">{editor.status}</span> : <>
            <button type="button" aria-label="执行需求" title={starting ? '正在启动 Agent…' : !projectExists ? '先绑定项目再执行' : '配置执行并选择 Agent'} disabled={busy || !projectExists || !!starting}
              onClick={() => { setError(''); setConfigureExecution(true); }}>
              {starting ? <LoaderCircle size={14} className="inbox-spin" /> : <Play size={14} />}
            </button>
            <button aria-label="删除需求" title="删除需求" disabled={busy} onClick={() => toggle('delete')}><Trash2 size={14} /></button>
          </>}
          {editor.editing && <EditorShortcutHint />}
        </div>
      </div>
      {showComments && commentCount > 0 && <InboxComments itemId={item.id} count={commentCount} />}
      {section === 'delete' && <div className="inbox-delete"><span>删除这条需求？</span><button disabled={busy} onClick={() => setSection(undefined)}>取消</button><button className="inbox-danger" disabled={busy} onClick={() => void action(() => inboxApi.remove(item), () => saveDraft(item.id))}>确认删除</button></div>}
      {execution && (execution.phase === 'failed' || execution.phase === 'interrupted') && <div className={`inbox-execution ${execution.phase}`} role="alert">
        {execution.error || '执行未完成'}
      </div>}
      {error && !configureExecution && <p className="inbox-error" role="alert">{error}</p>}
      {draft && editor.error && <p className="inbox-error" role="alert">{editor.error}<button onClick={() => { void editor.retry(); }}>重试</button></p>}
    </div>
    {configureExecution && boundProject && panelContainer && <InboxExecutePanel container={panelContainer} item={item} project={boundProject} agents={agents} busy={busy} error={error} onClose={() => setConfigureExecution(false)} onSubmit={execute} />}
  </article>;
}

import { useEffect, useId, useRef, useState, type CSSProperties } from 'react';
import { ChevronDown, MoreHorizontal, Search, Tag, X } from 'lucide-react';
import type { AowProject } from '../../aow/types';
import { LabelsEditor } from './LabelsEditor';
import { ProjectSelect } from './ProjectSelect';
import { RowMenu } from './RowMenu';
import type { InboxSnapshot } from './types';

export function InboxToolbar({ visible, data, projects, project, query, labels, count, onProject, onQuery, onLabel, onClear, mutate }: {
  visible: boolean; data?: InboxSnapshot; projects: AowProject[]; project: string; query: string; labels: string[]; count: number;
  onProject: (id: string) => void; onQuery: (query: string) => void; onLabel: (id: string) => void; onClear: () => void;
  mutate: <T>(action: () => Promise<T>) => Promise<T>;
}) {
  const [open, setOpen] = useState<'filter' | 'labels'>();
  const id = useId();
  const popup = useRef<HTMLDivElement>(null);
  const filter = useRef<HTMLButtonElement>(null);
  const manage = useRef<HTMLButtonElement>(null);
  const filtered = !!project || !!query || labels.length > 0;

  useEffect(() => { if (!visible) setOpen(undefined); }, [visible]);
  useEffect(() => {
    if (open !== 'labels') return;
    const trigger = manage.current;
    popup.current?.querySelector<HTMLInputElement>('input:not([type=color])')?.focus({ preventScroll: true });
    const outside = (event: PointerEvent) => {
      const target = event.target as Node;
      if (!popup.current?.contains(target) && !filter.current?.contains(target) && !manage.current?.contains(target)) setOpen(undefined);
    };
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault(); setOpen(undefined); trigger?.focus({ preventScroll: true });
      }
    };
    window.addEventListener('pointerdown', outside);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', outside);
      window.removeEventListener('keydown', key);
    };
  }, [open]);

  return <header className="inbox-header">
    <ProjectSelect projects={projects} value={project} filter visible={visible} onChange={onProject} />
    <label className="inbox-search"><Search size={14} />
      <input aria-label="搜索需求" placeholder="搜索需求" value={query} onChange={event => onQuery(event.target.value)} />
      {data && <span className="inbox-match-count" aria-label={`显示 ${count} 条需求，共 ${data.items.length} 条`}>{count}{count !== data.items.length ? ` / ${data.items.length}` : ''}</span>}
    </label>
    <button ref={filter} className={`inbox-select inbox-filter-trigger${labels.length ? ' active' : ''}`} aria-label="按标签筛选" title="按标签筛选（匹配任一标签）"
      aria-haspopup="dialog" aria-expanded={open === 'filter'} aria-controls={open === 'filter' ? `${id}-filter` : undefined}
      disabled={!data} onClick={() => setOpen(value => value === 'filter' ? undefined : 'filter')}
      onKeyDown={event => { if (event.key === 'ArrowDown') { event.preventDefault(); setOpen('filter'); } }}>
      <Tag size={15} /><span className="inbox-filter-text">标签</span>{labels.length > 0 && <span className="inbox-filter-count">{labels.length}</span>}<ChevronDown size={12} className="inbox-filter-chevron" />
    </button>
    <button ref={manage} className={`inbox-label-menu-trigger${open === 'labels' ? ' active' : ''}`} aria-label="配置标签" title="配置标签"
      aria-haspopup="dialog" aria-expanded={open === 'labels'} aria-controls={open === 'labels' ? `${id}-labels` : undefined}
      disabled={!data} onClick={() => setOpen(value => value === 'labels' ? undefined : 'labels')}><MoreHorizontal size={18} /></button>
    {open === 'filter' && data && <RowMenu id={`${id}-filter`} className="inbox-filter-popover" role="dialog"
      label="按标签筛选（匹配任一标签）" anchor={filter} onClose={() => setOpen(undefined)}>
        <header><strong>标签过滤</strong><span>匹配任一标签</span></header>
        <div className="inbox-filter-list" role="group" aria-label="筛选标签">
          {data.labels.map(label => <label key={label.id} style={{ '--label-color': label.color } as CSSProperties}>
            <input type="checkbox" checked={labels.includes(label.id)} onChange={() => onLabel(label.id)} /><i /><span>{label.name}</span>
          </label>)}
          {!data.labels.length && <p>暂无标签，可在标签菜单中添加。</p>}
        </div>
        <footer><button disabled={!filtered} onClick={onClear}><X size={13} />清除筛选</button></footer>
    </RowMenu>}
    {open === 'labels' && data && <div ref={popup} id={`${id}-labels`} className="inbox-toolbar-popup inbox-labels-popover"
      role="dialog" aria-label="配置标签" onBlur={event => {
        const next = event.relatedTarget;
        if (next && !event.currentTarget.contains(next) && !filter.current?.contains(next) && !manage.current?.contains(next)) setOpen(undefined);
      }}>
      <LabelsEditor data={data} mutate={mutate} onClose={() => { setOpen(undefined); manage.current?.focus({ preventScroll: true }); }} />
    </div>}
  </header>;
}

import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import type { IDisposable, editor } from 'monaco-editor';
import { EditorShortcutHint } from './EditorShortcutHint';

const Editor = lazy(() => import('../editor/MonacoEditor'));

export function InlineEditor({ value, onChange, onFinish, onComposing, status, label = '需求 Markdown', seamless = false, initialHeight }: {
  value: string; onChange: (text: string) => void; onFinish: () => void; onComposing: (value: boolean) => void; status: string; label?: string;
  seamless?: boolean; initialHeight?: number;
}) {
  const host = useRef<HTMLDivElement>(null);
  const composing = useRef(false);
  const compositionCallback = useRef(onComposing); compositionCallback.current = onComposing;
  const listeners = useRef<IDisposable[]>([]);
  const [height, setHeight] = useState(seamless ? Math.max(initialHeight ?? 22, 22) : 112);
  useEffect(() => () => { listeners.current.forEach(listener => listener.dispose()); }, []);
  const mount = (instance: editor.IStandaloneCodeEditor) => {
    if (host.current) instance.updateOptions({ fontFamily: getComputedStyle(host.current).fontFamily });
    const fit = () => {
      const contentHeight = instance.getContentHeight();
      setHeight(seamless ? Math.max(initialHeight ?? 22, contentHeight) : Math.min(420, Math.max(112, contentHeight)));
    };
    const composition = (active: boolean) => { composing.current = active; compositionCallback.current(active); };
    listeners.current = [instance.onDidContentSizeChange(fit), instance.onDidLayoutChange(fit),
      instance.onDidCompositionStart(() => composition(true)), instance.onDidCompositionEnd(() => composition(false))];
    fit();
    if (!seamless) {
      const model = instance.getModel();
      if (model) instance.setPosition(model.getPositionAt(model.getValueLength()));
    }
    instance.getDomNode()?.querySelector<HTMLElement>('[role="textbox"]')?.focus({ preventScroll: seamless });
  };
  return <div className={`inbox-editor${seamless ? ' inbox-editor-seamless' : ''}`}>
    <div ref={host} className="inbox-code-editor"
      onKeyDownCapture={event => {
        if (composing.current || event.nativeEvent.isComposing) return;
        const finish = (event.metaKey || event.ctrlKey) && event.key === 'Enter';
        const escape = event.key === 'Escape' && (event.target as Element).matches('[role="textbox"]');
        if (finish || escape) { event.preventDefault(); event.stopPropagation(); onFinish(); }
      }}>
      <Suspense fallback={<div className="inbox-editor-loading" style={{ height }} role="status">正在加载编辑器…</div>}>
        <Editor language="markdown" theme="vs-dark" value={value} height={height} saveViewState={false}
          loading={<span className="inbox-editor-loading">正在加载编辑器…</span>}
          onMount={mount} onChange={text => onChange(text ?? '')}
          options={{
            ariaLabel: label, placeholder: '写下需求，支持 Markdown…', automaticLayout: true,
            fontSize: 13, lineHeight: 22, wordWrap: 'on', wrappingIndent: 'none',
            lineNumbers: 'off', lineNumbersMinChars: 0, lineDecorationsWidth: 0, glyphMargin: false, folding: false,
            minimap: { enabled: false }, overviewRulerLanes: 0, overviewRulerBorder: false, hideCursorInOverviewRuler: true,
            renderLineHighlight: 'none', scrollBeyondLastLine: false, scrollBeyondLastColumn: 0,
            padding: { top: seamless ? 0 : 10, bottom: seamless ? 0 : 10 },
            stickyScroll: { enabled: false }, guides: { indentation: false },
            occurrencesHighlight: 'off', selectionHighlight: false, renderWhitespace: 'none',
            quickSuggestions: false, wordBasedSuggestions: 'off', suggestOnTriggerCharacters: false,
            parameterHints: { enabled: false }, hover: { enabled: 'off' }, contextmenu: false, tabFocusMode: true,
            scrollbar: { vertical: seamless ? 'hidden' : 'auto', horizontal: 'hidden', verticalScrollbarSize: seamless ? 0 : 8,
              horizontalScrollbarSize: 0, alwaysConsumeMouseWheel: false, useShadows: false },
          }} />
      </Suspense>
    </div>
    {!seamless && <footer><span className="inbox-save-status" role="status">{status}</span><EditorShortcutHint /></footer>}
  </div>;
}

import { useState } from 'react';
import { Plus, Trash2, X } from 'lucide-react';
import { inboxApi } from './api';
import { newInboxId } from './id';
import { inboxError, type InboxLabel, type InboxSnapshot } from './types';
export function LabelsEditor({ data, mutate, onClose }: { data: InboxSnapshot; mutate: <T>(action: () => Promise<T>) => Promise<T>; onClose: () => void }) {
  const [labels, setLabels] = useState(() => data.labels.map(label => ({ ...label })));
  const [revision, setRevision] = useState(data.revision);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const change = (id: string, patch: Partial<InboxLabel>) => setLabels(items => items.map(label => label.id === id ? { ...label, ...patch } : label));
  const removedInUse = data.items.some(item => item.label_ids.some(id => !labels.some(label => label.id === id)));
  return <form className="inbox-label-editor" aria-label="配置标签" onSubmit={event => {
    event.preventDefault(); setBusy(true); setError('');
    void mutate(() => inboxApi.labels(revision, labels.map(label => ({ ...label, name: label.name.trim() })))).then(onClose).catch(reason => setError(inboxError(reason))).finally(() => setBusy(false));
  }}>
    <header><strong>配置标签</strong><button type="button" aria-label="关闭标签配置" disabled={busy} onClick={onClose}><X size={16} /></button></header>
    <div className="inbox-label-editor-list"><fieldset disabled={busy}>{labels.map((label, index) => <div key={label.id}>
      <input type="color" aria-label={`标签 ${index + 1} 颜色`} value={label.color} onChange={event => change(label.id, { color: event.target.value })} />
      <input aria-label={`标签 ${index + 1} 名称`} value={label.name} maxLength={40} required onChange={event => change(label.id, { name: event.target.value })} />
      <button type="button" aria-label={`删除标签 ${label.name}`} onClick={() => setLabels(items => items.filter(item => item.id !== label.id))}><Trash2 size={14} /></button>
    </div>)}</fieldset></div>
    {removedInUse && <p>保存后，已删除的标签也会从需求上移除。</p>}
    {error && <p role="alert" className="inbox-error">{error}<button type="button" onClick={() => { setLabels(data.labels.map(label => ({ ...label }))); setRevision(data.revision); setError(''); }}>重新载入标签</button></p>}
    <footer><button type="button" disabled={busy || labels.length >= 64} onClick={() => setLabels(items => [...items, { id: newInboxId(), name: '', color: '#94a3b8' }])}><Plus size={14} />添加标签</button><button className="inbox-primary" disabled={busy} type="submit">保存标签</button></footer>
  </form>;
}

import type { AowProject } from '../../aow/types';
import type { MobileNavigate } from '../../mobile/mobileState';
import { useMobileResource } from '../../mobile/mobileState';
import { agentsApi } from '../agents/api';
import { terminalApi } from '../terminals/terminalApi';
import { InboxPanel } from './InboxPanel';
export function MobileInbox({ projects, navigate }: { projects: AowProject[]; navigate: MobileNavigate }) {
  const agents = useMobileResource('inbox-agents', () => agentsApi.agents());
  return <div className="mobile-inbox">
    {agents.error && <p role="alert" className="inbox-error">{agents.error}<button onClick={agents.reload}>重新加载 Agent</button></p>}
    <InboxPanel visible projects={projects} agents={agents.data ?? []} onOpenTerminal={async id => {
      const tab = await terminalApi.get(id);
      navigate({ workspace: tab.workspace_root, view: 'terminal', terminal: tab.id });
    }} />
  </div>;
}

import { useEffect, useId, useRef, useState } from 'react';
import { Check, ChevronDown } from 'lucide-react';
import type { AowProject } from '../../aow/types';
import { RowMenu } from './RowMenu';

export function ProjectSelect({ projects, value, onChange, disabled = false, filter = false, visible = true }: {
  projects: AowProject[]; value: string; onChange: (id: string) => void; disabled?: boolean; filter?: boolean; visible?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const menuId = useId();
  const label = filter ? '按项目筛选' : '绑定项目';
  const options = [
    ...(filter ? [{ id: '', name: '所有项目' }, { id: 'unbound', name: '未绑定项目' }] : [{ id: '', name: '未绑定项目' }]),
    ...projects,
  ];
  if (!options.some(option => option.id === value)) options.push({ id: value, name: '项目已移除' });
  const selected = options.find(option => option.id === value)!;
  useEffect(() => { if (disabled || !visible) setOpen(false); }, [disabled, visible]);
  return <>
    <button ref={trigger} type="button" className={`inbox-select ${filter ? `inbox-project-filter${value ? ' active' : ''}` : 'inbox-project-select'}`}
      aria-label={label} title={selected.name} aria-haspopup="listbox" aria-expanded={open} aria-controls={open ? menuId : undefined}
      disabled={disabled} onClick={() => setOpen(current => !current)}
      onKeyDown={event => { if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); setOpen(true); } }}>
      <span className="inbox-select-text">{selected.name}</span><ChevronDown size={12} />
    </button>
    {open && <RowMenu id={menuId} label={label} role="listbox" anchor={trigger} onClose={() => setOpen(false)}>
      {options.map(option => <button key={option.id} type="button" role="option" aria-selected={option.id === value} tabIndex={-1}
        onClick={() => { setOpen(false); trigger.current?.focus({ preventScroll: true }); if (value !== option.id) onChange(option.id); }}>
        <span>{option.name}</span>{option.id === value && <Check size={14} className="inbox-option-check" />}
      </button>)}
    </RowMenu>}
  </>;
}

import { useId, useRef, useState, type CSSProperties } from 'react';
import { ChevronDown } from 'lucide-react';
import type { InboxLabel } from './types';
import { RowMenu } from './RowMenu';

export function RowLabels({ labels, selected, busy, onChange }: {
  labels: InboxLabel[]; selected: string[]; busy: boolean; onChange: (ids: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const menuId = useId();
  const active = labels.filter(label => selected.includes(label.id));
  return <>
    <button ref={trigger} className="inbox-select inbox-label-select" type="button" aria-label="选择标签" title={active.map(label => label.name).join('、') || '选择标签'}
      aria-haspopup="dialog" aria-expanded={open} aria-controls={open ? menuId : undefined} disabled={busy}
      onClick={() => setOpen(value => !value)} onKeyDown={event => { if (event.key === 'ArrowDown') { event.preventDefault(); setOpen(true); } }}>
      <span className="inbox-tags">{active.length ? active.map(label => <span key={label.id} className="inbox-tag" style={{ color: label.color, borderColor: `${label.color}55` }}>{label.name}</span>) : <span>标签</span>}</span><ChevronDown size={12} />
    </button>
    {open && <RowMenu id={menuId} label="选择需求标签" role="dialog" anchor={trigger} onClose={() => setOpen(false)}>
      <fieldset aria-label="需求标签" disabled={busy}>
        {labels.map(label => <label key={label.id} style={{ '--label-color': label.color } as CSSProperties}><input type="checkbox" checked={selected.includes(label.id)} onChange={event => onChange(event.target.checked ? [...selected, label.id] : selected.filter(id => id !== label.id))} /><i /><span>{label.name}</span></label>)}
        {!labels.length && <p>暂无标签，可在面板顶部配置。</p>}
      </fieldset>
    </RowMenu>}
  </>;
}

import { useEffect, useLayoutEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { createPortal } from 'react-dom';

export function RowMenu({ id, label, role = 'menu', anchor, onClose, children, className = '' }: {
  id: string; label: string; role?: 'menu' | 'dialog' | 'listbox'; anchor: RefObject<HTMLButtonElement | null>; onClose: () => void; children: ReactNode; className?: string;
}) {
  const menu = useRef<HTMLDivElement>(null);
  const close = useRef(onClose);
  close.current = onClose;
  const [position, setPosition] = useState({ top: 0, left: 0, width: 240, maxHeight: 240 });
  useLayoutEffect(() => {
    const panel = anchor.current?.closest('.inbox-panel');
    const update = () => {
      const bounds = anchor.current?.getBoundingClientRect();
      if (!bounds || !menu.current) return;
      const panelBounds = panel?.getBoundingClientRect();
      const left = Math.max(8, (panelBounds?.left ?? 0) + 8);
      const right = Math.min(window.innerWidth - 8, (panelBounds?.right ?? window.innerWidth) - 8);
      const top = Math.max(8, (panelBounds?.top ?? 0) + 8);
      const bottom = Math.min(window.innerHeight - 8, (panelBounds?.bottom ?? window.innerHeight) - 8);
      const width = Math.max(0, Math.min(240, right - left));
      const below = bottom - bounds.bottom - 4;
      const above = bounds.top - top - 4;
      const desired = Math.min(240, menu.current.scrollHeight + 2);
      const upwards = below < desired && above > below;
      const maxHeight = Math.max(32, Math.min(240, upwards ? above : below));
      const height = Math.min(desired, maxHeight);
      setPosition({ top: upwards ? bounds.top - height - 4 : bounds.bottom + 4, left: Math.max(left, Math.min(bounds.left, right - width)), width, maxHeight });
    };
    update();
    const observer = new ResizeObserver(update);
    if (menu.current) observer.observe(menu.current);
    if (anchor.current) observer.observe(anchor.current);
    if (panel) observer.observe(panel);
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => { observer.disconnect(); window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); };
  }, [anchor]);
  useEffect(() => {
    const outside = (event: Event) => { if (!anchor.current?.contains(event.target as Node) && !menu.current?.contains(event.target as Node)) close.current(); };
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape') { event.preventDefault(); close.current(); anchor.current?.focus(); } };
    document.addEventListener('pointerdown', outside);
    document.addEventListener('focusin', outside);
    document.addEventListener('keydown', escape);
    (menu.current?.querySelector<HTMLElement>('[role="option"][aria-selected="true"]') ?? menu.current?.querySelector<HTMLElement>('input:not(:disabled), button:not(:disabled)') ?? menu.current)?.focus({ preventScroll: true });
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('focusin', outside); document.removeEventListener('keydown', escape); };
  }, [anchor]);
  return createPortal(<div ref={menu} id={id} className={`inbox-row-menu ${className}`} data-inbox-editor-owner={anchor.current?.closest('[data-inbox-editor]')?.getAttribute('data-inbox-editor')}
    data-floating-workspace={anchor.current?.closest('[data-floating-workspace]') ? '' : undefined} role={role} aria-label={label} tabIndex={-1} style={position} onKeyDown={event => {
    if (role === 'dialog' || !['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return;
    const items = [...(menu.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled), [role="option"]:not(:disabled)') ?? [])];
    if (!items.length) return;
    event.preventDefault();
    const current = items.indexOf(document.activeElement as HTMLButtonElement);
    const index = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (current + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    items[index].focus();
  }}>{children}</div>, document.body);
}

import { aowRequest } from '../../lib/aowRequest';
import type { InboxComment, InboxExecuteOptions, InboxExecution, InboxItem, InboxLabel, InboxSnapshot } from './types';
const base = '/api/inbox';
const itemPath = (id: string) => `${base}/items/${encodeURIComponent(id)}`;
const json = (method: string, value: unknown) => ({ method, body: JSON.stringify(value) });
export const inboxApi = {
  list: () => aowRequest<InboxSnapshot>(base, { cache: 'no-store' }),
  comments: (id: string) => aowRequest<InboxComment[]>(`${itemPath(id)}/comments`, { cache: 'no-store' }),
  capture: (markdown: string, requestKey: string) => aowRequest<InboxItem>(`${base}/items`, json('POST', { markdown, request_key: requestKey })),
  update: (item: InboxItem, patch: Partial<Pick<InboxItem, 'markdown' | 'project_id' | 'label_ids'>>) => aowRequest<InboxItem>(itemPath(item.id), json('PUT', {
    expected_revision: item.revision, markdown: item.markdown, project_id: item.project_id, label_ids: item.label_ids, ...patch,
  })),
  remove: (item: InboxItem) => aowRequest<void>(itemPath(item.id), json('DELETE', { expected_revision: item.revision })),
  reorder: (revision: number, itemId: string, beforeId: string | null) => aowRequest<void>(`${base}/order`, json('PUT', { expected_revision: revision, item_id: itemId, before_id: beforeId })),
  labels: (revision: number, labels: InboxLabel[]) => aowRequest<void>(`${base}/labels`, json('PUT', { expected_revision: revision, labels })),
  execute: (item: InboxItem, options: InboxExecuteOptions, requestKey: string) => aowRequest<InboxExecution>(`${itemPath(item.id)}/execute`, json('POST', {
    expected_revision: item.revision, request_key: requestKey, ...options,
  })),
};

import { appLocalStorage } from '../../lib/basePath';
export function readDraft<T>(key: string): T | undefined {
  try { return JSON.parse(appLocalStorage.getItem(`aow-inbox-draft:${key}`) ?? 'null') ?? undefined; } catch { return; }
}
export function saveDraft(key: string, value?: unknown) {
  try {
    if (value === undefined) appLocalStorage.removeItem(`aow-inbox-draft:${key}`);
    else appLocalStorage.setItem(`aow-inbox-draft:${key}`, JSON.stringify(value));
  } catch { /* Draft remains in memory when browser storage is unavailable. */ }
}

// getRandomValues also works on LAN HTTP origins, where randomUUID is unavailable.
export function newInboxId(): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(16)), byte => byte.toString(16).padStart(2, '0')).join('');
}

