import type { WorkspaceConfig, WorkspaceMode } from '../workspaces/types';

export interface InboxLabel { id: string; name: string; color: string }
export interface InboxComment {
  id: string; author: { type: 'human' | 'ai'; name: string }; created_at: string; content: string;
}
export interface InboxItem {
  id: string; markdown: string; project_id: string | null; label_ids: string[];
  revision: number; created_at: string; updated_at: string;
}
export interface InboxExecution {
  id: string; item_id: string; request_key: string; item_revision: number;
  agent: string; project_id: string; cwd: string; markdown: string; workspace_mode: WorkspaceMode;
  phase: 'starting' | 'submitted' | 'failed' | 'interrupted';
  tab_id: string | null; pane_id: string | null; error: string | null; created_at: string;
}
export type InboxWorkspaceMode = WorkspaceMode;
export interface InboxExecuteOptions extends WorkspaceConfig {
  agent: string;
  append_prompt: string;
}
export interface InboxSnapshot { revision: number; labels: InboxLabel[]; items: InboxItem[]; executions: InboxExecution[]; comment_counts: Record<string, number> }
export const previewTitle = (markdown: string) => markdown.split(/\r?\n/, 1)[0].replace(/^\s{0,3}#{1,6}\s+/, '').trim() || '未命名需求';
export const inboxError = (error: unknown) => error instanceof Error ? error.message : String(error);

import { useEffect, useRef, type RefObject } from 'react';

export function useEditorDismiss(root: RefObject<HTMLElement | null>, active: boolean, finish: (focus?: boolean) => void) {
  const callback = useRef(finish); callback.current = finish;
  useEffect(() => {
    if (!active) return;
    const inside = (target: Element) => {
      if (root.current?.contains(target)) return true;
      // Project/tag menus are portalled, but still belong to the edited row.
      const owner = target.closest('[data-inbox-editor-owner]')?.getAttribute('data-inbox-editor-owner');
      return !!owner && owner === root.current?.getAttribute('data-inbox-editor');
    };
    const outside = (event: Event) => {
      if (event.target instanceof Element && !inside(event.target)) callback.current();
    };
    const keyboard = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing || !(event.target instanceof Element) || !inside(event.target)) return;
      if (event.key === 'Escape' && event.target.closest('[data-inbox-editor-owner]')) return;
      if ((event.key === 'Enter' && (event.metaKey || event.ctrlKey)) || event.key === 'Escape') {
        event.preventDefault(); callback.current(true);
      }
    };
    document.addEventListener('pointerdown', outside);
    document.addEventListener('focusin', outside);
    document.addEventListener('keydown', keyboard);
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('focusin', outside); document.removeEventListener('keydown', keyboard); };
  }, [root, active]);
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { subscribeWorkspaceChanges } from '../../lib/workspaceEvents';
import { inboxApi } from './api';
import { inboxError, type InboxSnapshot } from './types';

export function useInbox(visible: boolean) {
  const [data, setData] = useState<InboxSnapshot>();
  const [error, setError] = useState('');
  const generation = useRef(0);
  const reload = useCallback(async () => {
    const ticket = ++generation.current;
    try {
      const next = await inboxApi.list();
      if (ticket === generation.current) { setData(next); setError(''); }
    } catch (reason) { if (ticket === generation.current) setError(inboxError(reason)); }
  }, []);
  useEffect(() => {
    if (!visible) return;
    void reload();
    return subscribeWorkspaceChanges(change => { if (change.reset || change.inbox) void reload(); });
  }, [visible, reload]);
  const starting = data?.executions.some(run => run.phase === 'starting');
  useEffect(() => {
    if (!visible || !starting) return;
    const timer = window.setInterval(() => { if (document.visibilityState === 'visible') void reload(); }, 1500);
    return () => window.clearInterval(timer);
  }, [visible, starting, reload]);
  useEffect(() => () => { generation.current++; }, []);
  const mutate = useCallback(async <T,>(action: () => Promise<T>): Promise<T> => {
    try { return await action(); } finally { await reload(); }
  }, [reload]);
  return { data, error, reload, mutate };
}

import { useEffect, useRef, useState } from 'react';
import { inboxApi } from './api';
import { readDraft, saveDraft } from './drafts';
import { newInboxId } from './id';
import { inboxError, type InboxItem } from './types';

interface Draft {
  base?: InboxItem;
  markdown: string;
  project_id: string | null;
  label_ids: string[];
  requestKey?: string;
  captureMarkdown?: string;
  remove?: boolean;
}
type Fields = Pick<Draft, 'markdown' | 'project_id' | 'label_ids'>;
const fields = (item?: Fields): Fields => ({ markdown: item?.markdown ?? '', project_id: item?.project_id ?? null, label_ids: item?.label_ids ?? [] });
const dirty = (draft: Draft) => !draft.base || draft.markdown !== draft.base.markdown || draft.project_id !== draft.base.project_id
  || JSON.stringify(draft.label_ids) !== JSON.stringify(draft.base.label_ids);
const empty = (markdown: string) => /^[\s#]*$/.test(markdown);

// Each editor has one write in flight. Its response advances the base revision,
// while any text typed during that request remains the next pending write.
export function useInboxDraft(key: string, mutate: <T>(action: () => Promise<T>) => Promise<T>, item?: InboxItem, items?: InboxItem[]) {
  const [draft, setDraft] = useState<Draft | undefined>(() => {
    const stored = readDraft<Draft>(key);
    if (!stored || typeof stored.markdown !== 'string' || (key !== 'new' && stored.base?.id !== key)) return;
    return { ...fields(stored.base), ...stored, requestKey: stored.requestKey ?? (key === 'new' ? newInboxId() : undefined) };
  });
  const current = useRef(draft);
  const [editing, setEditing] = useState(!!draft && !draft.remove);
  const editingRef = useRef(editing);
  const showEditor = (value: boolean) => { editingRef.current = value; setEditing(value); };
  const latestItem = useRef(item); latestItem.current = item ?? items?.find(value => value.id === draft?.base?.id);
  const pending = useRef<Promise<boolean> | undefined>(undefined);
  const finishing = useRef<Promise<boolean> | undefined>(undefined);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const composing = useRef(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const put = (next?: Draft) => { current.current = next; setDraft(next); saveDraft(key, next); };
  const stopTimer = () => { clearTimeout(timer.current); timer.current = undefined; };
  const conflict = () => !!current.current?.base && !!latestItem.current && latestItem.current.revision > current.current.base.revision;
  const flush = async (): Promise<boolean> => {
    stopTimer();
    if (pending.current) return pending.current;
    if (composing.current) return false;
    const write = async () => {
      setError('');
      try {
        while (current.current && (dirty(current.current) || current.current.remove)) {
          if (conflict()) return false;
          if (composing.current) return false;
          let snapshot = current.current;
          if (snapshot.remove && (snapshot.base || snapshot.captureMarkdown === undefined)) {
            if (snapshot.base) {
              const base = snapshot.base;
              setSaving(true);
              await mutate(async () => {
                try { await inboxApi.remove(base); }
                catch (reason) {
                  // A lost DELETE response must not leave a permanent retry:
                  // a fresh snapshot can confirm that the item is already gone.
                  if ((await inboxApi.list()).items.some(item => item.id === base.id)) throw reason;
                }
              });
            }
            put();
            return true;
          }
          // While typing, keep empty content locally. Only finishing editing
          // requests removal. An uncertain capture must first recover its ID
          // with the original key/payload, then take the removal branch above.
          if (empty(snapshot.markdown) && !snapshot.remove) return true;
          setSaving(true);
          if (!snapshot.base && snapshot.captureMarkdown === undefined) {
            snapshot = { ...snapshot, captureMarkdown: snapshot.markdown };
            // Retrying a capture must use both the same key and the same payload.
            put(snapshot);
          }
          await mutate(async () => {
            const saved = snapshot.base
              ? await inboxApi.update(snapshot.base, fields(snapshot))
              : await inboxApi.capture(snapshot.captureMarkdown!, snapshot.requestKey!);
            if (current.current) put({ ...current.current, base: saved });
            return saved;
          });
        }
        if (!editingRef.current) put();
        return true;
      } catch (reason) { setError(inboxError(reason)); return false; }
      finally { setSaving(false); }
    };
    const request = write();
    pending.current = request;
    try { return await request; } finally { pending.current = undefined; }
  };
  const schedule = () => {
    stopTimer();
    if (!composing.current && current.current && (current.current.remove || (!empty(current.current.markdown) && dirty(current.current)))) {
      timer.current = setTimeout(() => { void flush(); }, 350);
    }
  };
  const begin = () => {
    if (current.current?.remove) return;
    if (!current.current) {
      const base = key === 'new' ? undefined : latestItem.current;
      put({ base, ...fields(base), markdown: base?.markdown ?? '## ', requestKey: key === 'new' ? newInboxId() : undefined });
    }
    showEditor(true); setError('');
  };
  const update = (patch: Partial<Fields>) => {
    if (!current.current || current.current.remove) return;
    put({ ...current.current, ...patch }); setError(''); schedule();
  };
  const finish = (): Promise<boolean> => {
    if (!current.current) return Promise.resolve(true);
    if (composing.current) return Promise.resolve(false);
    if (empty(current.current.markdown)) put({ ...current.current, remove: true });
    showEditor(false);
    if (finishing.current) return finishing.current;
    const request = flush();
    finishing.current = request;
    void request.finally(() => { finishing.current = undefined; });
    return request;
  };
  const resolve = (keep: boolean) => {
    if (!latestItem.current || !current.current || saving) return;
    put(keep ? { ...current.current, base: latestItem.current } : { base: latestItem.current, ...fields(latestItem.current) });
    setError('');
    if (!editingRef.current) void flush(); else schedule();
  };
  useEffect(() => {
    schedule();
    const online = () => { void flush(); };
    window.addEventListener('online', online);
    return () => { stopTimer(); window.removeEventListener('online', online); };
  // The ref owns the current draft, including changes made while a write is pending.
  }, []);
  return { draft, editing, saving, removing: !!draft?.remove, error, conflict: conflict(),
    status: draft?.remove ? (error || conflict() ? '移除失败' : '移除中…') : saving ? '保存中…' : error || conflict() ? '未保存' : draft && empty(draft.markdown) ? '编辑中' : draft && dirty(draft) ? '等待保存' : '已保存',
    begin, update, finish, resolve, retry: flush,
    setComposing: (value: boolean) => { composing.current = value; if (value) stopTimer(); else schedule(); } };
}

import { LiveEvents } from '../../lib/liveEvents';
import { TokenUsageBadge } from '../../components/TokenUsageBadge';
import { useEffect, useId, useRef, useState } from 'react';
import { ChevronDown, ChevronUp, Layers, X } from 'lucide-react';
import './agent-task-notifications.css';
import { useAowTerminalTabActivity, useAowTabNavigation } from '../../aow/AowTabEntry';
import { parseTaskStop, taskNotifications, useTaskNotifications, type TaskNotice } from './taskNotifications';
import { AgentIcon } from '../agents/AgentIcon';

const agentNames: Record<string, string> = { codex: 'Codex', traecli: 'TraeCode CLI', claude: 'Claude Code', hermes: 'Hermes' };
const visibleNoticeCount = 5;

function TaskNoticeCard({ notice }: { notice: TaskNotice }) {
  const navigateTab = useAowTabNavigation();
  const [error, setError] = useState('');
  const [opening, setOpening] = useState(false);
  const sources = notice.sources.filter(source => source.tab_id);
  const projectName = [...new Set(sources.map(source => source.project_name || source.workspace_root.split('/').filter(Boolean).pop() || '未命名项目'))].join('、')
    || notice.cwd.split('/').filter(Boolean).pop() || '未命名项目';
  const tabName = [...new Set(sources.map(source => source.tab_name || '未命名 Tab'))].join('、') || 'Tab 不可用';
  const failure = error || (!sources.length ? '无法定位对应 Tab。' : '');
  const dismiss = () => taskNotifications.dismiss(item => item.key === notice.key);
  const open = async () => {
    if (opening) return;
    setOpening(true);
    setError('');
    // A session may have several source tabs. Open the first one still available.
    let message = '';
    for (const source of sources) {
      try {
        await navigateTab({ type: 'terminal', tabId: source.tab_id });
        dismiss();
        setOpening(false);
        return;
      } catch (reason) { message = reason instanceof Error ? reason.message : String(reason); }
    }
    setError(message);
    setOpening(false);
  };
  return <article className="agent-task-notice" role="status">
    <button type="button" className="agent-task-notice-open" aria-label={`打开通知：${projectName} · ${tabName}`}
      disabled={opening || !sources.length} aria-busy={opening} onClick={() => void open()}>
      <span className="agent-task-notice-agent" title={agentNames[notice.agent] ?? notice.agent}><AgentIcon agentId={notice.agent} /></span>
      <span className="agent-task-notice-content">
        <span className="agent-task-notice-heading"><strong title={projectName}>{projectName}</strong>
          <time dateTime={new Date(notice.receivedAt).toISOString()} title={new Date(notice.receivedAt).toLocaleString()}>
            {new Date(notice.receivedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </time>
        </span>
        <span className="agent-task-notice-tab" title={tabName}>{tabName}</span>
        <TokenUsageBadge usage={notice.usage} />
      </span>
    </button>
    <button type="button" className="agent-task-notice-close" aria-label={`关闭通知：${projectName} · ${tabName}`}
      title="关闭弹框，保留未读提醒" disabled={opening}
      onClick={() => taskNotifications.closePopups(item => item.key === notice.key)}><X size={14} aria-hidden="true" /></button>
    {failure && <div className="agent-task-notice-failure">
      <span className="agent-task-notice-error" role="alert">{failure}</span>
      <button type="button" className="agent-task-notice-remove" onClick={dismiss}>移除通知</button>
    </div>}
  </article>;
}

export function AgentTaskNotifications() {
  const { notices: unreadNotices, storageError } = useTaskNotifications();
  const notices = unreadNotices.filter(notice => !notice.popupClosed);
  const [expanded, setExpanded] = useState(false);
  const tabActivity = useAowTerminalTabActivity();
  const listId = useId();
  const list = useRef<HTMLDivElement>(null);

  useEffect(() => { if (!notices.length) setExpanded(false); }, [notices.length]);

  useEffect(() => {
    const dismissActive = () => {
      const tabId = tabActivity.getCurrent();
      if (tabId) taskNotifications.dismiss(notice => notice.sources.some(source => source.tab_id === tabId));
    };
    dismissActive();
    return tabActivity.subscribe(dismissActive);
  }, [tabActivity]);

  useEffect(() => {
    const source = new LiveEvents('task-stopped');
    const stopped = (event: Event) => {
      let notice;
      try { notice = parseTaskStop(JSON.parse((event as MessageEvent<string>).data)); } catch { return; }
      if (!notice) return;
      if (notice.sources.some(source => source.tab_id === tabActivity.getCurrent())) return;
      // This is a live callback, not session-level deduplication: every newly
      // consumed stop record gets its own notice, including subsequent turns.
      taskNotifications.add(notice);
    };
    source.addEventListener('task-stopped', stopped);
    return () => { source.removeEventListener('task-stopped', stopped); source.close(); };
  }, [tabActivity]);

  if (!notices.length) return null;
  const visibleNotices = expanded ? notices : notices.slice(0, visibleNoticeCount);
  const foldedCount = notices.length - visibleNoticeCount;
  const collapse = () => { setExpanded(false); list.current?.scrollTo({ top: 0 }); };
  return <section className={`agent-task-notifications${expanded ? ' is-expanded' : ''}`} aria-label="任务完成提醒"
    onKeyDown={event => { if (expanded && event.key === 'Escape') { event.stopPropagation(); collapse(); } }}>
    {(notices.length > 1 || expanded) && <div className="agent-task-notifications-toolbar">
      <span>{notices.length} 条待处理</span>
      {expanded && <button onClick={collapse} aria-expanded="true" aria-controls={listId}><ChevronUp size={14} />收起</button>}
      {notices.length > 1 && <button className="agent-task-notifications-clear" title="关闭全部弹框，保留未读提醒" onClick={() => taskNotifications.closePopups(() => true)}>全部关闭</button>}
    </div>}
    {storageError && <div className="agent-task-notifications-storage-error" role="alert">{storageError}</div>}
    <div className="agent-task-notifications-list" id={listId} ref={list} tabIndex={expanded ? 0 : undefined}
      aria-label="待处理通知" aria-live="polite" aria-relevant="additions">
      {visibleNotices.map(notice => <TaskNoticeCard key={notice.key} notice={notice} />)}
    </div>
    {!expanded && foldedCount > 0 && <button className="agent-task-notifications-stack" aria-expanded="false" aria-controls={listId}
      onClick={() => { setExpanded(true); list.current?.scrollTo({ top: 0 }); }}>
      <Layers size={18} aria-hidden="true" /><span><strong>还有 {foldedCount} 条通知</strong><small>展开查看全部</small></span><ChevronDown size={16} aria-hidden="true" />
    </button>}
  </section>;
}

import { appBaseUrl } from '../../lib/basePath';
import { useEffect, useState } from 'react';
import { notificationsApi } from './api';
import type { NotificationChannel, NotificationSettings, NotificationSettingsUpdate, TaskCompletedSettings } from './types';
import './notification-settings.css';
import { ImSettingsPanel } from '../im/ImSettingsPanel';

export function NotificationSettingsPanel({ section, onBusyChange, onDirtyChange }: {
  section: 'im' | 'notifications'; onBusyChange: (busy: boolean) => void; onDirtyChange?: (dirty: boolean) => void;
}) {
  return section === 'im' ? <ImSettingsPanel onBusyChange={onBusyChange} onDirtyChange={onDirtyChange} /> : <NotificationPreferences onBusyChange={onBusyChange} onDirtyChange={onDirtyChange} />;
}

function NotificationPreferences({ onBusyChange, onDirtyChange }: { onBusyChange: (busy: boolean) => void; onDirtyChange?: (dirty: boolean) => void }) {
  const [settings, setSettings] = useState<NotificationSettings>();
  const [task, setTask] = useState<TaskCompletedSettings>({ enabled: true, channels: ['page'] });
  const [publicBaseUrl, setPublicBaseUrl] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState('');
  const feishu = settings?.im.providers.find(provider => provider.provider === 'feishu');
  const wechat = settings?.im.providers.find(provider => provider.provider === 'wechat');
  const dirty = !!settings && (JSON.stringify(task) !== JSON.stringify(settings.notifications.agent_task_completed)
    || publicBaseUrl !== (settings.notifications.public_base_url ?? ''));
  useEffect(() => { onDirtyChange?.(dirty); return () => onDirtyChange?.(false); }, [dirty, onDirtyChange]);

  useEffect(() => {
    let active = true;
    void notificationsApi.notificationSettings().then(next => {
      if (!active) return;
      setSettings(next);
      setTask(next.notifications.agent_task_completed);
      setPublicBaseUrl(next.notifications.public_base_url ?? '');
    }).catch(reason => { if (active) setError(reason instanceof Error ? reason.message : String(reason)); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);

  const changed = () => { setError(''); setSaved(''); };
  const save = async (update: NotificationSettingsUpdate) => {
    setBusy(true); onBusyChange(true); changed();
    try {
      const next = await notificationsApi.updateNotificationSettings(update);
      setSettings(next);
      setTask(next.notifications.agent_task_completed);
      setPublicBaseUrl(next.notifications.public_base_url ?? '');
      setSaved('通知配置已保存，即时生效。');
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
    } finally { setBusy(false); onBusyChange(false); }
  };
  const toggleChannel = (channel: NotificationChannel, checked: boolean) => {
    changed();
    setTask(previous => ({ ...previous, channels: checked
      ? [...previous.channels, channel] : previous.channels.filter(value => value !== channel) }));
  };
  const unavailable = loading || busy || !settings;
  const noChannels = task.enabled && task.channels.length === 0;

  return <form className="notification-settings-form project-aow-dialog-form" onSubmit={event => {
    event.preventDefault();
    if (!noChannels) void save({ section: 'notifications', agent_task_completed: task, public_base_url: publicBaseUrl.trim() });
  }}>
    <div className="project-aow-dialog-body">
      <div className="project-aow-settings-heading"><div>
        <h2>通知</h2>
        <p>选择 Agent 任务完成后的通知方式。</p>
      </div></div>
      {loading && <p role="status">加载配置中…</p>}
      <>
        <label className="project-aow-dialog-field"><span>AoW 访问地址</span><input type="url" aria-label="AoW 访问地址" value={publicBaseUrl} disabled={unavailable} spellCheck={false} placeholder="https://aow.example.com" onChange={event => { setPublicBaseUrl(event.target.value); changed(); }} /></label>
        <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => { setPublicBaseUrl(appBaseUrl()); changed(); }}>使用当前访问地址</button>
        <p className="project-aow-form-intro">用于 IM 通知中的 Tab 链接，请填写接收设备可访问的部署入口地址，包含端口和子目录（如有）。留空时只显示 Tab 名称。</p>
        <label className="project-aow-dialog-checkbox notification-checkbox notification-master"><input type="checkbox" checked={task.enabled} disabled={unavailable} onChange={event => {
          changed(); setTask(previous => ({ ...previous, enabled: event.target.checked,
            channels: event.target.checked && !previous.channels.length ? ['page'] : previous.channels }));
        }} /><span>Agent 任务完成</span></label>
        {settings && task.enabled && <fieldset disabled={unavailable} className="notification-channels">
          <legend>通知方式（至少选择一项）</legend>
          <label className="project-aow-dialog-checkbox notification-checkbox"><input type="checkbox" checked={task.channels.includes('page')} onChange={event => toggleChannel('page', event.target.checked)} /><span>页面提示</span></label>
          {feishu && <label className="project-aow-dialog-checkbox notification-checkbox"><input type="checkbox" checked={task.channels.includes('feishu')} onChange={event => toggleChannel('feishu', event.target.checked)} /><span>飞书推送</span></label>}
          {wechat && <label className="project-aow-dialog-checkbox notification-checkbox"><input type="checkbox" checked={task.channels.includes('wechat')} onChange={event => toggleChannel('wechat', event.target.checked)} /><span>微信推送</span></label>}
          {!feishu && !wechat && <p className="project-aow-form-intro">在 IM 中配置飞书或微信 Bot 后，可选择 IM 推送。</p>}
          {noChannels && <p role="alert" className="project-aow-error">至少选择一种通知方式。</p>}
        </fieldset>}
        <p className="project-aow-form-intro">通知包含项目、Tab 名称和触发的 Session ID。IM 推送在网页关闭后仍可发送。</p>
      </>
      {saved && <p role="status">{saved}</p>}
      {error && <div role="alert" className="project-aow-error">{error}</div>}
    </div>
    <footer className="project-aow-dialog-footer">
      <button type="submit" className="project-aow-dialog-button primary" disabled={unavailable || noChannels}>{busy ? '保存中…' : '保存'}</button>
    </footer>
  </form>;
}

