interface Props {
  tabId: string;
  paneId: string;
  agentId?: string | null;
  title: string;
  cwd: string;
  process?: TerminalAgentProcess;
  visible: boolean;
  header: (sessionButton: ReactNode) => ReactNode;
  terminal: (visible: boolean) => ReactNode;
}

