function savedAssociation(storageKey: string, identity: string, liveId: string | null): string | undefined {
  try {
    const saved = JSON.parse(appSessionStorage.getItem(storageKey) ?? 'null');
    return saved?.key === identity && saved.liveId === liveId && typeof saved.id === 'string' ? saved.id : undefined;
  } catch { return undefined; }
}

function relativeTime(value: string) {
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) return value;
  const seconds = Math.round((timestamp - Date.now()) / 1000);
  if (seconds === 0) return '刚刚';
  const ranges: [Intl.RelativeTimeFormatUnit, number][] = [
    ['year', 31_536_000], ['month', 2_592_000], ['week', 604_800],
    ['day', 86_400], ['hour', 3_600], ['minute', 60],
  ];
  const formatter = new Intl.RelativeTimeFormat('zh-CN', { numeric: 'always' });
  for (const [unit, size] of ranges) {
    if (Math.abs(seconds) >= size) return formatter.format(Math.round(seconds / size), unit);
  }
  return formatter.format(seconds, 'second');
}

export function TerminalAgentPane({ tabId, paneId, agentId, title, cwd, process, visible, header, terminal }: Props) {
  const titleSource = agentSessionTitleSource(agentId);
  const supported = !!titleSource;
  const storageKey = `terminal.agent-session.${tabId}.${paneId}`;
  // Native display titles can change without changing the session identity.
  const identity = JSON.stringify([tabId, paneId, agentId, process?.pid, process?.start_time, process?.cwd ?? cwd,
    titleSource === 'native' ? '' : terminalSessionTitle(title, process?.cwd ?? cwd)]);
  const [open, setOpen] = useState(false);
  const [association, setAssociation] = useState<Association>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [query, setQuery] = useState('');
  const [showAll, setShowAll] = useState(false);
  const [snapshotState, setSnapshotState] = useState<{ key: string; snapshot?: AgentSessionSnapshot; loading: boolean; error?: string }>();
  const [revision, setRevision] = useState(0);
  const currentIdentity = useRef(identity);
  currentIdentity.current = identity;
  const request = useRef<AbortController | undefined>(undefined);
  const current = association?.key === identity ? association : undefined;
  const selected = current?.choosing ? undefined : current?.selected;
  const showing = open && supported;

  const refresh = useCallback(async () => {
    request.current?.abort();
    const controller = new AbortController();
    request.current = controller;
    setLoading(true);
    setError('');
    try {
      const data = await terminalApi.paneSessions(tabId, paneId, controller.signal);
      if (controller.signal.aborted || currentIdentity.current !== identity) return;
      // Ignore results from a newer process until the shared metadata poll
      // catches up; a response must not bind an old pane generation.
      if (data.agent !== agentId || (process && (data.process?.pid !== process.pid
        || data.process.start_time !== process.start_time))) {
        setAssociation(undefined);
        setError('Agent 进程已变化，请刷新会话列表');
        return;
      }
      const candidates = terminalSessionCandidates(data);
      setAssociation(previous => {
        const same = previous?.key === identity ? previous : undefined;
        const liveChanged = same?.data?.live_session_id !== data.live_session_id;
        const savedId = savedAssociation(storageKey, identity, data.live_session_id);
        const retainedId = !liveChanged && same?.manual && same.selected ? same.selected.id : savedId;
        const retained = data.sessions.find(session => session.id === retainedId);
        return {
          key: identity, data,
          selected: retained ?? (same?.choosing ? undefined : candidates.automatic),
          choosing: same?.choosing ?? false,
          manual: !!retained && (same?.manual === true || retained.id === savedId),
        };
      });
      setRevision(value => value + 1);
    } catch (reason) {
      if (!controller.signal.aborted && currentIdentity.current === identity) {
        setError(reason instanceof Error ? reason.message : String(reason));
      }
    } finally {
      if (!controller.signal.aborted && currentIdentity.current === identity) setLoading(false);
    }
  }, [tabId, paneId, identity, agentId, process?.pid, process?.start_time]);

  useEffect(() => {
    setQuery('');
    setShowAll(false);
    if (!supported) { setOpen(false); setAssociation(undefined); }
  }, [identity, supported]);

  useEffect(() => {
    if (!showing || !visible) return;
    const update = () => { if (document.visibilityState === 'visible') void refresh(); };
    update();
    const timer = window.setInterval(update, 10_000);
    document.addEventListener('visibilitychange', update);
    return () => {
      request.current?.abort();
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', update);
    };
  }, [showing, visible, refresh]);

  const snapshotKey = selected ? `${identity}:${selected.id}` : '';
  useEffect(() => {
    if (!selected || !showing || !visible || error) return;
    const controller = new AbortController();
    setSnapshotState(previous => ({ key: snapshotKey, snapshot: previous?.key === snapshotKey ? previous.snapshot : undefined, loading: true }));
    void sessionsApi.agentSessionSnapshot(selected, selected.cwd, controller.signal).then(snapshot => {
      if (!controller.signal.aborted) setSnapshotState({ key: snapshotKey, snapshot, loading: false });
    }).catch(reason => {
      if (!controller.signal.aborted) setSnapshotState(previous => ({
        key: snapshotKey, snapshot: previous?.key === snapshotKey ? previous.snapshot : undefined,
        loading: false, error: reason instanceof Error ? reason.message : String(reason),
      }));
    });
    return () => controller.abort();
  }, [snapshotKey, revision, showing, visible, error]);

  const snapshot = snapshotState?.key === snapshotKey ? snapshotState : undefined;
  const candidates = current?.data ? terminalSessionCandidates(current.data) : undefined;
  const matches = candidates?.matches ?? [];
  const sessions = current?.data?.sessions ?? [];
  const displayed = sessionSearch(showAll || !matches.length ? sessions : matches, query);

  const choose = (session: AowAgentSession) => {
    try { appSessionStorage.setItem(storageKey, JSON.stringify({ key: identity, id: session.id, liveId: current?.data?.live_session_id ?? null })); } catch { /* Storage may be unavailable. */ }
    setAssociation(previous => previous?.key === identity
      ? { ...previous, selected: session, choosing: false, manual: true } : previous);
  };
  const reselect = () => {
    setAssociation(previous => previous?.key === identity ? { ...previous, choosing: true } : previous);
    setQuery('');
    setShowAll(true);
    void refresh();
  };

  return <>
    {header(supported ? <button className="terminal-agent-session-button" type="button"
      title={showing ? '返回终端' : '切换到会话详情'} aria-label={showing ? '返回终端' : '切换到会话详情'}
      aria-pressed={showing} onClick={() => setOpen(value => !value)}>
      {showing ? <SquareTerminal /> : <MessageSquare />}<span>{showing ? 'Terminal' : 'Conversation'}</span>
    </button> : null)}
    <div className="terminal-pane-surface" hidden={showing}>
      {terminal(visible && !showing)}
    </div>
    {showing ? <div className="terminal-agent-session-surface">
      <div className="terminal-agent-session-toolbar">
        <span title={selected?.session_id ?? current?.data?.cwd ?? cwd}>
          {selected ? `${current?.manual ? '已选择' : current?.data?.live_session_id ? '当前会话' : '标题匹配'} · ${selected.session_id}` : '选择当前会话'}
        </span>
        {selected ? <button type="button" onClick={reselect}>重新选择</button> : null}
        <button type="button" title="刷新会话列表" aria-label="刷新会话列表" disabled={loading} onClick={() => void refresh()}><RefreshCw className={loading ? 'spinning' : ''} /></button>
      </div>
      {error ? <div className="terminal-agent-session-error" role="alert">{error}</div> : null}
      {selected ? <SessionSnapshotView session={selected} snapshot={snapshot?.snapshot} loading={snapshot?.loading ?? true}
        actions={snapshot?.snapshot && <SessionShareButton session={selected} workspacePath={selected.cwd} />}
        error={snapshot?.error} onRefresh={() => void refresh()} /> : <div className="terminal-agent-session-picker">
        <p>{loading && !current?.data ? '正在查找当前会话…'
          : current?.data?.live_session_id && !matches.length ? '已识别当前会话，记录尚未就绪。可刷新重试或手动选择。'
          : matches.length ? `找到 ${matches.length} 个标题匹配的会话，请确认当前正在使用的会话。`
          : '未找到唯一匹配，请从当前目录的会话中选择。'}</p>
        <div className="terminal-agent-session-filter">
          <input aria-label="搜索会话标题或 ID" placeholder="搜索会话标题或 ID" value={query} onChange={event => setQuery(event.target.value)} />
          {matches.length > 0 ? <button type="button" onClick={() => setShowAll(value => !value)}>{showAll ? '只看标题匹配' : '显示全部会话'}</button> : null}
        </div>
        <div className="terminal-agent-session-directory" title={current?.data?.cwd ?? cwd}>{current?.data?.cwd ?? cwd}</div>
        <div className="terminal-agent-session-list" aria-label="候选会话">
          {loading && !current?.data ? <LoaderCircle className="spinning" /> : null}
          {!loading && !displayed.length ? <p>暂无匹配会话。新会话产生记录后可刷新重试。</p> : null}
          {displayed.map(session => <button type="button" key={session.id} onClick={() => choose(session)}>
            <strong><span>{session.title}</span><time dateTime={session.updated_at}>{relativeTime(session.updated_at)}</time></strong>
            <span><code>{session.session_id}</code><time dateTime={session.updated_at}>{new Date(session.updated_at).toLocaleString()}</time></span>
          </button>)}
        </div>
      </div>}
    </div> : null}
  </>;
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { RefreshCw, Trash2 } from 'lucide-react';
import { WorkspaceMenuLabel } from '../../aow/WorkspaceMenuLabel';

export function TerminalContextMenu({ x, y, title, onClose, onOpen, onOpenFloating, onRebuild, rebuilding, onDestroy, container }: {
  container?: HTMLElement;
  x: number;
  y: number;
  title: string;
  onClose: () => void;
  onOpen: () => void;
  onOpenFloating?: () => void;
  onRebuild?: () => void;
  rebuilding?: boolean;
  onDestroy: () => void;
}) {
  const menu = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x, y });

  useLayoutEffect(() => {
    const bounds = menu.current?.getBoundingClientRect();
    if (!bounds) return;
    setPosition({
      x: Math.max(4, Math.min(x, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(y, window.innerHeight - bounds.height - 4)),
    });
  }, [x, y]);

  useEffect(() => {
    const close = () => onClose();
    const key = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('pointerdown', close);
    window.addEventListener('scroll', close, true);
    window.addEventListener('resize', close);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', close);
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('resize', close);
      window.removeEventListener('keydown', key);
    };
  }, [onClose]);

  const action = (callback: () => void) => () => { onClose(); callback(); };
  return createPortal(<div ref={menu} className="project-aow-context-menu project-aow-terminal-menu"
    style={{ left: position.x, top: position.y }} role="menu" aria-label={`${title} 终端操作`}
    onPointerDown={event => event.stopPropagation()} onContextMenu={event => event.preventDefault()}>
    <button role="menuitem" onClick={action(onOpen)}><WorkspaceMenuLabel action="open" /></button>
    {onOpenFloating ? <button role="menuitem" onClick={action(onOpenFloating)}><WorkspaceMenuLabel action="floating" /></button> : null}
    {onRebuild ? <button role="menuitem" disabled={rebuilding} onClick={action(onRebuild)}><RefreshCw />{rebuilding ? '重建中…' : '重建'}</button> : null}
    <button className="danger" role="menuitem" onClick={action(onDestroy)}><Trash2 />销毁</button>
  </div>, container ?? document.body);
}

import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Bot, LoaderCircle, Search } from 'lucide-react';
import { aowApi } from '../../aow/aowApi';
import { automationApi } from '../automations/api';
import type { AutomationTask } from '../automations/types';
import { terminalApi } from './terminalApi';
import type { TerminalPane, TerminalTab } from './types';
import './terminal-hosting.css';

export function TerminalHostingButton({ tab, pane, onChange }: {
  tab: TerminalTab; pane: TerminalPane; onChange: (tab: TerminalTab) => void;
}) {
  const button = useRef<HTMLButtonElement>(null);
  const popup = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState<{ left: number; top: number }>();
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [search, setSearch] = useState('');
  const [maxInputs, setMaxInputs] = useState('3');
  const validLimit = Number.isInteger(Number(maxInputs)) && Number(maxInputs) > 0 && Number(maxInputs) <= 4_294_967_295;
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!position) return;
    let active = true;
    setLoading(true); setError(''); setSearch('');
    void aowApi.projects().then(projects => {
      const project = projects.find(project => project.worktrees.some(worktree => worktree.path === tab.workspace_root));
      if (!project) throw new Error('当前工作区未关联项目');
      return automationApi.list(project.id);
    }).then(tasks => { if (active) setTasks(tasks.filter(task => task.kind === 'manual' && task.workspace_mode === 'dynamic')); })
      .catch(reason => { if (active) setError(reason instanceof Error ? reason.message : String(reason)); })
      .finally(() => { if (active) setLoading(false); });
    const close = (event: PointerEvent) => {
      if (!popup.current?.contains(event.target as Node) && !button.current?.contains(event.target as Node)) setPosition(undefined);
    };
    const key = (event: KeyboardEvent) => { if (event.key === 'Escape') { setPosition(undefined); button.current?.focus(); } };
    const resize = () => setPosition(undefined);
    window.addEventListener('pointerdown', close); window.addEventListener('keydown', key); window.addEventListener('resize', resize);
    return () => { active = false; window.removeEventListener('pointerdown', close); window.removeEventListener('keydown', key); window.removeEventListener('resize', resize); };
  }, [Boolean(position), tab.workspace_root]);

  const select = async (task: AutomationTask) => {
    if (!validLimit) return;
    setBusy(true); setError('');
    try { onChange(await terminalApi.host(tab.id, pane.id, task.id, task.revision, Number(maxInputs))); setPosition(undefined); }
    catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); }
    finally { setBusy(false); }
  };
  const matches = tasks.filter(task => `${task.name} ${task.prompt}`.toLowerCase().includes(search.toLowerCase()));
  return <>
    <button ref={button} type="button" className="terminal-hosting-button" title="选择手动任务并开启托管" aria-label="Autopilot"
      aria-haspopup="dialog" aria-expanded={Boolean(position)} disabled={Boolean(pane.hosting) || pane.status !== 'running' || busy}
      onClick={event => {
        event.stopPropagation();
        const rect = event.currentTarget.getBoundingClientRect();
        setPosition(position ? undefined : { left: Math.max(8, Math.min(rect.right - 320, window.innerWidth - 328)), top: Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - 360)) });
      }}><Bot />Autopilot</button>
    {position && createPortal(<div ref={popup} className="terminal-hosting-menu" style={position} role="dialog" aria-label="选择托管任务"
      onPointerDown={event => event.stopPropagation()} onClick={event => event.stopPropagation()}>
      <strong>选择托管任务</strong>
      <p className="terminal-hosting-limit-hint">仅支持动态指定工作区的手动任务，执行时自动使用当前 Agent 的工作目录。</p>
      <label className="terminal-hosting-limit">最多自动输入次数<input type="number" min="1" step="1" aria-label="最多自动输入次数" value={maxInputs} disabled={busy} onChange={event => setMaxInputs(event.target.value)} /></label>
      <p className="terminal-hosting-limit-hint">达到上限后仍会做最后一次审查，不再自动输入。</p>
      {!validLimit && <p className="terminal-hosting-menu-error" role="alert">请输入有效的正整数</p>}
      <label className="terminal-hosting-search"><Search /><input autoFocus placeholder="搜索手动任务…" aria-label="搜索手动任务" value={search} onChange={event => setSearch(event.target.value)} /></label>
      <div className="terminal-hosting-tasks">
        {loading ? <p role="status"><LoaderCircle className="spinning" />加载中…</p> : matches.map(task => <button key={task.id} type="button" disabled={busy || !validLimit} onClick={() => void select(task)}>
          <span>{task.name}</span><small>{task.prompt.replace(/\s+/g, ' ').slice(0, 100)}</small>
        </button>)}
        {!loading && !matches.length && <p>{tasks.length ? '没有匹配的任务' : '暂无可用任务，请在 Automation 中创建手动任务，并选择「动态工作区 → 动态指定」。'}</p>}
      </div>
      {busy && <p role="status">正在开启托管…</p>}
      {error && <p className="terminal-hosting-menu-error" role="alert">{error}</p>}
    </div>, document.body)}
  </>;
}

import { useEffect, useState } from 'react';
import { AlertTriangle, CircleCheck } from 'lucide-react';
import { aowApi } from '../../aow/aowApi';
import { useAowTabNavigation } from '../../aow/AowTabEntry';
import { tabTargetUrl, type TabTarget } from '../../aow/tabRoutes';
import type { TerminalHosting } from './types';
import './terminal-hosting.css';

const hostingPhases: Record<TerminalHosting['phase'], string> = {
  waiting: '等待本轮完成', reviewing: '检查中', collecting: '读取结论', submitting: '提交反馈', failed: '已暂停',
  completed: '审查通过', limit_reached: '已达输入上限',
};

export function hostingStatus(hosting: TerminalHosting) {
  const state = hosting.phase === 'completed' ? '托管已结束' : hosting.phase === 'limit_reached' ? '托管已停止' : '托管中';
  return `${state} · ${hosting.task_name} · ${hostingPhases[hosting.phase]} · 已输入 ${hosting.input_count}/${hosting.max_inputs} 次`;
}

export function TerminalHostingDetails({ hosting }: { hosting: TerminalHosting }) {
  const navigate = useAowTabNavigation();
  const [target, setTarget] = useState<TabTarget>();
  const [error, setError] = useState('');
  const completed = hosting.phase === 'completed';
  const message = hosting.error || (hosting.phase === 'limit_reached' ? '请接管后处理剩余审查结论。' : '');
  const show = Boolean(message) || completed;
  useEffect(() => {
    let active = true;
    setTarget(undefined); setError('');
    if (!show || !hosting.run_id) return;
    void aowApi.projects().then(projects => {
      const worktree = projects.flatMap(project => project.worktrees).find(worktree => worktree.path === hosting.workspace_root);
      if (!worktree) throw new Error('执行记录所属工作区已移除');
      if (active) setTarget({ type: 'automation', workspace: worktree.id, taskId: hosting.task_id, runId: hosting.run_id!, view: 'runs' });
    }).catch(reason => { if (active) setError(reason instanceof Error ? reason.message : String(reason)); });
    return () => { active = false; };
  }, [show, hosting.task_id, hosting.run_id, hosting.workspace_root]);
  if (!show) return null;
  return <div className={`terminal-hosting-details${completed ? ' completed' : ''}`} role={completed && !error ? 'status' : 'alert'}>
    {completed ? <CircleCheck /> : <AlertTriangle />}{(message || error) && <span>{message}{error ? `${message ? ' · ' : ''}${error}` : ''}</span>}
    {target && <a href={tabTargetUrl(target)} onClick={event => {
      event.stopPropagation();
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      event.preventDefault();
      void navigate(target).catch(reason => setError(reason instanceof Error ? reason.message : String(reason)));
    }}>查看本次执行</a>}
  </div>;
}

import Editor from '../editor/MonacoEditor';

export default function TerminalInputEditor({ value, onChange, onComposing }: { value: string; onChange: (value: string) => void; onComposing: (active: boolean) => void }) {
  return <Editor language="markdown" theme="vs-dark" value={value} onChange={value => onChange(value ?? '')}
    loading={<span className="terminal-input-loading">正在加载编辑器…</span>}
    onMount={editor => {
      const listeners = [editor.onDidCompositionStart(() => onComposing(true)), editor.onDidCompositionEnd(() => onComposing(false))];
      editor.onDidDispose(() => { listeners.forEach(listener => listener.dispose()); onComposing(false); });
      const model = editor.getModel();
      if (model) editor.setPosition(model.getPositionAt(model.getValueLength()));
      editor.focus();
    }}
    options={{
      ariaLabel: '终端 Markdown 输入', automaticLayout: true, minimap: { enabled: false },
      fontFamily: "'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace",
      lineHeight: 15, cursorStyle: 'line', cursorBlinking: 'blink',
      fontSize: 13, lineNumbers: 'off', glyphMargin: false, folding: false, lineDecorationsWidth: 8,
      wordWrap: 'on', scrollBeyondLastLine: false, overviewRulerLanes: 0, hideCursorInOverviewRuler: true,
      renderLineHighlight: 'none', padding: { top: 8, bottom: 8 },
      occurrencesHighlight: 'off', selectionHighlight: false,
      quickSuggestions: false, suggestOnTriggerCharacters: false, parameterHints: { enabled: false },
      contextmenu: false, tabFocusMode: true, stickyScroll: { enabled: false },
      scrollbar: { verticalScrollbarSize: 8, horizontalScrollbarSize: 8 },
    }} />;
}

import { lazy, Suspense, useEffect, useLayoutEffect, useRef, useState, type ComponentProps } from 'react';
import { ChevronUp } from 'lucide-react';
import type { TerminalPaneControls } from './terminalPresentation';
import type { TerminalConnectionState } from './terminalState';
import { TerminalPaneView } from './TerminalPaneView';
import './terminal-input.css';

const TerminalInputEditor = lazy(() => import('./TerminalInputEditor'));
const DEFAULT_INPUT_HEIGHT = 80;

type Props = Pick<ComponentProps<typeof TerminalPaneView>, 'visible' | 'tabId' | 'pane' | 'active' | 'onFocus' | 'onStatus' | 'onRebuild' | 'rebuilding'>;

export function TerminalInputPane(props: Props) {
  const isMacOS = navigator.userAgent.includes('Macintosh');
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState('');
  const [height, setHeight] = useState(DEFAULT_INPUT_HEIGHT);
  const [availableHeight, setAvailableHeight] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [error, setError] = useState('');
  const [connection, setConnection] = useState<TerminalConnectionState>('connecting');
  const controls = useRef<TerminalPaneControls | null>(null);
  const container = useRef<HTMLDivElement>(null);
  const composer = useRef<HTMLDivElement>(null);
  const composing = useRef(false);
  const drag = useRef<{ y: number; height: number } | null>(null);
  const ready = props.visible && props.pane.status === 'running' && connection === 'connected' && !props.pane.hosting;
  const shown = open && ready && props.active;
  const maxHeight = Math.max(0, availableHeight - 40);
  const minHeight = Math.min(DEFAULT_INPUT_HEIGHT, maxHeight);
  const editorHeight = Math.max(minHeight, Math.min(height, maxHeight));

  const dismiss = () => {
    setOpen(false);
    setDragging(false);
    drag.current = null;
    composing.current = false;
  };

  useLayoutEffect(() => {
    const node = container.current;
    if (!node) return;
    const measure = () => setAvailableHeight(node.clientHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  useLayoutEffect(() => {
    if (shown) composer.current?.focus({ preventScroll: true });
  }, [shown]);

  useEffect(() => { if (!ready || !props.active) dismiss(); }, [ready, props.active]);

  useEffect(() => {
    if (!shown) return;
    const outside = (event: PointerEvent) => {
      if (!composer.current?.contains(event.target as Node)) dismiss();
    };
    const hidden = () => { if (document.hidden) dismiss(); };
    document.addEventListener('pointerdown', outside, true);
    document.addEventListener('visibilitychange', hidden);
    window.addEventListener('blur', dismiss);
    return () => {
      document.removeEventListener('pointerdown', outside, true);
      document.removeEventListener('visibilitychange', hidden);
      window.removeEventListener('blur', dismiss);
    };
  }, [shown]);

  const submit = () => {
    if (!draft.trim() || composing.current) return;
    try {
      if (!controls.current?.submit(draft)) {
        setError('终端暂时无法接收输入，草稿已保留');
        return;
      }
      setDraft('');
      setError('');
      dismiss();
      controls.current.focus();
    } catch {
      setError('发送失败，草稿已保留');
    }
  };

  return <div ref={container} className={`terminal-input-pane${dragging ? ' resizing' : ''}`}>
    {/* Transforms leave the measured xterm container and PTY grid unchanged. */}
    <div className="terminal-input-surface" style={{ transform: `translateY(-${shown ? editorHeight : 0}px)` }}>
      <TerminalPaneView {...props} controlsRef={controls} inputSuspended={shown} onConnectionChange={setConnection} />
    </div>
    {ready && !shown ? <button type="button" className="terminal-input-trigger" aria-label="打开终端输入编辑器"
      onClick={() => { props.onFocus(); setError(''); setOpen(true); }}>
      <span><ChevronUp aria-hidden="true" />点击编辑输入</span>
    </button> : null}
    {shown ? <div ref={composer} className="terminal-input-composer" style={{ height: editorHeight }}
      role="group" aria-label="终端输入编辑器" tabIndex={-1}
      onBlurCapture={event => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) dismiss();
      }}
      onKeyDownCapture={event => {
        if (event.nativeEvent.isComposing || composing.current || event.keyCode === 229) return;
        const submitShortcutPressed = isMacOS ? event.metaKey && !event.ctrlKey : event.ctrlKey && !event.metaKey;
        if (event.key === 'Enter' && submitShortcutPressed && !event.shiftKey && !event.altKey
          && event.target instanceof HTMLElement && event.target.matches('[role="textbox"]')
          && event.target.closest('.monaco-editor')) {
          event.preventDefault();
          event.stopPropagation();
          if (!event.repeat) submit();
        } else if (event.key === 'Escape') {
          event.preventDefault();
          event.stopPropagation();
          dismiss();
          controls.current?.focus();
        }
      }}>
      <div className="terminal-input-resize" role="separator" aria-label="调整输入编辑器高度"
        aria-orientation="horizontal" tabIndex={0} aria-valuenow={Math.round(editorHeight)}
        aria-valuemin={minHeight} aria-valuemax={maxHeight}
        onKeyDown={event => {
          if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
          event.preventDefault();
          event.stopPropagation();
          setHeight(Math.max(minHeight, Math.min(maxHeight, editorHeight + (event.key === 'ArrowUp' ? 20 : -20))));
        }}
        onPointerDown={event => {
          if (event.button !== 0) return;
          event.preventDefault();
          event.currentTarget.setPointerCapture(event.pointerId);
          drag.current = { y: event.clientY, height: editorHeight };
          setDragging(true);
        }}
        onPointerMove={event => {
          if (!drag.current) return;
          setHeight(Math.max(minHeight, Math.min(maxHeight, drag.current.height + drag.current.y - event.clientY)));
        }}
        onPointerUp={event => {
          event.currentTarget.releasePointerCapture(event.pointerId);
          drag.current = null;
          setDragging(false);
        }}
        onLostPointerCapture={() => { drag.current = null; setDragging(false); }} />
      <div className="terminal-input-editor">
        <Suspense fallback={<span className="terminal-input-loading">正在加载编辑器…</span>}>
          <TerminalInputEditor value={draft} onChange={setDraft} onComposing={active => { composing.current = active; }} />
        </Suspense>
      </div>
      <div className="terminal-input-hint">Enter 换行 · {isMacOS ? '⌘ + Enter' : 'Ctrl + Enter'} 提交</div>
      {error ? <div className="terminal-input-error" role="alert">{error}</div> : null}
    </div> : null}
  </div>;
}

