import { appUrl } from '../../lib/basePath';
import { defaultTerminalPaneName } from './terminalPresentation';
import type { TerminalAgentList, TerminalLayout, TerminalPane, TerminalPaneStatus, TerminalPaneSessions, TerminalAgentProcess, TerminalSplitAxis, TerminalTab } from './types';

const TERMINALS_PATH = appUrl('/api/terminals');
const paneStatuses = new Set<TerminalPaneStatus>(['running', 'exited', 'interrupted']);

class TerminalHttpError extends Error {
  constructor(message: string, readonly status: number) { super(message); }
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : undefined;
}

function errorMessage(payload: unknown, fallback: string) {
  const value = asRecord(payload);
  const error = asRecord(value?.error);
  return typeof value?.message === 'string'
    ? value.message
    : typeof error?.message === 'string'
      ? error.message
      : fallback;
}

async function request(url: string, init?: RequestInit, timeoutMs = 15_000, externalSignal?: AbortSignal): Promise<unknown> {
  const controller = new AbortController();
  let timedOut = false;
  const abortFromExternal = () => controller.abort();
  if (externalSignal?.aborted) controller.abort();
  else externalSignal?.addEventListener('abort', abortFromExternal, { once: true });
  const timer = window.setTimeout(() => { timedOut = true; controller.abort(); }, timeoutMs);
  try {
    const response = await fetch(url, {
      ...init,
      signal: controller.signal,
      headers: init?.body === undefined
        ? init?.headers
        : { 'Content-Type': 'application/json', ...init.headers },
    });
    const payload = response.status === 204 ? null : await response.json().catch(() => null);
    if (!response.ok) throw new TerminalHttpError(errorMessage(payload, `HTTP ${response.status}`), response.status);
    return payload;
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      if (timedOut) throw new Error(`终端请求超时（${Math.round(timeoutMs / 1000)} 秒）`);
    }
    throw error;
  } finally {
    window.clearTimeout(timer);
    externalSignal?.removeEventListener('abort', abortFromExternal);
  }
}

function normalizeLayout(value: unknown): TerminalLayout | null {
  const item = asRecord(value);
  if (!item) return null;
  if (item.type === 'pane' && typeof item.pane_id === 'string') {
    return { type: 'pane', pane_id: item.pane_id };
  }
  if (item.type !== 'split' || (item.axis !== 'row' && item.axis !== 'column')) return null;
  const first = normalizeLayout(item.first);
  const second = normalizeLayout(item.second);
  if (!first || !second) return null;
  const ratio = typeof item.ratio === 'number' && Number.isFinite(item.ratio)
    ? Math.min(.9, Math.max(.1, item.ratio))
    : .5;
  return { type: 'split', axis: item.axis, ratio, first, second };
}

function normalizePane(value: unknown): TerminalPane | null {
  const item = asRecord(value);
  if (!item || typeof item.id !== 'string') return null;
  const status = paneStatuses.has(item.status as TerminalPaneStatus)
    ? item.status as TerminalPaneStatus
    : 'running';
  const cwd = typeof item.cwd === 'string' ? item.cwd : '';
  const shell = typeof item.shell === 'string' ? item.shell : '';
  const agentTerminal = asRecord(item.agent_terminal);
  const hosting = asRecord(item.hosting);
  return {
    id: item.id,
    // Pane names are generated; ignore legacy custom names from stored metadata
    // and older servers, including when no OSC title is available.
    name: defaultTerminalPaneName({ cwd, shell }),
    cwd,
    shell,
    arguments: Array.isArray(item.arguments) ? item.arguments.filter((value): value is string => typeof value === 'string') : [],
    kind: item.kind === 'agent' ? 'agent' : 'terminal',
    ...(hosting && typeof hosting.id === 'string' && typeof hosting.task_id === 'string'
      && typeof hosting.task_name === 'string' && typeof hosting.workspace_root === 'string'
      && ['waiting', 'reviewing', 'collecting', 'submitting', 'completed', 'limit_reached', 'failed'].includes(String(hosting.phase)) ? {
      hosting: {
        id: hosting.id, task_id: hosting.task_id, task_name: hosting.task_name, workspace_root: hosting.workspace_root,
        phase: hosting.phase as NonNullable<TerminalPane['hosting']>['phase'],
        max_inputs: typeof hosting.max_inputs === 'number' ? hosting.max_inputs : 3,
        input_count: typeof hosting.input_count === 'number' ? hosting.input_count : 0,
        run_id: typeof hosting.run_id === 'string' ? hosting.run_id : null,
        error: typeof hosting.error === 'string' ? hosting.error : null,
      },
    } : {}),
    ...(agentTerminal && ['starting', 'ready', 'failed'].includes(String(agentTerminal.phase)) ? {
      agent_terminal: {
        phase: agentTerminal.phase as 'starting' | 'ready' | 'failed',
        error: typeof agentTerminal.error === 'string' ? agentTerminal.error : null,
        task_submitted: agentTerminal.task_submitted === true,
      },
    } : {}),
    ...(typeof item.agent_id === 'string' || item.agent_id === null
      ? { agent_id: item.agent_id } : {}),
    ...(typeof item.restart_on_daemon_restart === 'boolean' ? { restart_on_daemon_restart: item.restart_on_daemon_restart } : {}),
    status,
    ...(typeof item.exit_code === 'number' || item.exit_code === null
      ? { exit_code: item.exit_code }
      : {}),
    ...(typeof item.rows === 'number' ? { rows: item.rows } : {}),
    ...(typeof item.cols === 'number' ? { cols: item.cols } : {}),
  };
}

function normalizeTab(value: unknown): TerminalTab | null {
  const item = asRecord(value);
  if (!item || typeof item.id !== 'string') return null;
  return {
    id: item.id,
    name: typeof item.name === 'string' && item.name.trim() ? item.name : 'Terminal',
    ...(typeof item.name_is_custom === 'boolean' ? { name_is_custom: item.name_is_custom } : {}),
    workspace_root: typeof item.workspace_root === 'string' ? item.workspace_root : '',
    layout: normalizeLayout(item.layout),
    panes: Array.isArray(item.panes)
      ? item.panes.map(normalizePane).filter((pane): pane is TerminalPane => pane !== null)
      : [],
    ...(typeof item.revision === 'number' || typeof item.revision === 'string'
      ? { revision: item.revision }
      : {}),
    ...(typeof item.created_at === 'string' || typeof item.created_at === 'number' ? { created_at: item.created_at } : {}),
    ...(typeof item.updated_at === 'string' || typeof item.updated_at === 'number' ? { updated_at: item.updated_at } : {}),
  };
}

export function tabFromPayload(payload: unknown): TerminalTab | null {
  const direct = normalizeTab(payload);
  if (direct) return direct;
  const envelope = asRecord(payload);
  return normalizeTab(envelope?.tab ?? envelope?.terminal);
}

function terminalPath(tabId: string, suffix = '') {
  return `${TERMINALS_PATH}/${encodeURIComponent(tabId)}${suffix}`;
}

export const terminalApi = {
  async agents(workspaceRoot?: string, signal?: AbortSignal): Promise<TerminalAgentList> {
    const query = new URLSearchParams(workspaceRoot === undefined ? {} : { workspace_root: workspaceRoot });
    const payload = asRecord(await request(`${TERMINALS_PATH}/agents?${query}`, undefined, 5_000, signal));
    const agents = asRecord(payload?.agents);
    if (!agents) throw new Error('服务器返回了无效的终端 Agent 数据');
    return {
      agents: Object.fromEntries(Object.entries(agents).filter((entry): entry is [string, string | null] =>
        entry[1] === null || typeof entry[1] === 'string' && entry[1].length > 0)),
      titles: Object.fromEntries(Object.entries(asRecord(payload?.titles) ?? {})
        .filter((entry): entry is [string, string] => typeof entry[1] === 'string' && entry[1].trim().length > 0)),
      processes: Object.fromEntries(Object.entries(asRecord(payload?.processes) ?? {}).flatMap(([id, value]) => {
        const process = asRecord(value);
        return process && Number.isInteger(process.pid) && (process.pid as number) > 0
          && typeof process.start_time === 'string' && typeof process.cwd === 'string'
          ? [[id, process as unknown as TerminalAgentProcess]] : [];
      })),
    };
  },

  async paneSessions(tabId: string, paneId: string, signal?: AbortSignal): Promise<TerminalPaneSessions> {
    return await request(terminalPath(tabId, `/panes/${encodeURIComponent(paneId)}/agent-sessions`),
      { cache: 'no-store' }, 15_000, signal) as TerminalPaneSessions;
  },

  async host(tabId: string, paneId: string, taskId: string, revision: number, maxInputs: number): Promise<TerminalTab> {
    const tab = tabFromPayload(await request(terminalPath(tabId, `/panes/${encodeURIComponent(paneId)}/hosting`), {
      method: 'PUT', body: JSON.stringify({ task_id: taskId, revision, max_inputs: maxInputs }),
    }, 30_000));
    if (!tab) throw new Error('服务器返回了无效的托管状态');
    return tab;
  },

  async list(workspaceRoot?: string, signal?: AbortSignal): Promise<TerminalTab[]> {
    const query = new URLSearchParams(workspaceRoot === undefined ? {} : { workspace_root: workspaceRoot });
    const payload = await request(`${TERMINALS_PATH}?${query}`, undefined, 15_000, signal);
    const envelope = asRecord(payload);
    const values = Array.isArray(payload) ? payload : Array.isArray(envelope?.tabs) ? envelope.tabs : [];
    return values.map(normalizeTab).filter((tab): tab is TerminalTab => tab !== null);
  },

  async get(tabId: string, signal?: AbortSignal): Promise<TerminalTab> {
    try {
      const tab = tabFromPayload(await request(terminalPath(tabId), undefined, 15_000, signal));
      if (!tab) throw new Error('服务器返回了无效的终端数据');
      return tab;
    } catch (reason) {
      if (reason instanceof TerminalHttpError && reason.status === 404) throw new Error('该 Tab 已关闭或不存在。');
      throw reason;
    }
  },

  async create(workspaceRoot: string, options: { cwd: string; name?: string; agentId?: string; resumeSessionId?: string }): Promise<TerminalTab> {
    const payload = await request(TERMINALS_PATH, {
      method: 'POST',
      body: JSON.stringify({
        workspace_root: workspaceRoot,
        cwd: options.cwd,
        ...(options.name?.trim() ? { name: options.name.trim() } : {}),
        ...(options.agentId ? { agent_id: options.agentId } : {}),
        ...(options.resumeSessionId !== undefined ? { resume_session_id: options.resumeSessionId } : {}),
      }),
    });
    const tab = tabFromPayload(payload);
    if (!tab) throw new Error('服务器返回了无效的终端数据');
    return tab;
  },

  async rename(tabId: string, name: string): Promise<TerminalTab | null> {
    return tabFromPayload(await request(terminalPath(tabId), {
      method: 'PATCH',
      body: JSON.stringify({ name }),
    }));
  },

  async reorder(workspaceRoot: string, tabIds: string[]): Promise<TerminalTab[]> {
    const payload = await request(`${TERMINALS_PATH}/order`, {
      method: 'PUT',
      body: JSON.stringify({ workspace_root: workspaceRoot, tab_ids: tabIds }),
    });
    const envelope = asRecord(payload);
    const values = Array.isArray(payload) ? payload : Array.isArray(envelope?.tabs) ? envelope.tabs : [];
    return values.map(normalizeTab).filter((tab): tab is TerminalTab => tab !== null);
  },

  close(tabId: string): Promise<unknown> {
    return request(terminalPath(tabId), { method: 'DELETE' });
  },

  async rebuild(tabId: string): Promise<TerminalTab> {
    const tab = tabFromPayload(await request(terminalPath(tabId, '/rebuild'), { method: 'POST' }));
    if (!tab) throw new Error('服务器返回了无效的终端数据');
    return tab;
  },

  async split(
    tabId: string,
    targetPaneId: string,
    axis: TerminalSplitAxis,
    options?: { ratio?: number; cwd?: string; shell?: string },
  ): Promise<TerminalTab | null> {
    return tabFromPayload(await request(terminalPath(tabId, '/split'), {
      method: 'POST',
      body: JSON.stringify({
        target_pane_id: targetPaneId,
        axis,
        ...(options?.ratio === undefined ? {} : { ratio: options.ratio }),
        ...(options?.cwd ? { cwd: options.cwd } : {}),
        ...(options?.shell ? { shell: options.shell } : {}),
      }),
    }));
  },

  async closePane(tabId: string, paneId: string): Promise<TerminalTab | null> {
    const suffix = `/panes/${encodeURIComponent(paneId)}`;
    return tabFromPayload(await request(terminalPath(tabId, suffix), { method: 'DELETE' }));
  },

  async uploadClipboardImage(tabId: string, paneId: string, file: File, signal?: AbortSignal): Promise<{ path: string }> {
    const suffix = `/panes/${encodeURIComponent(paneId)}/clipboard-images`;
    const payload = await request(terminalPath(tabId, suffix), {
      method: 'POST',
      body: file,
      headers: { 'Content-Type': file.type || 'application/octet-stream' },
    }, 30_000, signal);
    const response = asRecord(payload);
    if (typeof response?.path !== 'string' || response.path.length === 0) {
      throw new Error('服务器返回了无效的图片路径');
    }
    return { path: response.path };
  },

  async updateLayout(tabId: string, layout: TerminalLayout, revision?: number | string): Promise<TerminalTab | null> {
    return tabFromPayload(await request(terminalPath(tabId, '/layout'), {
      method: 'PUT',
      body: JSON.stringify({ layout, ...(revision === undefined ? {} : { revision }) }),
    }));
  },

  webSocketUrl(tabId: string, paneId: string, resume?: { epoch: string; after: number }) {
    const url = new URL(terminalPath(tabId, `/panes/${encodeURIComponent(paneId)}/ws`), window.location.href);
    url.protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    url.searchParams.set('control', 'v2');
    // Full VT restores must only be sent to clients that understand the
    // accompanying snapshot geometry. Unknown query parameters are ignored
    // by older servers, which keeps rolling upgrades on the raw replay path.
    url.searchParams.set('capabilities', 'vt-snapshot-v1');
    // Ask newer terminald instances for a read-only stream when another
    // browser attachment already owns terminal input. Older servers ignore
    // this capability and retain their existing waiting behavior.
    url.searchParams.set('observer', 'v1');
    if (resume !== undefined) {
      if (!resume.epoch) throw new RangeError('终端续传 epoch 不能为空');
      if (!Number.isSafeInteger(resume.after) || resume.after < 0) throw new RangeError('终端续传位置必须是非负安全整数');
      url.searchParams.set('epoch', resume.epoch);
      url.searchParams.set('after', String(resume.after));
    }
    return url.toString();
  },

  resizeMessage(cols: number, rows: number) {
    return JSON.stringify({ type: 'resize', cols, rows });
  },

  claimMessage(force: boolean) {
    return JSON.stringify({ type: 'claim', force });
  },
};

import type { Terminal } from '@xterm/xterm';

// Some soft keyboards emit keydown + input without a usable keyCode or keypress.
// xterm 6 ignores that input while a key is down; recover only text it hasn't sent.
export function installMobileTerminalInput(terminal: Terminal): () => void {
  const host = terminal.element;
  const textarea = terminal.textarea;
  if (!host || !textarea) return () => {};

  let keydown: KeyboardEvent | undefined;
  let keyHandled = false;
  let composing = false;
  let compositionTimer: number | undefined;
  const keyEvent = terminal.onKey(() => { keyHandled = true; });
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.target !== textarea) return;
    keydown = event;
    keyHandled = false;
    // xterm's 229 fallback guesses textarea changes in a timer. A soft keyboard
    // may update it in a later task; use its actual input event instead.
    if (event.keyCode === 229 && !composing) event.stopImmediatePropagation();
  };
  const onKeyUp = () => { keydown = undefined; };
  const onCompositionStart = () => {
    window.clearTimeout(compositionTimer);
    composing = true;
  };
  const onCompositionEnd = () => {
    // xterm commits composition asynchronously after the textarea has updated.
    compositionTimer = window.setTimeout(() => { composing = false; }, 0);
  };
  const onBeforeInput = (event: Event) => {
    if (!(event instanceof InputEvent) || event.target !== textarea || (keydown && keyHandled) || composing || event.isComposing) return;
    const data = event.inputType === 'deleteContentBackward' ? '\x7f'
      : event.inputType === 'insertLineBreak' || event.inputType === 'insertParagraph' ? '\r' : undefined;
    if (!data) return;
    // beforeinput also fires for backspace when the hidden textarea is empty.
    event.preventDefault();
    event.stopImmediatePropagation();
    keyHandled = true;
    terminal.input(data, true);
  };
  const onInput = (event: Event) => {
    if (!(event instanceof InputEvent) || event.target !== textarea || !keydown || keyHandled || composing || event.isComposing
      || event.inputType !== 'insertText' || !event.data) return;
    event.stopImmediatePropagation();
    terminal.input(event.data, true);
  };
  host.addEventListener('keydown', onKeyDown, true);
  host.addEventListener('keyup', onKeyUp, true);
  host.addEventListener('blur', onKeyUp, true);
  host.addEventListener('compositionstart', onCompositionStart, true);
  host.addEventListener('compositionend', onCompositionEnd);
  host.addEventListener('beforeinput', onBeforeInput, true);
  host.addEventListener('input', onInput, true);

  return () => {
    window.clearTimeout(compositionTimer);
    keyEvent.dispose();
    host.removeEventListener('keydown', onKeyDown, true);
    host.removeEventListener('keyup', onKeyUp, true);
    host.removeEventListener('blur', onKeyUp, true);
    host.removeEventListener('compositionstart', onCompositionStart, true);
    host.removeEventListener('compositionend', onCompositionEnd);
    host.removeEventListener('beforeinput', onBeforeInput, true);
    host.removeEventListener('input', onInput, true);
  };
}

import type { Terminal } from '@xterm/xterm';

type CellPosition = [number, number] | undefined;
type DomRenderer = {
  renderRows(start: number, end: number): void;
  handleBlur(): void;
  handleSelectionChanged(start: CellPosition, end: CellPosition, column: boolean): void;
};

/** Keep native mobile input focus changes from rebuilding the entire terminal. */
export function installMobileTerminalRendering(terminal: Terminal): () => void {
  // xterm 6's DOM renderer redraws every row on blur and even empty selection
  // updates (a native click emits one). Its public API has no way to restrict
  // those repaints. Keep this compatibility shim local to the mobile DOM path;
  // fall back to normal rendering if a future xterm version changes its shape.
  const renderer = (terminal as Terminal & {
    _core?: { _renderService?: { _renderer?: { value?: Partial<DomRenderer> } } };
  })._core?._renderService?._renderer?.value;
  if (!terminal.element?.querySelector('.xterm-rows')
    || typeof renderer?.renderRows !== 'function'
    || typeof renderer.handleBlur !== 'function'
    || typeof renderer.handleSelectionChanged !== 'function') return () => {};

  const dom = renderer as DomRenderer;
  const originalBlur = dom.handleBlur;
  const originalSelection = dom.handleSelectionChanged;
  let renderedSelection = terminal.hasSelection();

  const limitRepaint = (action: () => void, cursorRow?: number) => {
    const renderRows = dom.renderRows;
    dom.renderRows = (start, end) => {
      if (cursorRow !== undefined && cursorRow >= 0 && cursorRow < terminal.rows
        && cursorRow >= start && cursorRow <= end) renderRows.call(dom, cursorRow, cursorRow);
    };
    try {
      action();
    } finally {
      dom.renderRows = renderRows;
    }
  };

  dom.handleBlur = () => {
    // Selected cells have different active/inactive colors; preserve their
    // normal repaint, including a selection whose clearing is still queued.
    if (renderedSelection || terminal.hasSelection()) {
      originalBlur.call(dom);
      return;
    }
    const buffer = terminal.buffer.active;
    limitRepaint(() => originalBlur.call(dom), buffer.baseY + buffer.cursorY - buffer.viewportY);
  };
  dom.handleSelectionChanged = (start, end, column) => {
    const hadSelection = renderedSelection;
    renderedSelection = !!(start && end && (start[0] !== end[0] || start[1] !== end[1]));
    const update = () => originalSelection.call(dom, start, end, column);
    // Still run xterm's selection bookkeeping, including clearing overlays.
    // Real selection changes and clearing an old highlight render normally.
    if (hadSelection || renderedSelection) update();
    else limitRepaint(update);
  };

  return () => {
    dom.handleBlur = originalBlur;
    dom.handleSelectionChanged = originalSelection;
  };
}

import type { TerminalLayout, TerminalPane, TerminalTab } from './types';

export function isCliTerminal(tab: TerminalTab) {
  return tab.panes.some(pane => pane.agent_terminal !== undefined);
}

export function terminalPaneAgent(pane: TerminalPane, detected: Record<string, string | null>) {
  if (pane.status !== 'running') return undefined;
  return Object.hasOwn(detected, pane.id) ? detected[pane.id]
    : pane.agent_id;
}

function agentTitle(pane: TerminalPane, detected: Record<string, string | null>, titles: Record<string, string>) {
  return pane.status === 'running' && terminalPaneAgent(pane, detected) ? titles[pane.id] : undefined;
}

export function defaultTerminalPaneName(pane: Pick<TerminalPane, 'cwd' | 'shell'>) {
  return pane.cwd.split(/[\\/]/).filter(Boolean).at(-1) || pane.cwd.trim()
    || pane.shell.split(/[\\/]/).filter(Boolean).at(-1) || 'Shell';
}

export function terminalPaneTitle(pane: TerminalPane, detected: Record<string, string | null>, titles: Record<string, string>) {
  return agentTitle(pane, detected, titles) || defaultTerminalPaneName(pane);
}

function orderedTerminalPanes(tab: TerminalTab) {
  const ordered: TerminalPane[] = [];
  const seen = new Set<string>();
  const add = (id: string) => {
    const pane = tab.panes.find((item) => item.id === id);
    if (pane && !seen.has(id)) { seen.add(id); ordered.push(pane); }
  };
  const visit = (layout: TerminalLayout | null) => {
    if (!layout) return;
    if (layout.type === 'pane') add(layout.pane_id);
    else { visit(layout.first); visit(layout.second); }
  };
  visit(tab.layout);
  tab.panes.forEach((pane) => add(pane.id));
  return ordered;
}

export function terminalTabPresentation(tab: TerminalTab, detected: Record<string, string | null>, titles: Record<string, string>) {
  const panes = orderedTerminalPanes(tab).map(pane => ({
    id: pane.id, title: terminalPaneTitle(pane, detected, titles), agentId: terminalPaneAgent(pane, detected),
  }));
  const agents = panes.filter(pane => pane.agentId);
  const agentCount = agents.length;
  const agentIds = new Set(agents.map(pane => pane.agentId));
  let title = tab.name;
  // Unknown naming intent (old servers) preserves the existing label.
  if (tab.name_is_custom === false) {
    if (agentCount > 1) title = `${agentCount} agents`;
    else if (agentCount === 1) {
      const pane = tab.panes.find(pane => pane.id === agents[0].id)!;
      title = agentTitle(pane, detected, titles) || tab.name;
    }
  }
  return { title, agentCount, agentId: agentIds.size === 1 ? agents[0].agentId : undefined, panes };
}

export type TerminalTabPresentation = ReturnType<typeof terminalTabPresentation>;

export interface TerminalDimensions { cols: number; rows: number }
export interface TerminalFrame extends TerminalDimensions { width: number; height: number; top: number; cursorRow: number }
export interface TerminalPaneControls {
  send: (text: string, paste?: boolean) => boolean;
  submit: (text: string) => boolean;
  takeControl: () => void;
  focus: () => void;
  scroll: (lines: number | 'bottom', point?: { clientX: number; clientY: number }) => void;
}

export function savedTerminalDimensions(pane: Pick<TerminalPane, 'cols' | 'rows'>): TerminalDimensions {
  const valid = (value: number | undefined) => Number.isInteger(value) && value! > 0 && value! <= 1000;
  return { cols: valid(pane.cols) ? pane.cols! : 80, rows: valid(pane.rows) ? pane.rows! : 24 };
}

export function flattenTerminalTabs(tabs: TerminalTab[], detected: Record<string, string | null> = {}, titles: Record<string, string> = {}) {
  return tabs.flatMap((tab) => {
    const ordered = orderedTerminalPanes(tab);
    return ordered.map((pane) => ({
      key: `${tab.id}:${pane.id}`, tab, pane,
      title: agentTitle(pane, detected, titles)
        || (ordered.length > 1 ? `${tab.name} · ${defaultTerminalPaneName(pane)}` : tab.name),
    }));
  });
}

export const terminalAccessoryKeys = [
  { label: 'Tab', data: '\t' }, { label: 'Enter', data: '\r' },
  { label: 'Shift+Tab', data: '\u001b[Z' }, { label: 'Space', data: ' ' },
  { label: 'Ctrl+C', data: '\u0003' }, { label: 'Esc', data: '\u001b' },
  { label: '↑', data: '\u001b[A' }, { label: '↓', data: '\u001b[B' },
  { label: '←', data: '\u001b[D' }, { label: '→', data: '\u001b[C' },
  { label: '⌫', data: '\u007f' }, { label: 'Ctrl+D', data: '\u0004' },
] as const;

import type { TerminalPaneSessions } from './types';
import type { AowAgentSession } from '../sessions/types';
import { agentSessionTitleSource, isAgentDisplayName } from '../agents/agentTypes';

const whitespace = (value: string) => value.replace(/\s+/gu, ' ').trim();
const decoration = /^[\s⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏●✳✶✻✽✢·]+|[\s⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏]+$/gu;
const status = /^(?:Ready|Working|Thinking|Waiting|Starting|Action required|Needs input)$/iu;

// Use raw OSC metadata, never the pane's user-defined label. Keep this key
// stable across activity frames so a spinner cannot reset a manual selection.
export function terminalSessionTitle(raw: string, cwd: string) {
  const project = cwd.replace(/\/+$/u, '').split('/').at(-1);
  const parts = whitespace(raw).replace(decoration, '')
    .replace(/^\[ [!.] \] Action Required\s*(?:\|\s*)?/iu, '').split(/\s+\|\s+/u)
    .map(part => part.replace(decoration, '').trim()).filter(Boolean);
  if (parts.at(-1) === project) parts.pop();
  return parts.filter(part => !status.test(part) && !isAgentDisplayName(part)).join(' | ');
}

export function terminalSessionCandidates(data: TerminalPaneSessions) {
  const title = terminalSessionTitle(data.title, data.cwd);
  const sessions = data.sessions.filter(session => session.agent === data.agent);
  // A native session identity takes precedence even if no transcript has
  // been written yet. Do not silently open an unrelated title match then.
  if (data.live_session_id) {
    const exact = sessions.find(session => session.session_id === data.live_session_id);
    return { title, matches: exact ? [exact] : [], automatic: exact };
  }
  // Display-only titles cannot identify a session without native evidence.
  if (agentSessionTitleSource(data.agent) === 'native') return { title, matches: [], automatic: undefined };
  const sameDirectory = sessions.filter(session => session.cwd.replace(/\/+$/u, '') === data.cwd.replace(/\/+$/u, ''));
  const exact = title ? sameDirectory.filter(session => whitespace(session.title) === title) : [];
  const prefix = title.replace(/(?:\.\.\.|…)$/u, '');
  const truncated = prefix !== title && Array.from(prefix).length >= 8;
  const matches = truncated
    ? sameDirectory.filter(session => whitespace(session.title).startsWith(prefix)) : exact;
  return { title, matches, automatic: data.process && !truncated && exact.length === 1 ? exact[0] : undefined };
}

export function sessionSearch(sessions: AowAgentSession[], query: string) {
  const needle = whitespace(query).toLocaleLowerCase();
  return sessions.filter(session => `${session.title} ${session.session_id}`.toLocaleLowerCase().includes(needle));
}

import type { TerminalPane, TerminalTab } from './types';

export const terminalLifecycleLabels = {
  starting: '初始化中', running: '运行中', failed: '启动失败',
  exited: '已退出', interrupted: '已中断', closed: '已关闭',
} as const;
export type TerminalLifecycle = keyof typeof terminalLifecycleLabels;
export const terminalDisplayLabels = { shown: '已显示', hidden: '已隐藏' } as const;
export const terminalControlLabels = { controlled: '已接管', observing: '旁观中', disconnected: '未连接' } as const;
export type TerminalControl = keyof typeof terminalControlLabels;

// Emulator attachment progress includes replaying a finished process. UI control
// state is derived separately and never treats that replay as taking control.
export type TerminalConnectionState = 'connecting' | 'connected' | 'observing' | 'waiting' | 'disconnected' | 'exited' | 'interrupted';

const connectionLabels: Record<TerminalConnectionState, string> = {
  connecting: '连接中', connected: terminalControlLabels.controlled, observing: terminalControlLabels.observing,
  waiting: '此终端正在其他窗口使用', disconnected: '连接中断',
  exited: terminalLifecycleLabels.exited, interrupted: terminalLifecycleLabels.interrupted,
};

export function terminalPaneLifecycle(pane: TerminalPane): TerminalLifecycle {
  if (pane.status !== 'running') return pane.status;
  const phase = pane.agent_terminal?.phase;
  return phase === 'starting' || phase === 'failed' ? phase : 'running';
}

export function terminalTabLifecycle(tab: TerminalTab): TerminalLifecycle {
  const states = tab.panes.map(terminalPaneLifecycle);
  // Prefer live panes over finished ones, independent of pane order. Report an
  // interruption rather than a normal exit once every pane has finished.
  return (['running', 'starting', 'failed', 'interrupted', 'exited'] as const)
    .find(state => states.includes(state)) ?? 'closed';
}

export function terminalPaneControl(pane: TerminalPane, connection?: TerminalConnectionState): TerminalControl {
  if (pane.status !== 'running') return 'disconnected';
  return connection === 'connected' ? 'controlled' : connection === 'observing' ? 'observing' : 'disconnected';
}

export function terminalTabState(tab: TerminalTab, opened: boolean, connection: (paneId: string) => TerminalConnectionState | undefined) {
  const panes = tab.panes.map(pane => ({ pane, connection: connection(pane.id) }));
  const controls = panes.map(({ pane, connection }) => terminalPaneControl(pane, connection));
  return {
    lifecycle: terminalTabLifecycle(tab),
    // Opened means a tab exists, even when it is in the background or disconnected.
    display: opened || panes.some(pane => pane.connection !== undefined) ? 'shown' : 'hidden',
    control: controls.includes('controlled') ? 'controlled' : controls.includes('observing') ? 'observing' : 'disconnected',
  } as const;
}

export function terminalPaneStatusMessage(pane: TerminalPane, connection: TerminalConnectionState, message?: string) {
  // A stream can report exit before the parent's process snapshot is updated.
  const lifecycle = connection === 'exited' || connection === 'interrupted' ? connection : terminalPaneLifecycle(pane);
  if (lifecycle === 'exited' || lifecycle === 'interrupted') return terminalLifecycleLabels[lifecycle];
  const detail = message || connectionLabels[connection];
  if (lifecycle === 'starting') return `${terminalLifecycleLabels[lifecycle]} · ${detail}`;
  if (lifecycle === 'failed') return `${terminalLifecycleLabels[lifecycle]} · ${detail} · ${pane.agent_terminal?.error || '请查看终端输出'}`;
  return detail;
}

import { useEffect, useSyncExternalStore } from 'react';
import type { TerminalTab } from './types';
import { terminalTabState, type TerminalConnectionState } from './terminalState';

// Browser-local view state is independent of the terminal process lifecycle.
// Sharing it here also covers tabs displayed in another worktree or a portal.
const listeners = new Set<() => void>();
let connections: ReadonlyMap<string, TerminalConnectionState> = new Map();
const paneKey = (tabId: string, paneId: string) => JSON.stringify([tabId, paneId]);
const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
};
const snapshot = () => connections;

function update(key: string, state?: TerminalConnectionState) {
  if (connections.get(key) === state) return;
  const next = new Map(connections);
  if (state === undefined) next.delete(key);
  else next.set(key, state);
  connections = next;
  for (const listener of listeners) listener();
}

export function usePublishTerminalConnection(tabId: string, paneId: string, state: TerminalConnectionState) {
  const key = paneKey(tabId, paneId);
  useEffect(() => { update(key, state); }, [key, state]);
  useEffect(() => () => update(key), [key]);
}

export function useTerminalStates() {
  const current = useSyncExternalStore(subscribe, snapshot);
  return (tab: TerminalTab, opened: boolean) => terminalTabState(tab, opened, paneId => current.get(paneKey(tab.id, paneId)));
}

