import { appUrl } from './basePath';

class AowHttpError extends Error {}

export async function aowRequest<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(appUrl(url), {
    ...init,
    headers: init?.body === undefined
      ? init?.headers
      : { 'Content-Type': 'application/json', ...init.headers },
  });
  const payload = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) {
    const message = payload && typeof payload === 'object' && 'message' in payload
      ? String(payload.message)
      : `HTTP ${response.status}`;
    throw new AowHttpError(message);
  }
  return payload as T;
}

// Supplied by the web server before any module runs. Vite development/test
// pages have no metadata and keep using the root deployment.
export const basePath = typeof document === 'undefined' ? ''
  : document.querySelector<HTMLMetaElement>('meta[name="aow-base-path"]')?.content ?? '';

/** Convert a root-relative application URL into a deployment URL, exactly once. */
export function appUrl(path: string): string {
  if (!path.startsWith('/') || path.startsWith('//')) throw new Error('Expected a root-relative application URL');
  return basePath + path;
}

export function appPath(pathname: string): string | undefined {
  if (!basePath) return pathname;
  if (pathname === basePath) return '/';
  return pathname.startsWith(basePath + '/') ? pathname.slice(basePath.length) : undefined;
}

export const appBaseUrl = () => window.location.origin + basePath;

// Preserve existing root-deployment state; isolate subpath deployments on the
// same origin. This is namespacing, not a security boundary between sites.
export const storageKey = (key: string) => basePath ? `aow@${basePath}:${key}` : key;
function scopedStorage(kind: 'localStorage' | 'sessionStorage') {
  return {
    getItem: (key: string) => window[kind].getItem(storageKey(key)),
    setItem: (key: string, value: string) => window[kind].setItem(storageKey(key), value),
    removeItem: (key: string) => window[kind].removeItem(storageKey(key)),
  };
}
export const appLocalStorage = scopedStorage('localStorage');
export const appSessionStorage = scopedStorage('sessionStorage');

import { appUrl } from './basePath';

export class HttpRequestError extends Error {}

export async function fetchWithTimeout(url: string, init?: RequestInit, timeoutMs = 12_000) {
  const controller = new AbortController();
  const signal = init?.signal ? AbortSignal.any([init.signal, controller.signal]) : controller.signal;
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(appUrl(url), { ...init, signal });
  } catch (error) {
    init?.signal?.throwIfAborted();
    if (error instanceof DOMException && error.name === 'AbortError') {
      throw new Error(`请求超时（${Math.round(timeoutMs / 1000)} 秒）`);
    }
    throw error;
  } finally {
    window.clearTimeout(timer);
  }
}

export async function request<T>(url: string, init?: RequestInit, retries = 1, timeoutMs = 12_000): Promise<T> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      init?.signal?.throwIfAborted();
      const response = await fetchWithTimeout(url, init, timeoutMs);
      const payload = await response.json().catch(() => null);
      init?.signal?.throwIfAborted();
      if (!response.ok) {
        throw new HttpRequestError(payload?.message ?? payload?.error?.message ?? `HTTP ${response.status}`);
      }
      return payload as T;
    } catch (error) {
      init?.signal?.throwIfAborted();
      if (error instanceof HttpRequestError || attempt >= retries) throw error;
      await new Promise((resolve) => window.setTimeout(resolve, 250));
    }
  }
}

import { appUrl } from './basePath';

type EventName = 'workspace' | 'operations' | 'task-stopped';
const subscribers = new Set<LiveEvents>();
const snapshots = new Map<EventName, string>();
let socket: WebSocket | undefined;
let retry: ReturnType<typeof setTimeout> | undefined;
let connecting: ReturnType<typeof setTimeout> | undefined;
let attempts = 0;
let denied = false;

function connect() {
  if (socket || !subscribers.size || denied) return;
  clearTimeout(retry);
  retry = undefined;
  const url = new URL(appUrl('/api/events/ws'), window.location.href);
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  let current: WebSocket;
  try { current = new WebSocket(url); }
  catch { disconnected(); return; }
  socket = current;
  connecting = setTimeout(() => current.close(), 10_000);
  current.onopen = () => {
    if (socket !== current) return;
    clearTimeout(connecting);
    attempts = 0;
    for (const listener of subscribers) listener.open();
  };
  current.onmessage = event => {
    if (socket !== current || typeof event.data !== 'string') return;
    let envelope: { event?: EventName; data?: unknown };
    try { envelope = JSON.parse(event.data); } catch { return; }
    if (!envelope || !['workspace', 'operations', 'task-stopped'].includes(envelope.event ?? '') || envelope.data === undefined) return;
    const name = envelope.event!;
    const data = JSON.stringify(envelope.data);
    // State snapshots may be replayed to late subscribers; notifications never are.
    if (name !== 'task-stopped') snapshots.set(name, data);
    for (const listener of subscribers) if (listener.name === name) listener.receive(data);
  };
  current.onerror = () => current.close();
  current.onclose = event => {
    if (socket !== current) return;
    socket = undefined;
    denied = event.code === 1008;
    disconnected();
  };
}

function disconnected() {
  clearTimeout(connecting);
  snapshots.clear();
  for (const listener of subscribers) listener.failed();
  if (subscribers.size && !denied) {
    retry = setTimeout(connect, Math.min(30_000, 1000 * 2 ** Math.min(attempts++, 5)));
  }
}

function resume() {
  if (document.visibilityState === 'visible') connect();
}

function reconcile() {
  if (subscribers.size) { connect(); return; }
  clearTimeout(retry);
  clearTimeout(connecting);
  const previous = socket;
  socket = undefined;
  previous?.close();
  snapshots.clear();
  attempts = 0;
  denied = false;
  window.removeEventListener('online', resume);
  document.removeEventListener('visibilitychange', resume);
}

/** EventSource-like subscriptions sharing one WebSocket per page, outside the HTTP pool. */
export class LiveEvents extends EventTarget {
  static readonly OPEN = 1;
  readyState = 0;
  onopen: (() => void) | null = null;
  onerror: (() => void) | null = null;
  private closed = false;

  constructor(readonly name: EventName) {
    super();
    if (!subscribers.size) {
      window.addEventListener('online', resume);
      document.addEventListener('visibilitychange', resume);
    }
    subscribers.add(this);
    queueMicrotask(() => {
      if (this.closed) return;
      if (socket?.readyState === WebSocket.OPEN) {
        this.open();
        const cached = snapshots.get(name);
        if (cached !== undefined) this.receive(cached);
      } else { connect(); }
    });
  }

  open() {
    if (this.closed) return;
    this.readyState = LiveEvents.OPEN;
    this.onopen?.();
  }

  receive(data: string) {
    if (!this.closed) this.dispatchEvent(new MessageEvent(this.name, { data }));
  }

  failed() {
    if (this.closed) return;
    this.readyState = denied ? 2 : 0;
    this.onerror?.();
  }

  close() {
    this.closed = true;
    this.readyState = 2;
    subscribers.delete(this);
    // React StrictMode and section switches may replace subscriptions in one turn.
    queueMicrotask(reconcile);
  }
}

export interface TokenUsage {
  input_tokens: number;
  output_tokens: number;
  cached_input_tokens: number;
  cache_write_input_tokens: number;
  reasoning_output_tokens: number;
  total_tokens: number;
}

export function parseTokenUsage(value: unknown): TokenUsage | undefined {
  if (!value || typeof value !== 'object') return;
  const data = value as Record<string, unknown>;
  const count = (key: keyof TokenUsage, optional = false) => {
    const value = data[key] ?? (optional ? 0 : undefined);
    return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : undefined;
  };
  const input_tokens = count('input_tokens');
  const output_tokens = count('output_tokens');
  const total_tokens = count('total_tokens');
  const cached_input_tokens = count('cached_input_tokens', true);
  const cache_write_input_tokens = count('cache_write_input_tokens', true);
  const reasoning_output_tokens = count('reasoning_output_tokens', true);
  if (input_tokens === undefined || output_tokens === undefined || total_tokens === undefined
    || cached_input_tokens === undefined || cache_write_input_tokens === undefined || reasoning_output_tokens === undefined) return;
  return { input_tokens, output_tokens, total_tokens, cached_input_tokens, cache_write_input_tokens, reasoning_output_tokens };
}

const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 });
const exact = new Intl.NumberFormat('en-US');

export const formatTokenCount = (count: number) => `${compact.format(count)} tokens`;
export const tokenUsageLabel = (usage: TokenUsage) => `本轮 ${formatTokenCount(usage.total_tokens)}`;

export function tokenUsageDetails(usage: TokenUsage): string {
  const details = [
    `本轮：${exact.format(usage.total_tokens)} tokens`,
    `输入：${exact.format(usage.input_tokens)}`,
    `输出：${exact.format(usage.output_tokens)}`,
    `缓存命中（包含在输入中）：${exact.format(usage.cached_input_tokens)}`,
  ];
  if (usage.cache_write_input_tokens) details.push(`缓存写入（包含在输入中）：${exact.format(usage.cache_write_input_tokens)}`);
  if (usage.reasoning_output_tokens) details.push(`推理（包含在输出中）：${exact.format(usage.reasoning_output_tokens)}`);
  return details.join('\n');
}

import { LiveEvents } from './liveEvents';

interface Snapshot {
  boot_id: string;
  revision: number;
  projects: number;
  terminals: number;
  inbox?: number;
  repositories: Record<string, number>;
}

export interface WorkspaceChange {
  reset: boolean;
  projects: boolean;
  terminals: boolean;
  inbox: boolean;
  repositories: ReadonlySet<string>;
}

type Listener = (change: WorkspaceChange) => void;
const listeners = new Set<Listener>();
let source: LiveEvents | undefined;
let fallback: ReturnType<typeof setInterval> | undefined;
let scheduled = false;

function dispatch(change: WorkspaceChange) {
  for (const listener of [...listeners]) listener(change);
}

function reset() {
  dispatch({ reset: true, projects: true, terminals: true, inbox: true, repositories: new Set() });
}

// All registered projects are watched by the server. Changing worktrees does
// not change subscriptions or reconnect this shared browser connection.
function connect() {
  scheduled = false;
  if (source && listeners.size) return;
  source?.close();
  source = undefined;
  clearInterval(fallback);
  fallback = undefined;
  if (!listeners.size) return;
  const connection = new LiveEvents('workspace');
  source = connection;
  let previous: Snapshot | undefined;
  let reconnected = true;
  connection.onopen = () => { reconnected = true; };
  connection.addEventListener('workspace', event => {
    if (source !== connection) return;
    let next: Snapshot;
    try { next = JSON.parse((event as MessageEvent<string>).data); } catch { return; }
    if (!next || typeof next.boot_id !== 'string' || !Number.isSafeInteger(next.revision)
      || !Number.isSafeInteger(next.projects) || !Number.isSafeInteger(next.terminals)
      || !next.repositories || typeof next.repositories !== 'object') return;
    if (previous?.boot_id === next.boot_id && previous.revision > next.revision) return;
    clearInterval(fallback);
    fallback = undefined;
    const changed: WorkspaceChange = {
      reset: reconnected || !previous || previous.boot_id !== next.boot_id,
      projects: previous?.projects !== next.projects,
      terminals: previous?.terminals !== next.terminals,
      inbox: previous?.inbox !== next.inbox,
      repositories: new Set(Object.keys(next.repositories).filter(root => previous?.repositories[root] !== next.repositories[root])),
    };
    previous = next;
    reconnected = false;
    dispatch(changed);
  });
  connection.onerror = () => {
    if (source !== connection || fallback) return;
    // Only degraded connections poll. Healthy connections never poll history.
    fallback = setInterval(() => { if (document.visibilityState === 'visible') reset(); }, 30_000);
  };
}

function scheduleConnection() {
  if (scheduled) return;
  scheduled = true;
  queueMicrotask(connect);
}

export function subscribeWorkspaceChanges(listener: Listener): () => void {
  listeners.add(listener);
  scheduleConnection();
  return () => { listeners.delete(listener); scheduleConnection(); };
}

