.confirmation-dialog::backdrop { background:#0008; }
.confirmation-dialog > header { min-height:32px; padding:4px 6px 4px 12px; }
.confirmation-dialog h2 { flex:1; margin:0; color:var(--aow-text-strong); font-size:12px; font-weight:600; line-height:1.5; }
.confirmation-dialog > header > button { flex:0 0 22px; width:22px; height:22px; color:var(--aow-icon-foreground, var(--aow-icon)); cursor:pointer; }
.confirmation-dialog > header > button svg { width:13px; height:13px; color:inherit; }
.confirmation-body { min-height:0; padding:10px 12px; overflow:auto; }
.confirmation-body > p { margin:0; color:var(--aow-text); line-height:1.5; overflow-wrap:anywhere; }
.confirmation-items { max-height:144px; margin:8px 0 0; padding:0; overflow:auto; list-style:none; background:#1b1f25; border:1px solid #383f49; border-radius:3px; }
.confirmation-items li { min-height:24px; display:flex; align-items:center; gap:6px; padding:4px 8px; }
.confirmation-items li + li { border-top:1px solid #303640; }
.confirmation-items li > svg { flex:0 0 14px; width:14px; height:14px; color:var(--aow-icon-foreground, var(--aow-icon)); }
.confirmation-items li > .agent-icon { flex:0 0 14px; width:14px; height:14px; }
.confirmation-items li > div { min-width:0; display:flex; flex-direction:column; gap:1px; }
.confirmation-items strong { color:var(--aow-text-strong); font-size:11px; font-weight:500; line-height:16px; overflow-wrap:anywhere; }
.confirmation-items span { color:var(--aow-muted); font:10px/1.4 ui-monospace,monospace; overflow-wrap:anywhere; }
.confirmation-warning { display:flex; align-items:flex-start; gap:6px; margin-top:8px; color:#c8a77d; }
.confirmation-warning > svg { flex:0 0 13px; width:13px; height:13px; margin-top:2px; color:#d4a46d; }
.confirmation-warning p { margin:0; font-size:11px; line-height:1.5; }
.confirmation-dialog > footer { flex:0 0 auto; gap:6px; margin:0; padding:7px 12px; background:#1e2228; border-top:1px solid #3b414b; }
.confirmation-dialog > footer button { min-height:24px; justify-content:center; padding:3px 9px; border-radius:3px; font-size:11px; line-height:16px; cursor:pointer; }
.confirmation-dialog > footer button.danger { color:var(--aow-text-hover); background:#a6443e; border-color:#be554d; }
.confirmation-dialog > footer button.danger:hover { background:#ba4d45; border-color:#d2665c; }
.confirmation-dialog button:focus-visible { outline:1px solid #80afe9; outline-offset:2px; }
.editor-file-notice > svg,.project-aow-snapshot-header .warning > svg,.project-aow-snapshot-state.error > svg,.project-aow-agent-row > button > svg,.project-aow-onboarding > button > svg,.project-aow-tab-away > button > svg { color:inherit; }
.tree-row:hover:not(:disabled) .tree-label,.commit-row:hover .commit-subject,.editor-tabs button:hover:not(:disabled),.project-aow-sidebar-footer button:hover:not(:disabled) > span { color:var(--aow-text-hover); }
.markdown-preview a,.project-aow-snapshot-markdown a { color:var(--aow-link); }
.markdown-preview a:hover,.project-aow-snapshot-markdown a:hover,.worktree-cleanup-result > button:hover:not(:disabled) { color:var(--aow-link-hover); }
.project-aow-dialog .project-aow-command-preview summary:hover { color:var(--aow-text-hover); }

/// <reference types="vite/client" />

interface Window {
  MonacoEnvironment?: {
    getWorker(moduleId: string, label: string): Worker;
  };
  requestIdleCallback?(callback: () => void, options?: { timeout?: number }): number;
  cancelIdleCallback?(handle: number): void;
}
